registrarDetalhes({"ES-001":{"cognitivo":{"motivo":"Propriedade comparativa média × mediana — conceito central da estatística descritiva.","palavraCritica":"não é influenciada pela magnitude"},"comentario":{"resolucao":"CERTO. A mediana é medida de posição baseada na ordem dos dados: valores extremos alteram no máximo qual observação ocupa o centro, mas não 'puxam' o resultado pela sua magnitude. A média, por incorporar todos os valores no numerador, é sensível a outliers.","fundamento":"Estatística descritiva — propriedades das medidas de tendência central.","macete":"Renda de bairro com um milionário: média mente, mediana conta a verdade.","erroComum":"Marcar E por achar que 'robusta' teria sentido técnico diverso.","comoBancaPensa":"Compara duas medidas irmãs — o formato favorito para futuras inversões."}},"ES-002":{"cognitivo":{"motivo":"O erro inferencial mais clássico da estatística aplicada.","palavraCritica":"correlação ≠ causalidade"},"comentario":{"resolucao":"ERRADO. O coeficiente de Pearson mede apenas a força e o sentido da associação linear entre variáveis. Correlação elevada não autoriza conclusão de causalidade: pode haver terceira variável influenciando ambas, relação inversa ou mero acaso. Causalidade exige desenho de estudo adequado (experimentos, controles).","fundamento":"Estatística — interpretação do coeficiente de correlação.","macete":"Pearson mostra a dança, não diz quem conduz.","erroComum":"Concluir 'X causa Y' de um r alto.","comoBancaPensa":"Frase tecnicamente vestida escondendo o salto lógico proibido."}},"ES-003":{"cognitivo":{"motivo":"Regra 68-95-99,7, item expresso do edital (2.27).","palavraCritica":"±2σ ↔ 95%"},"comentario":{"resolucao":"CERTO. Pela regra empírica da distribuição normal: cerca de 68% dos dados estão a ±1 desvio-padrão da média, 95% a ±2 e 99,7% a ±3. A assertiva pareia corretamente 95% com dois desvios.","fundamento":"Estatística — regra empírica (três sigmas) da distribuição normal.","macete":"Sequência mágica: 68 → 95 → 99,7.","erroComum":"Atribuir 95% a ±1σ ou 99% a ±2σ.","comoBancaPensa":"Três pares numéricos fixos = questão de conferência direta, feita para trocas."}},"ES-004":{"cognitivo":{"motivo":"Utilidade prática do CV — comparação entre séries heterogêneas.","palavraCritica":"desvio ÷ média"},"comentario":{"resolucao":"CERTO. CV = desvio-padrão ÷ média (frequentemente ×100). Por ser a razão de duas grandezas na mesma unidade, é adimensional — ideal para comparar variabilidades de variáveis com médias ou unidades distintas (ex.: dispersão de salários × dispersão de idades).","fundamento":"Estatística descritiva — medidas de dispersão relativa.","macete":"Quem tem maior CV é mais heterogêneo, não importa a unidade.","erroComum":"Inverter numerador e denominador da razão.","comoBancaPensa":"Definição + utilidade na mesma frase: dupla oportunidade de troca em provas futuras."}},"ES-005":{"cognitivo":{"motivo":"Definição formal de independência — base para Bayes e distribuições.","palavraCritica":"P(A∩B) = P(A)·P(B)"},"comentario":{"resolucao":"CERTO. A definição de independência é exatamente P(A∩B) = P(A)×P(B) — equivalente a P(A|B) = P(A). Não confundir com eventos mutuamente excludentes, em que P(A∩B) = 0.","fundamento":"Teoria da probabilidade — axiomas e independência.","macete":"Independente multiplica; excludente soma (na união) e zera (na interseção).","erroComum":"Tratar 'não podem ocorrer juntos' como sinônimo de independência.","comoBancaPensa":"Definições vizinhas e trocáveis — decorou uma, a banca cobra a fronteira entre as duas."}},"ES-006":{"cognitivo":{"motivo":"Inversão espelhada das duas técnicas de amostragem por grupos.","palavraCritica":"de cada estrato × grupos inteiros"},"comentario":{"resolucao":"ERRADO. Está invertido. Na amostragem ESTRATIFICADA, dividem-se os elementos em estratos homogêneos e sorteiam-se elementos DENTRO DE CADA estrato. Na amostragem POR CONGLOMERADOS, sorteiam-se conglomerados (grupos) inteiros e examinam-se seus integrantes.","fundamento":"Técnicas de amostragem probabilística.","macete":"Pesquisa por bairros sorteando QUARTEIRÕES inteiros = conglomerado. Garantindo homens E mulheres na amostra = estrato.","erroComum":"Aceitar o item porque as duas mecânicas 'existem'.","comoBancaPensa":"Par espelhado de procedimentos — o mesmo molde de DA-005 e DH-005."}},"ES-007":{"cognitivo":{"motivo":"Definição nuclear de α — item 3.3 do edital.","palavraCritica":"rejeitar H0 verdadeira"},"comentario":{"resolucao":"CERTO. O nível de significância (α) é, por definição, a probabilidade máxima tolerada de erro tipo I — rejeitar a hipótese nula sendo ela verdadeira. O erro tipo II (β) é o oposto: não rejeitar H0 falsa; a potência do teste é 1−β.","fundamento":"Inferência estatística — teoria dos testes de hipóteses.","macete":"α vem primeiro no alfabeto e no tipo de erro: tipo I.","erroComum":"Definir α como 'probabilidade de a hipótese ser verdadeira' (interpretação incorreta).","comoBancaPensa":"Dupla de erros espelhados (I × II) = próxima inversão já contratada."}},"ES-008":{"cognitivo":{"motivo":"Conceito central de avaliação de modelos — item 4 de Análise de Dados.","palavraCritica":"ótimo no treino, ruim no novo"},"comentario":{"resolucao":"CERTO. Overfitting é o sobreajuste: o modelo captura ruído e idiossincrasias do conjunto de treinamento, minimizando o erro ali, mas com erro elevado em dados não vistos (baixa generalização). Mitigações: regularização, validação cruzada, mais dados, simplificação do modelo.","fundamento":"Machine learning — viés × variância, validação de modelos.","macete":"Treino 99%, produção 60% = cheiro clássico de overfitting.","erroComum":"Chamar de overfitting o modelo que já erra no próprio treino (isso é underfitting).","comoBancaPensa":"Par over/under = mais um espelho pronto para inversão em prova."}},"ES-009":{"cognitivo":{"motivo":"Fronteira supervisionado × não supervisionado — base da mineração de dados.","palavraCritica":"não supervisionado"},"comentario":{"resolucao":"ERRADO. A clusterização é técnica de aprendizado NÃO SUPERVISIONADO: agrupa observações por similaridade sem qualquer rótulo prévio (ex.: k-means agrupando ocorrências criminais por padrão espacial). Quem exige dados rotulados é a classificação (supervisionada), como o Naive Bayes.","fundamento":"Mineração de dados — paradigmas de aprendizado.","macete":"Tem gabarito no treino? Supervisionado. Não tem? Cluster/associação.","erroComum":"Rotular toda mineração como supervisionada.","comoBancaPensa":"Vocabulário técnico do edital novo — quem só decorou nomes cai na troca de paradigma."}},"ES-010":{"cognitivo":{"motivo":"Cobrar o conceito e a aplicação do teorema de Bayes.","palavraCritica":"atualizar à luz de nova evidência"},"comentario":{"resolucao":"CERTO. O teorema de Bayes atualiza a crença sobre uma hipótese H após observar a evidência E: P(H|E) = P(E|H)·P(H)/P(E). Combina a probabilidade a priori P(H) com a verossimilhança P(E|H) para obter a probabilidade a posteriori. É base de raciocínio investigativo e de modelos como o Naive Bayes.","fundamento":"Teoria da probabilidade — teorema de Bayes.","macete":"Bayes = 'revisar a aposta' quando surge uma pista nova.","erroComum":"Inverter a priori (antes) com a posteriori (depois).","comoBancaPensa":"Bayes é citado nominalmente no edital — cobrança conceitual e aplicada."}},"ES-011":{"cognitivo":{"motivo":"Cobrar o enunciado do Teorema Central do Limite.","palavraCritica":"independentemente da distribuição da população"},"comentario":{"resolucao":"CERTO. O Teorema Central do Limite afirma que a distribuição da média amostral tende à normal conforme n cresce, qualquer que seja a distribuição da população de origem (com média e variância finitas). É o que fundamenta a inferência sobre médias.","fundamento":"Estatística — Teorema Central do Limite.","macete":"TCL = 'com amostra grande, a média vira normal', não importa a população.","erroComum":"Exigir população normal (o TCL dispensa isso).","comoBancaPensa":"A independência em relação à distribuição populacional é o ponto-chave manipulado."}},"ES-012":{"cognitivo":{"motivo":"Distinguir aprendizado supervisionado de não supervisionado.","palavraCritica":"clusterização = não supervisionado"},"comentario":{"resolucao":"CERTO. A clusterização (análise de agrupamentos) é aprendizado NÃO supervisionado: agrupa observações semelhantes sem rótulos prévios. Já a classificação e a regressão são supervisionadas (usam dados rotulados/variável-alvo conhecida).","fundamento":"Fundamentos de machine learning — paradigmas de aprendizado.","macete":"Cluster = descobre grupos (sem rótulo). Classificação = prevê rótulo (supervisionado).","erroComum":"Trocar clusterização (não supervisionado) por classificação (supervisionado).","comoBancaPensa":"Paradigmas de aprendizado são cobrados trocando as técnicas."}},"ES-013":{"cognitivo":{"motivo":"Cobrar o conceito de overfitting e o papel da regularização.","palavraCritica":"ajuste excessivo ao treino / piora a generalização"},"comentario":{"resolucao":"CERTO. No overfitting, o modelo memoriza o ruído dos dados de treino e generaliza mal em dados novos (bom no treino, ruim no teste). A regularização (ex.: L1/L2), a validação cruzada e mais dados ajudam a mitigar. O oposto é o underfitting (modelo simples demais).","fundamento":"Machine learning — viés/variância, overfitting, regularização.","macete":"Overfitting = decorou; underfitting = não aprendeu. Regularização controla a complexidade.","erroComum":"Inverter overfitting com underfitting.","comoBancaPensa":"Par overfitting × underfitting é cobrado por inversão."}},"ES-014":{"cognitivo":{"motivo":"Cobrar a sequência de fases do CRISP-DM.","palavraCritica":"preparação de dados = fase mais custosa"},"comentario":{"resolucao":"CERTO. O CRISP-DM tem seis fases: entendimento do negócio, entendimento dos dados, preparação dos dados, modelagem, avaliação e implantação. O entendimento do negócio antecede a preparação, e esta costuma ser a etapa mais demorada do processo.","fundamento":"Metodologia CRISP-DM (mineração de dados).","macete":"Ordem: Negócio → Dados → Preparação → Modelagem → Avaliação → Implantação.","erroComum":"Inverter a ordem das fases.","comoBancaPensa":"Sequência de fases é cobrada por troca de ordem."}},"ES-015":{"cognitivo":{"motivo":"Cobrar a diferença entre média e mediana e o efeito da assimetria.","palavraCritica":"sempre"},"comentario":{"resolucao":"ERRADO. Média e mediana só coincidem em distribuições simétricas. Em conjuntos assimétricos (ou com valores extremos), elas diferem — a média é influenciada por outliers, ao passo que a mediana é resistente a eles.","fundamento":"Estatística descritiva — medidas de posição.","macete":"Salário com um bilionário na sala: a média dispara, a mediana quase não muda.","erroComum":"Achar que média e mediana são sempre iguais.","comoBancaPensa":"Termo absoluto ('sempre') aplicado a conceito que depende da simetria."}},"ES-016":{"cognitivo":{"motivo":"Cobrar a natureza não negativa do desvio padrão.","palavraCritica":"negativos"},"comentario":{"resolucao":"ERRADO. O desvio padrão é a raiz quadrada da variância, calculada a partir de desvios ELEVADOS AO QUADRADO; portanto, é sempre maior ou igual a zero, independentemente de os dados estarem acima ou abaixo da média. Só é zero quando não há variação.","fundamento":"Estatística descritiva — variância e desvio padrão.","macete":"Quadrado não é negativo → dispersão não é negativa.","erroComum":"Associar 'dados abaixo da média' a desvio negativo.","comoBancaPensa":"Cria uma propriedade impossível para a medida de dispersão."}},"ES-017":{"cognitivo":{"motivo":"Distinguir amostragem aleatória simples da estratificada.","palavraCritica":"probabilidade distinta (deveria ser igual)"},"comentario":{"resolucao":"ERRADO. Na amostragem aleatória simples, todos os elementos da população têm IGUAL probabilidade de seleção. A menção a 'estratos mais representativos' descreve a amostragem estratificada, técnica distinta.","fundamento":"Estatística — técnicas de amostragem.","macete":"Simples = igual chance. Estratificada = por grupos (estratos).","erroComum":"Trocar aleatória simples por estratificada.","comoBancaPensa":"Mistura características de duas técnicas de amostragem."}},"ES-018":{"cognitivo":{"motivo":"Cobrar a aplicabilidade da moda a variáveis qualitativas.","palavraCritica":"moda não pode em qualitativas (falso)"},"comentario":{"resolucao":"ERRADO. É o contrário: a MODA (valor/categoria mais frequente) é a única medida de tendência central aplicável a variáveis QUALITATIVAS nominais, pois independe de operações aritméticas. Média e mediana exigem dados quantitativos (ou pelo menos ordenáveis, no caso da mediana).","fundamento":"Estatística descritiva — medidas de posição.","macete":"Cor preferida da turma? Só a moda responde (qualitativa).","erroComum":"Achar que a moda não serve para qualitativas.","comoBancaPensa":"Inverte a única medida aplicável a variáveis qualitativas."}},"ES-019":{"cognitivo":{"motivo":"Cobrar o intervalo do coeficiente de Pearson (−1 a +1).","palavraCritica":"acima de um (impossível)"},"comentario":{"resolucao":"ERRADO. O coeficiente de correlação de Pearson (r) está limitado ao intervalo [−1, +1]. Não assume valores acima de +1 nem abaixo de −1. |r| próximo de 1 indica correlação linear forte; r = 0 indica ausência de correlação linear.","fundamento":"Estatística — coeficiente de correlação de Pearson.","macete":"Pearson: de −1 a +1, sempre. Fora disso, é erro.","erroComum":"Admitir |r| > 1.","comoBancaPensa":"Extrapola o intervalo do coeficiente."}},"ES-020":{"cognitivo":{"motivo":"Cobrar a simetria da distribuição normal e a coincidência das três medidas.","palavraCritica":"assimétrica / valores distintos (falso)"},"comentario":{"resolucao":"ERRADO. A distribuição normal é SIMÉTRICA em torno da média; nela, média, mediana e moda COINCIDEM (assumem o mesmo valor central). A afirmação de assimetria e de valores distintos é falsa.","fundamento":"Estatística — distribuição normal.","macete":"Normal = sino simétrico: média = mediana = moda.","erroComum":"Tratar a normal como assimétrica.","comoBancaPensa":"Nega a simetria característica da normal."}},"ES-021":{"cognitivo":{"motivo":"Cobrar o intervalo axiomático da probabilidade [0, 1].","palavraCritica":"negativos (impossível)"},"comentario":{"resolucao":"ERRADO. Pela definição axiomática, a probabilidade de qualquer evento está entre 0 e 1 (0 ≤ P ≤ 1). Um evento impossível tem probabilidade ZERO — nunca negativa. Um evento certo tem probabilidade 1.","fundamento":"Teoria da probabilidade — axiomas de Kolmogorov.","macete":"Probabilidade: 0 a 1. Impossível = 0. Certo = 1.","erroComum":"Associar evento impossível a probabilidade negativa.","comoBancaPensa":"Viola o intervalo axiomático da probabilidade."}},"ES-022":{"cognitivo":{"motivo":"Reconhecer a comparação renda × movimentação como técnica investigativa do edital.","palavraCritica":"incompatibilidade patrimonial"},"comentario":{"resolucao":"CERTO. A confrontação entre a movimentação financeira e a renda declarada é técnica expressamente prevista no programa (“comparação entre fluxos financeiros e capacidade econômica declarada”) e constitui indício relevante de ocultação patrimonial, a ser corroborado por outros elementos.","fundamento":"Técnicas de análise financeira investigativa; Lei 9.613/1998.","macete":"Renda declarada muito menor que a movimentação = sinal de alerta.","erroComum":"Desconsiderar a análise comparativa como indício.","comoBancaPensa":"Cobra a aplicação prática de uma técnica listada no edital."}},"ES-023":{"cognitivo":{"motivo":"Distinguir baixa dispersão de dispersão nula.","palavraCritica":"necessariamente zero (falso)"},"comentario":{"resolucao":"ERRADO. O desvio padrão é igual a zero apenas quando TODOS os valores do conjunto são exatamente iguais. Valores meramente próximos entre si produzem desvio padrão pequeno, mas necessariamente positivo. A proximidade indica baixa dispersão, não dispersão nula.","fundamento":"Estatística descritiva — variância e desvio padrão.","macete":"Desvio zero só se todos os números forem idênticos. 'Parecido' não é 'igual'.","erroComum":"Concluir dispersão nula a partir de valores apenas próximos.","comoBancaPensa":"Termo absoluto ('necessariamente zero') sobre medida que exige igualdade exata."}},"ES-024":{"cognitivo":{"motivo":"Cobrar o cálculo e a interpretação do intervalo interquartil.","palavraCritica":"soma"},"comentario":{"resolucao":"ERRADO. O intervalo interquartil é calculado por subtração, e não soma: IIQ = Q3 − Q1 = 65 − 45 = 20. O valor 110 corresponderia à soma dos quartis, o que não tem significado estatístico como medida de dispersão.","fundamento":"Estatística descritiva — medidas de dispersão (intervalo interquartil).","macete":"IIQ = Q3 − Q1. Sempre subtração, nunca soma.","erroComum":"Somar os quartis em vez de subtrair.","comoBancaPensa":"Troca a operação aritmética correta por outra plausível."}},"ES-025":{"cognitivo":{"motivo":"Cobrar o critério clássico (regra de Tukey) para identificação de outliers.","palavraCritica":"1,5 vez"},"comentario":{"resolucao":"CERTO. Pelo critério usual (regra de Tukey), o limite superior para outliers é Q3 + 1,5×IIQ = 65 + 1,5×(65−45) = 65 + 30 = 95. Valores estritamente superiores a 95 são considerados atípicos.","fundamento":"Estatística descritiva — regra de Tukey para outliers.","macete":"Outlier superior = Q3 + 1,5×IIQ. Outlier inferior = Q1 − 1,5×IIQ.","erroComum":"Usar multiplicador diferente de 1,5 ou somar ao invés de partir de Q3.","comoBancaPensa":"Exige o cálculo completo da regra de Tukey."}},"ES-026":{"cognitivo":{"motivo":"Cobrar o axioma de que a soma das probabilidades no espaço amostral é 1.","palavraCritica":"sempre igual a 1"},"comentario":{"resolucao":"CERTO. Por definição, se o intervalo entre o valor mínimo e o valor máximo observados contém todo o suporte da variável aleatória X (ou seja, todos os valores possíveis), a probabilidade de X pertencer a esse intervalo é igual a 1, já que a soma das probabilidades de todos os valores possíveis de uma variável aleatória é sempre 1 (axioma da probabilidade total).","fundamento":"Teoria da probabilidade — axiomas de Kolmogorov (soma das probabilidades = 1).","macete":"Todo o suporte da variável = evento certo = probabilidade 1.","erroComum":"Supor que há probabilidade fora do intervalo observado.","comoBancaPensa":"Testa a compreensão do conceito de espaço amostral completo."}},"ES-027":{"cognitivo":{"motivo":"Cobrar o cálculo do escore Z (padronização da normal).","palavraCritica":"escore Z igual a 4"},"comentario":{"resolucao":"ERRADO. O escore Z correto é Z = (X − μ) / σ = (121 − 85) / 18 = 36 / 18 = 2, e não 4. O valor 121 km/h está 2 desvios padrão acima da média, não 4.","fundamento":"Estatística — padronização da distribuição normal (escore Z).","macete":"Z = (X − média) / desvio padrão.","erroComum":"Aceitar o número da assertiva sem refazer o cálculo.","comoBancaPensa":"Troca o resultado numérico correto por outro plausível."}},"ES-028":{"cognitivo":{"motivo":"Cobrar a ordem correta das etapas do ETL.","palavraCritica":"extração ... antecede a transformação"},"comentario":{"resolucao":"CERTO. No processo de ETL, a extração (Extract) dos dados de suas fontes de origem é a primeira etapa, antecedendo a transformação (Transform) — em que os dados são padronizados, limpos e enriquecidos — que, por sua vez, antecede o carregamento (Load) no ambiente de destino.","fundamento":"Análise de dados — processos de ETL (Extract, Transform, Load).","macete":"ETL: a ordem das letras é a ordem das etapas.","erroComum":"Inverter a ordem, transformando antes de extrair.","comoBancaPensa":"Testa se o candidato decorou a sigla sem entender o processo."}},"ES-029":{"cognitivo":{"motivo":"Cobrar a finalidade correta de cada biblioteca Python.","palavraCritica":"Pandas: DataFrame/Series. Sklearn: modelos de ML."},"comentario":{"resolucao":"ERRADO. As atribuições foram invertidas. O Pandas é a biblioteca voltada à manipulação e análise de dados estruturados, com as estruturas DataFrame e Series. O Scikit-learn (sklearn) é a biblioteca de referência para criação, treinamento e avaliação de modelos de aprendizado de máquina.","fundamento":"Análise de dados — bibliotecas Python (Pandas, Scikit-learn).","macete":"Pandas = tabela (DataFrame/Series). Sklearn = machine learning.","erroComum":"Não perceber a inversão de finalidades entre as duas bibliotecas.","comoBancaPensa":"Troca atribuições entre ferramentas conhecidas."}},"ES-030":{"cognitivo":{"motivo":"Cobrar a distinção entre aprendizado supervisionado e não supervisionado.","palavraCritica":"aprendizado supervisionado ... rótulos previamente definidos"},"comentario":{"resolucao":"ERRADO. A análise de agrupamentos (clusterização) é uma técnica de aprendizado NÃO supervisionado, que identifica grupos (clusters) de observações semelhantes entre si sem que existam rótulos ou categorias previamente definidas nos dados. A exigência de rótulos é característica da classificação, técnica supervisionada.","fundamento":"Mineração de dados — aprendizado supervisionado × não supervisionado.","macete":"Sem rótulo = não supervisionado = clusterização.","erroComum":"Trocar clusterização por classificação.","comoBancaPensa":"Inverte a natureza da técnica de aprendizado."}},"ES-031":{"cognitivo":{"motivo":"Cobrar a premissa 'ingênua' (naive) de independência condicional do algoritmo.","palavraCritica":"condicionalmente independentes"},"comentario":{"resolucao":"CERTO. O Naive Bayes baseia-se no teorema de Bayes e assume que os atributos são condicionalmente independentes dado o valor da classe. Embora essa premissa 'ingênua' raramente reflita a realidade dos dados, o algoritmo é amplamente reconhecido por apresentar bom desempenho prático em diversas aplicações, como filtros antispam.","fundamento":"Machine Learning — classificador Naive Bayes (teorema de Bayes).","macete":"Naive = ingênuo = assume independência condicional entre atributos.","erroComum":"Achar que a premissa irrealista invalida o desempenho prático.","comoBancaPensa":"Testa o entendimento da premissa e da robustez empírica do modelo."}},"ES-032":{"cognitivo":{"motivo":"Cobrar o conceito de n-gramas em PLN.","palavraCritica":"unigrama: 1 item. Bigrama: 2 itens."},"comentario":{"resolucao":"ERRADO. As definições foram invertidas. O unigrama corresponde a uma sequência de um único item (n=1), e o bigrama, a uma sequência de dois itens consecutivos (n=2) — e não o contrário.","fundamento":"Análise de dados — Processamento de Linguagem Natural (n-gramas).","macete":"Unigrama=1, bigrama=2, trigrama=3 itens.","erroComum":"Não perceber a inversão entre unigrama e bigrama.","comoBancaPensa":"Item de fixação conceitual sobre representação textual, com troca proposital das quantidades."}},"ES-033":{"cognitivo":{"motivo":"Cobrar a distinção entre overfitting e underfitting.","palavraCritica":"overfitting: excesso de ajuste. Underfitting: falta de ajuste."},"comentario":{"resolucao":"ERRADO. Os conceitos foram invertidos. O overfitting (e não o underfitting) ocorre quando o modelo se ajusta em excesso aos dados de treinamento, capturando ruídos que comprometem sua generalização. O underfitting (e não o overfitting) caracteriza-se pela incapacidade do modelo de capturar os padrões subjacentes.","fundamento":"Machine Learning — validação e avaliação de modelos preditivos.","macete":"Overfitting: decorou demais. Underfitting: não aprendeu nada.","erroComum":"Não perceber a troca de nomes entre os dois conceitos.","comoBancaPensa":"Testa a distinção clássica entre os dois problemas de ajuste, invertendo os rótulos."}},"ES-034":{"cognitivo":{"motivo":"Cobrar a finalidade típica de cada formato de dados.","palavraCritica":"CSV: tabular simples. XML/JSON: hierárquico."},"comentario":{"resolucao":"CERTO. O CSV é adequado para dados tabulares simples (linhas e colunas separadas por vírgula), enquanto XML e JSON permitem representar dados hierárquicos ou aninhados, com estruturas mais complexas de objetos e atributos.","fundamento":"Análise de dados — formatos e tecnologias (XML, JSON, CSV).","macete":"CSV: tabela simples. XML/JSON: estrutura aninhada.","erroComum":"Inverter as finalidades dos formatos.","comoBancaPensa":"Item de fixação sobre formatos de dados."}},"ES-035":{"cognitivo":{"motivo":"Cobrar a distinção entre estimação pontual e intervalar.","palavraCritica":"único valor ... intervalo ... nível de confiança"},"comentario":{"resolucao":"ERRADO. Os nomes foram invertidos. A estimação pontual (e não a intervalar) fornece um único valor como estimativa do parâmetro populacional. A estimação intervalar (e não a pontual) fornece um intervalo de valores plausíveis, associado a um nível de confiança.","fundamento":"Estatística — inferência estatística (estimação pontual e intervalar).","macete":"Pontual: um valor. Intervalar: faixa + confiança.","erroComum":"Não perceber a troca de nomes entre as duas formas de estimação.","comoBancaPensa":"Item de fixação conceitual em inferência, com troca proposital dos rótulos."}},"ES-036":{"cognitivo":{"motivo":"Cobrar o conceito de amostragem estratificada.","palavraCritica":"internamente ... heterogêneos"},"comentario":{"resolucao":"ERRADO. A lógica foi invertida: na amostragem estratificada, cada estrato deve ser internamente HOMOGÊNEO (e não heterogêneo), com elementos semelhantes entre si quanto a alguma característica relevante, enquanto os estratos entre si devem ser heterogêneos.","fundamento":"Estatística — técnicas de amostragem (amostragem estratificada).","macete":"Estrato: homogêneo por dentro, heterogêneo entre estratos.","erroComum":"Não perceber a inversão da lógica de homogeneidade.","comoBancaPensa":"Item de fixação sobre a técnica de amostragem, com troca proposital do termo-chave."}},"ES-037":{"cognitivo":{"motivo":"Cobrar a relação entre média, mediana e tipo de assimetria.","palavraCritica":"mediana superior à média ... assimetria negativa"},"comentario":{"resolucao":"CERTO. Quando a mediana é superior à média aritmética, a distribuição apresenta assimetria negativa (à esquerda): valores extremos menores 'puxam' a média para baixo, gerando uma cauda mais alongada nessa direção.","fundamento":"Estatística descritiva — medidas de assimetria.","macete":"Média < mediana → assimetria negativa (cauda à esquerda).","erroComum":"Inverter a direção da assimetria.","comoBancaPensa":"Testa a relação entre as três medidas de tendência central."}},"ES-038":{"cognitivo":{"motivo":"Cobrar a relação hierárquica correta entre IA, Machine Learning, redes neurais e LLMs.","palavraCritica":"campo ... técnica ... arquiteturas neurais profundas"},"comentario":{"resolucao":"CERTO. A afirmação descreve corretamente a relação hierárquica entre os conceitos: Machine Learning é o campo da IA voltado ao aprendizado de padrões a partir de dados; as redes neurais são uma das técnicas utilizadas dentro desse campo; e os LLMs são modelos baseados em arquiteturas neurais profundas, treinados em larga escala para processar e gerar linguagem natural.","fundamento":"Doutrina de Inteligência Artificial — taxonomia e hierarquia conceitual (IA, ML, redes neurais, LLMs).","macete":"Pense em círculos concêntricos: IA por fora, depois ML, depois redes neurais, depois LLMs.","erroComum":"Tratar Machine Learning, redes neurais e LLMs como sinônimos intercambiáveis.","comoBancaPensa":"Item 'limpo', com a relação hierárquica descrita de forma tecnicamente precisa."}},"ES-039":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o Machine Learning generaliza a partir de dados e que redes neurais podem ter múltiplas camadas.","palavraCritica":"exclusivamente ... apenas por uma única camada"},"comentario":{"resolucao":"ERRADO. O Machine Learning é definido pela capacidade de aprender padrões e generalizar a partir de dados, e não por regras fixas e determinísticas — essa última característica é mais próxima da IA simbólica clássica. Além disso, redes neurais artificiais podem possuir múltiplas camadas intermediárias e funções de ativação não lineares.","fundamento":"Doutrina de Inteligência Artificial — fundamentos conceituais (Machine Learning e redes neurais).","macete":"'Exclusivamente' e 'apenas' são bandeiras vermelhas em itens de IA.","erroComum":"Confundir Machine Learning com sistemas de regras fixas.","comoBancaPensa":"Combina duas palavras absolutas em uma única assertiva para reforçar o erro."}},"ES-040":{"cognitivo":{"motivo":"Cobrar o funcionamento técnico correto dos LLMs: previsão estatística da próxima palavra.","palavraCritica":"previsão estatística da sequência de palavras mais provável"},"comentario":{"resolucao":"CERTO. Os LLMs constroem suas respostas por meio da previsão estatística da sequência de palavras mais provável, com base nos padrões aprendidos a partir de grandes volumes de dados textuais durante o treinamento — funcionamento fundamentalmente estatístico, e não baseado em compreensão semântica plena.","fundamento":"Doutrina de Inteligência Artificial — funcionamento técnico dos modelos de linguagem de grande porte (LLMs).","macete":"LLM = prevê a próxima palavra mais provável, com base no que aprendeu no treinamento.","erroComum":"Atribuir aos LLMs uma compreensão semântica equivalente à humana.","comoBancaPensa":"Item 'limpo' e tecnicamente correto sobre o mecanismo estatístico central dos LLMs."}},"ES-041":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que os LLMs não têm consciência humana nem respostas totalmente determinísticas.","palavraCritica":"compreensão semântica plena ... totalmente determinísticas"},"comentario":{"resolucao":"ERRADO. Os LLMs não possuem compreensão semântica nem consciência contextual equivalentes à cognição humana — seu funcionamento é estatístico. Além disso, suas respostas podem variar conforme o contexto e os parâmetros de geração, não sendo totalmente determinísticas e invariáveis.","fundamento":"Doutrina de Inteligência Artificial — limitações dos modelos de linguagem de grande porte (LLMs).","macete":"LLM não tem consciência humana, nem respostas 100% fixas.","erroComum":"Humanizar excessivamente o funcionamento dos LLMs.","comoBancaPensa":"Combina duas afirmações absolutas e exageradas sobre a capacidade cognitiva dos LLMs."}},"ES-042":{"cognitivo":{"motivo":"Cobrar a característica central da IA generativa: criação de conteúdo inédito a partir de LLMs.","palavraCritica":"criar conteúdos inéditos"},"comentario":{"resolucao":"CERTO. A IA Generativa é definida pela capacidade de criar conteúdos inéditos — textos, imagens, músicas e códigos —, sendo que plataformas amplamente utilizadas, como o ChatGPT e o DeepSeek, têm seu funcionamento baseado em Modelos de Linguagem de Grande Porte (LLMs).","fundamento":"Doutrina de Inteligência Artificial — Inteligência Artificial Generativa (IAG).","macete":"IA Generativa = cria conteúdo novo (texto, imagem, áudio, código).","erroComum":"Associar a IA generativa a funções de segurança de rede ou armazenamento, sem relação com o tema.","comoBancaPensa":"Item 'limpo' com a definição correta e exemplos reais e coerentes de plataformas."}},"ES-043":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a IA generativa cria conteúdo inédito e depende de treinamento prévio.","palavraCritica":"incapaz ... exclusivamente ... sem qualquer treinamento prévio"},"comentario":{"resolucao":"ERRADO. A IA generativa é justamente capaz de produzir textos e outros conteúdos inéditos, com aplicações muito além do entretenimento, e depende de treinamento prévio extenso com grandes volumes de dados — a assertiva nega, ao mesmo tempo, três características básicas e corretas do conceito.","fundamento":"Doutrina de Inteligência Artificial — Inteligência Artificial Generativa (IAG).","macete":"IA generativa sempre precisa de treinamento prévio e não se restringe a jogos.","erroComum":"Aceitar múltiplas negações absolutas empilhadas na mesma assertiva.","comoBancaPensa":"Empilha três negações absolutas na mesma frase, todas contrárias à definição do conceito."}},"ES-044":{"cognitivo":{"motivo":"Cobrar que ferramentas como o Copilot acessam contexto de documentos, mas ainda assim exigem revisão humana.","palavraCritica":"acesso ao contexto ... continuam exigindo revisão humana"},"comentario":{"resolucao":"CERTO. Ferramentas de IA generativa integradas a suítes de produtividade, como o Copilot, realmente têm acesso ao contexto de documentos do usuário para gerar respostas mais relevantes, mas isso não dispensa a revisão humana dos resultados, uma vez que tais modelos não são treinados exclusivamente com informações integralmente verificadas.","fundamento":"Doutrina de Inteligência Artificial — IA generativa integrada a suítes de produtividade (Copilot).","macete":"Copilot vê o contexto do documento, mas o resultado sempre precisa de revisão humana.","erroComum":"Achar que ferramentas integradas não acessam contexto algum, ou que dispensam revisão humana.","comoBancaPensa":"Testa duas características simultaneamente corretas sobre uma mesma ferramenta."}},"ES-045":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que ferramentas como o Copilot acessam contexto e ainda exigem revisão humana.","palavraCritica":"não têm acesso a nenhum tipo de contexto ... dispensam qualquer revisão"},"comentario":{"resolucao":"ERRADO. Ferramentas de IA generativa integradas a suítes de produtividade, como o Copilot, efetivamente têm acesso ao contexto de documentos do usuário — e, mesmo assim, seus resultados continuam exigindo revisão humana, já que os modelos não são infalíveis.","fundamento":"Doutrina de Inteligência Artificial — IA generativa integrada a suítes de produtividade (Copilot).","macete":"Copilot acessa contexto, sim; e revisão humana continua necessária.","erroComum":"Encadear duas afirmações falsas como se uma justificasse a outra.","comoBancaPensa":"Nega duas características corretas em cadeia, dando a falsa impressão de coerência lógica interna."}},"ES-046":{"cognitivo":{"motivo":"Cobrar que a alucinação em IA generativa pode ocorrer independentemente da qualidade do comando do usuário.","palavraCritica":"mesmo quando o comando ... está correto e bem formulado"},"comentario":{"resolucao":"CERTO. A alucinação consiste na geração de informações incorretas ou inexistentes, apresentadas com aparência de veracidade, sendo uma limitação intrínseca do funcionamento estatístico dos modelos de IA generativa — podendo ocorrer mesmo quando o comando fornecido pelo usuário está correto e bem formulado.","fundamento":"Doutrina de Inteligência Artificial — IA generativa (fenômeno da alucinação).","macete":"Alucinação é falha do modelo, não só do usuário.","erroComum":"Restringir a ocorrência da alucinação apenas a comandos mal formulados.","comoBancaPensa":"Cobra a compreensão de que a alucinação é uma limitação estrutural do modelo, e não apenas erro de operação do usuário."}},"ES-047":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a alucinação é limitação do modelo, e não apenas erro do usuário.","palavraCritica":"exclusivamente ... não se verificando em hipótese alguma"},"comentario":{"resolucao":"ERRADO. A alucinação é uma limitação intrínseca dos modelos de IA generativa e pode ocorrer independentemente da qualidade do comando fornecido pelo usuário, inclusive diante de prompts corretos e bem formulados — não se trata de fenômeno exclusivo de comandos incorretos.","fundamento":"Doutrina de Inteligência Artificial — IA generativa (fenômeno da alucinação).","macete":"Prompt perfeito não garante ausência de alucinação.","erroComum":"Atribuir a alucinação exclusivamente a falhas do usuário na formulação do comando.","comoBancaPensa":"Usa palavras absolutas ('exclusivamente', 'em hipótese alguma') para restringir indevidamente a causa do fenômeno."}},"ES-048":{"cognitivo":{"motivo":"Cobrar a definição correta e completa do aprendizado de máquina.","palavraCritica":"quantidade e qualidade dos dados fornecidos"},"comentario":{"resolucao":"CERTO. O aprendizado de máquina é subcampo da IA que permite que sistemas aprendam padrões e tomem decisões sem programação explícita para cada tarefa, sendo sua capacidade de generalização diretamente dependente da quantidade e da qualidade dos dados utilizados no treinamento.","fundamento":"Doutrina de Inteligência Artificial — fundamentos do Machine Learning.","macete":"Mais dados relevantes e de qualidade → melhor generalização do modelo.","erroComum":"Ignorar a relação entre qualidade dos dados de treinamento e capacidade de generalização.","comoBancaPensa":"Item 'limpo' e tecnicamente correto sobre os fundamentos do aprendizado de máquina."}},"ES-049":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o Machine Learning é software/técnica, e não hardware, e que não elimina erros.","palavraCritica":"tipo de hardware ... eliminar totalmente"},"comentario":{"resolucao":"ERRADO. O Machine Learning é um campo de algoritmos e técnicas computacionais de aprendizado a partir de dados, e não um tipo de hardware de data center. Além disso, nenhum modelo de aprendizado de máquina elimina totalmente a ocorrência de erros de previsão.","fundamento":"Doutrina de Inteligência Artificial — fundamentos do Machine Learning.","macete":"ML é software/algoritmo, não hardware. Erros de previsão nunca são zerados por completo.","erroComum":"Confundir o conceito de Machine Learning com um componente de infraestrutura física.","comoBancaPensa":"Classifica erroneamente o conceito e, ainda, exagera sua capacidade preditiva."}},"ES-050":{"cognitivo":{"motivo":"Cobrar os três tipos clássicos de aprendizado de máquina e suas características distintivas.","palavraCritica":"supervisionado ... não supervisionado ... por reforço"},"comentario":{"resolucao":"CERTO. Os três tipos clássicos de aprendizado de máquina são corretamente descritos: supervisionado (dados rotulados), não supervisionado (identificação de padrões sem rótulos) e por reforço (aprendizado por recompensas e penalidades em interações com o ambiente).","fundamento":"Doutrina de Inteligência Artificial — tipos de aprendizado de máquina.","macete":"Supervisionado (rótulo), não supervisionado (sem rótulo), reforço (recompensa/punição).","erroComum":"Inverter as características entre os três tipos de aprendizado.","comoBancaPensa":"Item de fixação clássico sobre a taxonomia central do aprendizado de máquina."}},"ES-051":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que é o supervisionado (e não o não supervisionado) que depende de dados rotulados.","palavraCritica":"supervisionado dispensa ... não supervisionado ... depende de rótulos"},"comentario":{"resolucao":"ERRADO. As definições foram completamente invertidas: é o aprendizado supervisionado que depende de dados rotulados, e o aprendizado não supervisionado que dispensa rótulos, identificando padrões e tendências nos dados de forma autônoma.","fundamento":"Doutrina de Inteligência Artificial — tipos de aprendizado de máquina (supervisionado x não supervisionado).","macete":"Supervisionado = COM rótulo. Não supervisionado = SEM rótulo.","erroComum":"Inverter a dependência de rótulos entre os dois tipos de aprendizado.","comoBancaPensa":"Troca as características centrais dos dois tipos de aprendizado entre si, invertendo a lógica correta."}},"ES-052":{"cognitivo":{"motivo":"Cobrar a definição correta de embeddings e sua função na busca semântica.","palavraCritica":"embeddings"},"comentario":{"resolucao":"CERTO. Os embeddings são representações numéricas densas, de dimensão fixa, geradas a partir de textos, de modo que a proximidade entre os vetores reflita a similaridade semântica entre os textos originais — mecanismo central da busca semântica em sistemas baseados em modelos de linguagem.","fundamento":"Doutrina de Inteligência Artificial — representações vetoriais (embeddings) e busca semântica.","macete":"Embeddings = texto virou vetor; vetor perto = significado parecido.","erroComum":"Confundir embeddings com tokens (unidades de divisão do texto) ou prompts (comandos de entrada).","comoBancaPensa":"Item de fixação técnica sobre um conceito central de busca semântica em IA."}},"ES-053":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a representação vetorial de similaridade semântica é embedding, não token.","palavraCritica":"denominada token"},"comentario":{"resolucao":"ERRADO. A representação vetorial que reflete a similaridade semântica entre textos, usada em busca semântica, é denominada embedding, e não token. O token é apenas a unidade de divisão do texto para processamento, servindo de insumo para a geração dos embeddings, mas não se confunde com eles.","fundamento":"Doutrina de Inteligência Artificial — representações vetoriais (embeddings x tokens).","macete":"Busca semântica usa embeddings, não tokens.","erroComum":"Confundir token (unidade textual) com embedding (vetor de significado).","comoBancaPensa":"Troca o termo técnico correto por outro relacionado, mas com função distinta."}},"ES-054":{"cognitivo":{"motivo":"Cobrar a definição correta de Deep Learning como subconjunto do Machine Learning baseado em redes profundas.","palavraCritica":"subconjunto do aprendizado de máquina"},"comentario":{"resolucao":"CERTO. O Deep Learning é, de fato, um subconjunto do aprendizado de máquina, caracterizado pelo uso de redes neurais artificiais com múltiplas camadas, nas quais pesos e vieses distintos são atribuídos a cada camada e a cada neurônio artificial ao longo do treinamento.","fundamento":"Doutrina de Inteligência Artificial — Deep Learning (aprendizado profundo).","macete":"Deep Learning = ML + redes neurais com muitas camadas.","erroComum":"Tratar o Deep Learning como um campo independente do Machine Learning.","comoBancaPensa":"Item 'limpo' sobre a relação de subconjunto e a estrutura técnica do Deep Learning."}},"ES-055":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o Deep Learning é compatível com os três tipos de aprendizado (supervisionado, não supervisionado e por reforço).","palavraCritica":"trabalha sempre ... não sendo compatível"},"comentario":{"resolucao":"ERRADO. O Deep Learning não trabalha exclusivamente com aprendizado não supervisionado — sua arquitetura de redes neurais multicamadas é compatível com os três paradigmas de aprendizado: supervisionado, não supervisionado e por reforço, dependendo da aplicação.","fundamento":"Doutrina de Inteligência Artificial — Deep Learning e paradigmas de aprendizado.","macete":"Deep Learning é arquitetura — funciona com qualquer um dos três tipos de aprendizado.","erroComum":"Confundir a arquitetura de redes profundas com um único paradigma de aprendizado.","comoBancaPensa":"Usa a palavra absoluta 'sempre' para restringir indevidamente a compatibilidade do Deep Learning."}},"ES-056":{"cognitivo":{"motivo":"Cobrar a definição correta do aprendizado não supervisionado.","palavraCritica":"inferir suas próprias regras ... sem respostas corretas rotuladas"},"comentario":{"resolucao":"CERTO. O aprendizado não supervisionado é definido justamente pela ausência de rótulos nos dados de treinamento, exigindo que o próprio modelo infira regras e identifique padrões significativos de forma autônoma.","fundamento":"Doutrina de Inteligência Artificial — aprendizado não supervisionado.","macete":"Sem rótulo + acha padrão sozinho = aprendizado não supervisionado.","erroComum":"Confundir com o aprendizado supervisionado, que depende de dados rotulados.","comoBancaPensa":"Item de fixação sobre a definição precisa do aprendizado não supervisionado."}},"ES-057":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o aprendizado não supervisionado dispensa dados rotulados.","palavraCritica":"necessitam de dados rotulados"},"comentario":{"resolucao":"ERRADO. Os modelos de aprendizado não supervisionado dispensam dados rotulados, identificando padrões e tendências nos dados de forma autônoma — a necessidade de dados rotulados é justamente a característica que define o aprendizado supervisionado, e não o não supervisionado.","fundamento":"Doutrina de Inteligência Artificial — aprendizado não supervisionado x supervisionado.","macete":"Rótulo é do supervisionado. Não supervisionado dispensa rótulo.","erroComum":"Inverter a característica central que diferencia os dois tipos de aprendizado.","comoBancaPensa":"Atribui ao aprendizado não supervisionado a característica definidora do aprendizado supervisionado."}},"ES-058":{"cognitivo":{"motivo":"Cobrar a inspiração biológica das redes neurais e a aplicabilidade do aprendizado por reforço em ambientes dinâmicos.","palavraCritica":"interação dinâmica com o ambiente"},"comentario":{"resolucao":"CERTO. As redes neurais artificiais são inspiradas no funcionamento do cérebro humano, ajustando pesos para reconhecer padrões complexos a partir de grandes volumes de dados. O aprendizado por reforço, por sua vez, é aplicado justamente em sistemas que envolvem interação dinâmica com o ambiente, como jogos e robótica.","fundamento":"Doutrina de Inteligência Artificial — redes neurais artificiais e aprendizado por reforço.","macete":"Redes neurais = inspiração cerebral. Reforço = interação dinâmica com o ambiente.","erroComum":"Restringir o aprendizado por reforço a análises estáticas de dados.","comoBancaPensa":"Item 'limpo' que combina duas afirmações corretas sobre conceitos distintos de IA."}},"ES-059":{"cognitivo":{"motivo":"Cobrar que sistemas baseados em regras (IA simbólica) também são reconhecidos como inteligência artificial, mesmo sem aprendizado a partir de dados.","palavraCritica":"requisito indispensável"},"comentario":{"resolucao":"ERRADO. Sistemas baseados exclusivamente em regras lógicas predefinidas (IA simbólica, como sistemas especialistas) são reconhecidos como uma vertente legítima da Inteligência Artificial, ainda que não possuam capacidade de aprendizado a partir de dados — o aprendizado de máquina é apenas uma das abordagens dentro do campo mais amplo da IA, e não um requisito indispensável para toda e qualquer definição de sistema inteligente.","fundamento":"Doutrina de Inteligência Artificial — IA simbólica (sistemas baseados em regras) x aprendizado de máquina.","macete":"IA é mais ampla que ML — sistemas de regras (IA simbólica) também contam como IA.","erroComum":"Restringir o conceito de IA apenas aos sistemas que aprendem a partir de dados.","comoBancaPensa":"Cria um requisito conceitual inexistente para excluir uma vertente legítima e histórica da IA."}},"ES-060":{"cognitivo":{"motivo":"Cobrar a distinção conceitual básica entre estatística (medida da amostra) e parâmetro (medida da população).","palavraCritica":"estatística ... amostra ... parâmetro ... população"},"comentario":{"resolucao":"CERTO. Uma estatística é uma medida numérica calculada a partir dos dados de uma amostra (ex.: média amostral, desvio padrão amostral), ao passo que um parâmetro é uma medida numérica que descreve uma característica da população como um todo (ex.: média populacional).","fundamento":"Doutrina de Estatística — conceitos fundamentais de amostragem e inferência estatística.","macete":"Estatística = amostra. Parâmetro = população. Nunca inverter.","erroComum":"Trocar as definições, atribuindo 'estatística' à população e 'parâmetro' à amostra.","comoBancaPensa":"Item 'limpo' que testa a distinção mais básica e mais cobrada da inferência estatística."}},"ES-061":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que é a estatística (e não o parâmetro) que se refere à amostra, e o parâmetro (e não a estatística) que se refere à população.","palavraCritica":"parâmetro ... amostra ... estatística ... população"},"comentario":{"resolucao":"ERRADO. É a estatística que é medida numérica calculada a partir dos dados de uma amostra, e o parâmetro que descreve uma característica da população como um todo — o item inverte exatamente essas definições.","fundamento":"Doutrina de Estatística — conceitos fundamentais de amostragem e inferência estatística.","macete":"Estatística = amostra. Parâmetro = população. O item trocou os dois.","erroComum":"Aceitar a inversão entre as definições de estatística e parâmetro sem perceber a troca.","comoBancaPensa":"Inverte deliberadamente os dois conceitos centrais da inferência estatística para testar a memorização exata."}},"ES-062":{"cognitivo":{"motivo":"Cobrar que variáveis quantitativas contínuas admitem valores fracionários, obtidas por mensuração.","palavraCritica":"qualquer valor numérico ... não corresponda a um número inteiro"},"comentario":{"resolucao":"CERTO. Variáveis quantitativas contínuas, obtidas por mensuração, podem assumir qualquer valor numérico dentro de um intervalo, inclusive valores fracionários — como ocorre com a altura ou o peso de uma pessoa —, ao contrário das variáveis discretas, que só assumem valores inteiros.","fundamento":"Doutrina de Estatística — classificação de variáveis (quantitativas contínuas x discretas).","macete":"Contínua = mensuração, pode ter fração. Discreta = contagem, só inteiro.","erroComum":"Achar que variáveis quantitativas contínuas só podem assumir valores inteiros.","comoBancaPensa":"Item 'limpo' que reforça a característica central que distingue variáveis contínuas de discretas."}},"ES-063":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que variáveis contínuas admitem valores fracionários, e que essa admissão não as torna discretas.","palavraCritica":"somente ... valores numéricos inteiros ... vedada"},"comentario":{"resolucao":"ERRADO. Variáveis quantitativas contínuas admitem valores fracionários (obtidas por mensuração, como altura e peso) — é a variável quantitativa discreta (obtida por contagem) que é restrita a valores inteiros. O item inverte essa classificação.","fundamento":"Doutrina de Estatística — classificação de variáveis (quantitativas contínuas x discretas).","macete":"Restrição a valores inteiros é da discreta, não da contínua — nunca inverter.","erroComum":"Atribuir à variável contínua a restrição a valores inteiros, que pertence à variável discreta.","comoBancaPensa":"Inverte as características centrais de contínua e discreta para testar a memorização exata da distinção."}},"ES-064":{"cognitivo":{"motivo":"Cobrar que uma variável qualitativa com k categorias exige k-1 variáveis dummy para codificação completa, sem redundância.","palavraCritica":"não pode ser representada ... duas variáveis dummy"},"comentario":{"resolucao":"CERTO. Uma variável qualitativa com três categorias não pode ser representada por uma única variável dummy (binária, que só distingue 2 valores) — são necessárias, no mínimo, duas variáveis dummy para codificar as três categorias sem redundância (regra geral: k categorias exigem k-1 dummies).","fundamento":"Doutrina de Estatística — codificação de variáveis qualitativas (variáveis dummy).","macete":"k categorias → k-1 dummies. Nunca apenas uma dummy para 3 ou mais categorias.","erroComum":"Achar que uma única variável dummy é suficiente para representar qualquer variável qualitativa, independentemente do número de categorias.","comoBancaPensa":"Item 'limpo' que exige conhecer a regra de codificação k-1 para variáveis dummy."}},"ES-065":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que uma única variável dummy (binária) só distingue 2 categorias, não sendo suficiente para 3 ou mais.","palavraCritica":"qualquer número de categorias em um único indicador binário"},"comentario":{"resolucao":"ERRADO. A variável dummy é binária por definição, distinguindo no máximo 2 categorias isoladamente. Uma variável qualitativa com 3 categorias exige, no mínimo, 2 variáveis dummy para codificação completa sem redundância — não pode ser representada por uma única dummy.","fundamento":"Doutrina de Estatística — codificação de variáveis qualitativas (variáveis dummy).","macete":"Uma dummy = só 2 categorias. Nunca 'qualquer número' em um único indicador binário.","erroComum":"Achar que a variável dummy, sozinha, pode codificar qualquer quantidade de categorias.","comoBancaPensa":"Generaliza indevidamente a capacidade de uma única variável dummy, ignorando sua natureza binária."}},"ES-066":{"cognitivo":{"motivo":"Cobrar que a média aritmética exige variável quantitativa (métrica), não sendo aplicável a variáveis qualitativas.","palavraCritica":"necessariamente do tipo métrica ... não sendo possível"},"comentario":{"resolucao":"CERTO. O cálculo da média aritmética exige que a variável seja do tipo métrica (quantitativa) — não é possível calcular uma média aritmética significativa a partir de dados qualitativos nominais ou ordinais, ainda que codificados numericamente. Para esses casos, usam-se moda ou mediana.","fundamento":"Doutrina de Estatística — medidas de tendência central e níveis de mensuração.","macete":"Média = variável métrica. Nominal → moda. Ordinal → mediana.","erroComum":"Achar que a média aritmética pode ser calculada para qualquer variável, inclusive qualitativas codificadas numericamente.","comoBancaPensa":"Item 'limpo' que reforça a exigência de nível de mensuração adequado para cada medida de tendência central."}},"ES-067":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a mera codificação numérica de categorias qualitativas não torna a média aritmética significativa.","palavraCritica":"qualquer tipo de variável ... bastando ... codificadas"},"comentario":{"resolucao":"ERRADO. A média aritmética exige variável métrica (quantitativa) para ter significado estatístico — a mera codificação numérica de categorias qualitativas nominais ou ordinais não torna essa média significativa. Para essas variáveis, usam-se moda (nominal) ou mediana (ordinal).","fundamento":"Doutrina de Estatística — medidas de tendência central e níveis de mensuração.","macete":"Codificação numérica arbitrária não cria escala métrica — a média continua sem sentido.","erroComum":"Achar que basta atribuir números às categorias qualitativas para poder calcular uma média significativa.","comoBancaPensa":"Generaliza indevidamente a aplicabilidade da média aritmética para qualquer variável, ignorando a exigência do nível de mensuração."}},"ES-068":{"cognitivo":{"motivo":"Cobrar que variáveis que remetem a uma ideia de ordem (como dias da semana) são qualitativas ordinais, e não quantitativas.","palavraCritica":"qualitativa ordinal ... e não de variável quantitativa"},"comentario":{"resolucao":"CERTO. Os dias da semana são exemplo de variável qualitativa ordinal, e não quantitativa — expressam uma ordem entre categorias, mas essa ordem não corresponde a uma medida numérica passível de operações aritméticas (não faz sentido somar ou dividir 'terça-feira').","fundamento":"Doutrina de Estatística — classificação de variáveis (qualitativas nominais/ordinais x quantitativas discretas/contínuas).","macete":"'Ordinal' só existe como subtipo de qualitativa — nunca de quantitativa.","erroComum":"Classificar variáveis com ordem entre categorias (como dias da semana) como 'quantitativas ordinais', categoria inexistente.","comoBancaPensa":"Item 'limpo' que corrige uma confusão comum entre 'ordem entre categorias' e 'natureza quantitativa'."}},"ES-069":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que 'ordinal' é subtipo exclusivo de variável qualitativa, e que dias da semana não são variáveis quantitativas.","palavraCritica":"variáveis quantitativas podem ser do tipo ordinais"},"comentario":{"resolucao":"ERRADO. 'Ordinal' é subdivisão exclusiva das variáveis qualitativas, e não das quantitativas — estas se dividem em discretas e contínuas. Dias da semana e horas do dia, quando tratados como categorias que expressam ordem, são exemplos de variáveis qualitativas ordinais, e não quantitativas.","fundamento":"Doutrina de Estatística — classificação de variáveis (qualitativas nominais/ordinais x quantitativas discretas/contínuas).","macete":"Nunca existe 'variável quantitativa ordinal' — ordinal é sempre qualitativa.","erroComum":"Classificar como quantitativas variáveis que apenas expressam ordem entre categorias, sem natureza numérica somável.","comoBancaPensa":"Cria uma categoria de classificação inexistente para testar se o candidato decorou a árvore de classificação sem entendê-la."}},"ES-070":{"cognitivo":{"motivo":"Cobrar que a escolha de cores em visualizações de dados tem impacto significativo na interpretação, e não é um detalhe irrelevante.","palavraCritica":"influência relevante ... distorcer"},"comentario":{"resolucao":"CERTO. A escolha das cores em um gráfico tem influência relevante na interpretação dos dados, podendo destacar, ofuscar ou distorcer a percepção de padrões, tendências e comparações entre categorias — é elemento central das boas práticas de visualização de dados.","fundamento":"Doutrina de Estatística e Ciência de Dados — visualização de dados (data visualization).","macete":"Cor em gráfico é ferramenta analítica, não só estética — influencia diretamente a leitura dos dados.","erroComum":"Tratar a escolha de cores como um detalhe estético irrelevante para a interpretação dos dados.","comoBancaPensa":"Item 'limpo' que reforça a relevância prática de um tema frequentemente subestimado em provas de estatística aplicada."}},"ES-071":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a escolha de cores tem influência relevante (e não pouca ou nula) na interpretação de dados visualizados.","palavraCritica":"pouca influência ... meramente estético"},"comentario":{"resolucao":"ERRADO. A escolha das cores em um gráfico tem influência relevante — e não pouca ou nula — na interpretação dos dados, podendo destacar, ofuscar ou distorcer a percepção de padrões e comparações entre categorias. Não se trata de aspecto meramente estético.","fundamento":"Doutrina de Estatística e Ciência de Dados — visualização de dados (data visualization).","macete":"Nunca é 'pouca influência' — cor é ferramenta analítica central na visualização de dados.","erroComum":"Subestimar a importância da escolha de cores, tratando-a como puramente decorativa.","comoBancaPensa":"Minimiza a relevância de um elemento técnico central da visualização de dados, testando o conhecimento prático do tema."}},"ES-072":{"cognitivo":{"motivo":"Cobrar que o gráfico de pizza é adequado para poucas categorias, e não para grandes conjuntos de dados complexos.","palavraCritica":"não é a melhor escolha ... poucas categorias"},"comentario":{"resolucao":"CERTO. O gráfico de setores (pizza) não é a melhor escolha para grandes conjuntos de dados complexos — é mais adequado para representar a distribuição proporcional de uma variável qualitativa com poucas categorias, sob pena de se tornar visualmente poluído e de difícil leitura com muitas fatias.","fundamento":"Doutrina de Estatística e Ciência de Dados — visualização de dados (limitações do gráfico de setores).","macete":"Pizza: poucas categorias, sim. Muitas categorias/dados complexos: prefira gráfico de barras.","erroComum":"Achar que o gráfico de pizza é adequado para representar grandes volumes de dados ou muitas categorias.","comoBancaPensa":"Item 'limpo' que reforça uma limitação prática bem estabelecida na literatura de visualização de dados."}},"ES-073":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o gráfico de pizza se torna ilegível com muitas categorias, não sendo adequado para dados complexos.","palavraCritica":"melhor escolha ... elevado número de categorias ... sem prejuízo"},"comentario":{"resolucao":"ERRADO. O gráfico de pizza não é a melhor escolha para grandes conjuntos de dados complexos — com um número elevado de categorias, as fatias tornam-se pequenas e de difícil distinção visual, prejudicando a clareza da leitura. Nesses casos, são preferíveis gráficos de barras ou outras visualizações.","fundamento":"Doutrina de Estatística e Ciência de Dados — visualização de dados (limitações do gráfico de setores).","macete":"Pizza nunca é ideal para 'grandes conjuntos complexos' — a legibilidade cai com muitas fatias.","erroComum":"Achar que o gráfico de pizza mantém boa legibilidade independentemente do número de categorias representadas.","comoBancaPensa":"Inverte a limitação conhecida do gráfico de pizza, apresentando-a como uma vantagem, para testar o conhecimento prático de visualização de dados."}},"ES-074":{"cognitivo":{"motivo":"Cobrar que a tabela de frequências, ao agregar dados em contagens por categoria, perde a informação sobre a ordem/sequência original das observações individuais.","palavraCritica":"não é possível recuperar a sequência original ... sem preservar a ordem"},"comentario":{"resolucao":"CERTO. A agregação é irreversível: a tabela guarda \"quantos\", não \"em que ordem\" nem \"de quem\". Do resumo não se retorna ao dado bruto. É exatamente o mesmo motivo pelo qual, a partir de uma tabela de frequências por classe, não se calcula a média EXATA — só uma estimativa, usando o ponto médio de cada classe como representante de todos os valores dela. Guarde a regra geral: todo resumo estatístico troca detalhe por legibilidade, e a pergunta útil em prova é sempre qual informação foi descartada no caminho.","fundamento":"Doutrina de Estatística — distribuições de frequência (agregação e perda de informação sequencial).","macete":"Tabela de frequências = contagem por categoria. A ordem original dos dados nunca é recuperável a partir dela.","erroComum":"Achar que a tabela de frequências preserva informação suficiente para reconstruir a sequência exata dos dados coletados.","comoBancaPensa":"Item 'limpo' que reforça um conceito central sobre agregação de dados: resumir é sempre perder alguma informação."}},"ES-075":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a tabela de frequências não preserva a ordem/sequência original das observações.","palavraCritica":"é possível recuperar ... incluída a ordem exata"},"comentario":{"resolucao":"ERRADO. A tabela de frequências absolutas não preserva a ordem em que os dados foram coletados — apenas informa a contagem de ocorrências por categoria. Não é possível, a partir dela, recuperar a sequência original dos valores individuais da série de dados.","fundamento":"Doutrina de Estatística — distribuições de frequência (agregação e perda de informação sequencial).","macete":"Tabela de frequências: contagem sim, ordem original nunca.","erroComum":"Achar que uma tabela resumida de frequências preserva informação suficiente para reconstruir a sequência exata da coleta original.","comoBancaPensa":"Afirma uma capacidade de reconstrução que a agregação estatística, por definição, não permite."}},"ES-076":{"cognitivo":{"motivo":"Cobrar a regra básica de construção do histograma: altura das barras proporcional à frequência.","palavraCritica":"altura das barras ... proporcional à frequência"},"comentario":{"resolucao":"CERTO. A altura da barra representa a frequência da classe. Duas precisões que a banca cobra: primeiro, o histograma é para variável QUANTITATIVA e tem barras coladas, porque o eixo horizontal é contínuo — barras separadas caracterizam o gráfico de colunas, próprio de variável qualitativa. Segundo, quando as classes têm amplitudes DIFERENTES, o rigor manda usar a densidade de frequência (frequência ÷ amplitude) na altura, para que a ÁREA, e não a altura, fique proporcional à frequência. Com classes de mesma amplitude — o caso usual em prova — altura e área são proporcionais e o enunciado está correto como escrito.","fundamento":"Doutrina de Estatística — representação gráfica de distribuições de frequência (histograma).","macete":"Histograma: altura da barra = frequência da classe.","erroComum":"Confundir a dimensão do histograma (altura) que representa a frequência com a largura das barras.","comoBancaPensa":"Item 'limpo' que reproduz a regra fundamental de construção do histograma."}},"ES-077":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que é a altura (e não a largura) das barras do histograma que representa a frequência de cada classe.","palavraCritica":"altura ... sempre igual ... largura ... deve ser ajustado"},"comentario":{"resolucao":"ERRADO. No histograma, é a altura das barras verticais que é proporcional à frequência observada de cada classe — a largura geralmente corresponde à amplitude do intervalo de classe. O item inverte essa relação, atribuindo à largura a função de representar a frequência.","fundamento":"Doutrina de Estatística — representação gráfica de distribuições de frequência (histograma).","macete":"Nunca inverter: altura = frequência. A largura não é o elemento que representa a frequência da classe.","erroComum":"Trocar as dimensões do histograma, atribuindo à largura das barras a representação da frequência de cada classe.","comoBancaPensa":"Inverte a regra fundamental de construção do histograma para testar a memorização exata do conceito."}},"ES-078":{"cognitivo":{"motivo":"Cobrar que aumentar o número de classes (intervalos mais estreitos) reduz a perda de informação, aproximando a representação dos dados originais.","palavraCritica":"tanto menor quanto maior for o número de classes"},"comentario":{"resolucao":"CERTO. Ao agrupar dados contínuos em classes, quanto maior o número de classes escolhidas (intervalos mais estreitos), menor a perda de informação em relação aos dados originais, pois a representação se aproxima mais dos valores individuais reais.","fundamento":"Doutrina de Estatística — distribuições de frequência por classes (agrupamento de dados contínuos).","macete":"Mais classes = intervalos mais estreitos = menos perda de informação.","erroComum":"Inverter a relação, achando que mais classes geram mais perda de informação em vez de menos.","comoBancaPensa":"Item 'limpo' que reforça, na forma correta, a relação entre granularidade das classes e fidelidade aos dados originais."}},"ES-079":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que mais classes (intervalos mais estreitos) reduzem — e não aumentam — a perda de informação.","palavraCritica":"tanto maior quanto maior for o número de classes"},"comentario":{"resolucao":"ERRADO. A relação está invertida: quanto maior o número de classes (intervalos mais estreitos), MENOR é a perda de informação em relação aos dados originais — e não maior. É o uso de POUCAS classes (intervalos largos) que aumenta a perda de informação.","fundamento":"Doutrina de Estatística — distribuições de frequência por classes (agrupamento de dados contínuos).","macete":"Inverteu a lógica? Desconfie: mais classes sempre aproxima mais dos dados originais, nunca afasta.","erroComum":"Achar que aumentar o número de classes de agrupamento aumenta a perda de informação em relação aos dados originais.","comoBancaPensa":"Inverte deliberadamente uma relação lógica bem estabelecida para testar se o candidato raciocina ou apenas decora padrões."}},"ES-080":{"cognitivo":{"motivo":"Cobrar o cálculo correto da mediana em um conjunto de tamanho par: a média aritmética dos dois valores centrais após a ordenação.","palavraCritica":"igual a 19 minutos"},"comentario":{"resolucao":"CERTO. Com os dados já ordenados (12, 15, 15, 18, 20, 22, 25, 30), a mediana de um conjunto de 8 valores (par) é a média aritmética dos dois valores centrais, o 4º (18) e o 5º (20): (18 + 20) / 2 = 19 minutos.","fundamento":"Doutrina de Estatística — cálculo da mediana em conjuntos de tamanho par.","macete":"Conjunto par: some os dois valores do meio e divida por 2.","erroComum":"Considerar apenas um dos dois valores centrais (18 ou 20) como sendo a mediana, sem calcular a média entre eles.","comoBancaPensa":"Item 'limpo' que exige o cálculo correto e completo da mediana em conjunto de tamanho par."}},"ES-081":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a mediana de um conjunto par não é apenas um dos valores centrais isolados, mas a média entre eles.","palavraCritica":"igual a 18 minutos"},"comentario":{"resolucao":"ERRADO. A mediana correta é 19 minutos, e não 18. Com os dados ordenados (12, 15, 15, 18, 20, 22, 25, 30), a mediana de um conjunto de 8 valores é a média aritmética entre o 4º valor (18) e o 5º valor (20): (18 + 20) / 2 = 19.","fundamento":"Doutrina de Estatística — cálculo da mediana em conjuntos de tamanho par.","macete":"18 é só o 4º valor — a mediana real é a média entre o 4º e o 5º, que dá 19.","erroComum":"Parar no primeiro dos dois valores centrais e esquecer de calcular a média com o segundo.","comoBancaPensa":"Apresenta um valor real da série (18), mas que não corresponde à mediana correta, testando o cálculo completo."}},"ES-082":{"cognitivo":{"motivo":"Cobrar o cálculo correto da moda: o valor que ocorre com maior frequência no conjunto de dados.","palavraCritica":"igual a 25 anos"},"comentario":{"resolucao":"CERTO. No conjunto de dados (22, 25, 25, 25, 28, 30, 32, 35, 40), o valor 25 é o único que se repete (aparece 3 vezes), sendo, portanto, a moda do conjunto.","fundamento":"Doutrina de Estatística — cálculo da moda (medida de tendência central).","macete":"Moda = valor mais frequente. Conte as repetições, não olhe só para a posição na lista.","erroComum":"Atribuir a moda a um valor que aparece apenas uma vez no conjunto de dados.","comoBancaPensa":"Item 'limpo' que exige a identificação correta do valor de maior frequência."}},"ES-083":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a moda é o valor mais frequente (25), e não o primeiro valor da série ordenada (22).","palavraCritica":"igual a 22 anos"},"comentario":{"resolucao":"ERRADO. A moda correta é 25 anos, e não 22. O valor 22 aparece apenas uma vez no conjunto de dados (22, 25, 25, 25, 28, 30, 32, 35, 40), ao passo que o valor 25 se repete 3 vezes, sendo o mais frequente.","fundamento":"Doutrina de Estatística — cálculo da moda (medida de tendência central).","macete":"Menor valor da lista ≠ moda. Moda é sempre o valor mais repetido.","erroComum":"Confundir a moda com o valor mínimo (ou qualquer valor que não seja o mais frequente) do conjunto de dados.","comoBancaPensa":"Atribui a moda a um valor extremo do conjunto para testar se o candidato realmente conta as frequências."}},"ES-084":{"cognitivo":{"motivo":"Cobrar o cálculo direto da média aritmética: soma dos valores dividida pela quantidade de observações.","palavraCritica":"igual a 7"},"comentario":{"resolucao":"CERTO. A soma das quantidades de armas apreendidas nas 5 operações é 3 + 5 + 7 + 9 + 11 = 35. Dividindo pela quantidade de operações (5), obtém-se a média aritmética: 35 / 5 = 7.","fundamento":"Doutrina de Estatística — cálculo da média aritmética (medida de tendência central).","macete":"Média = soma ÷ quantidade de valores. Confira sempre os dois números antes de dividir.","erroComum":"Errar a soma dos valores ou dividir por uma quantidade de observações incorreta.","comoBancaPensa":"Item 'limpo' que exige apenas o cálculo direto e correto da média aritmética."}},"ES-085":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a média aritmética correta do conjunto é 7, e não 9 (que é apenas um dos valores observados).","palavraCritica":"igual a 9"},"comentario":{"resolucao":"ERRADO. A média aritmética correta é 7, e não 9. A soma dos valores (3 + 5 + 7 + 9 + 11 = 35) dividida pela quantidade de operações (5) resulta em 35 / 5 = 7 — o valor 9 é apenas uma das observações, não o resultado da média.","fundamento":"Doutrina de Estatística — cálculo da média aritmética (medida de tendência central).","macete":"Nunca confundir um valor do conjunto com o resultado do cálculo da média.","erroComum":"Apontar um valor qualquer do conjunto de dados como sendo a própria média aritmética, sem realizar o cálculo.","comoBancaPensa":"Apresenta um valor real, porém individual, da série como se fosse o resultado do cálculo da média."}},"ES-086":{"cognitivo":{"motivo":"Cobrar a comparação entre o primeiro quartil (que reflete os valores mais baixos da distribuição) e a média amostral.","palavraCritica":"inferior à média amostral"},"comentario":{"resolucao":"CERTO. O primeiro quartil (Q1) é calculado a partir da metade inferior dos dados ordenados (50, 55), resultando em 52,5. A média amostral é (50+55+60+65+70)/5 = 60. Como 52,5 é inferior a 60, o item está correto.","fundamento":"Doutrina de Estatística — quartis e média aritmética (medidas de posição e tendência central).","macete":"Q1 = mediana da metade inferior dos dados. Compare sempre com o resultado real da média, não com 'impressões'.","erroComum":"Inverter a comparação, afirmando que o primeiro quartil é superior à média amostral.","comoBancaPensa":"Item 'limpo' que exige o cálculo de duas medidas distintas (quartil e média) para uma comparação correta."}},"ES-087":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o primeiro quartil (52,5) é inferior — e não superior — à média amostral (60).","palavraCritica":"superior à média amostral"},"comentario":{"resolucao":"ERRADO. O primeiro quartil (Q1 = 52,5) é inferior — e não superior — à média amostral (60). O item inverte o resultado da comparação correta entre as duas medidas.","fundamento":"Doutrina de Estatística — quartis e média aritmética (medidas de posição e tendência central).","macete":"Refaça sempre os dois cálculos (Q1 e média) antes de aceitar qualquer comparação entre eles.","erroComum":"Assumir, sem calcular, que o primeiro quartil seria superior à média amostral.","comoBancaPensa":"Inverte o resultado de uma comparação numérica real para testar se o candidato de fato calcula, em vez de apenas estimar."}},"ES-088":{"cognitivo":{"motivo":"Cobrar que, em distribuições perfeitamente simétricas, média, mediana e moda tendem a coincidir.","palavraCritica":"tendem a assumir o mesmo valor"},"comentario":{"resolucao":"CERTO. Na simetria perfeita as três medidas coincidem sobre o eixo de simetria. Duas cautelas que a banca explora: primeiro, a recíproca é FALSA — média igual a mediana igual a moda não prova simetria, pois há distribuições assimétricas em que elas coincidem. Segundo, na assimetria à direita (cauda longa à direita) a ordem típica é moda < mediana < média, porque só a média é puxada pelos valores extremos; à esquerda, inverte-se. É por isso que renda se reporta por mediana, não por média. O \"tendem a\" do enunciado é proposital e está correto.","fundamento":"Doutrina de Estatística — medidas de tendência central e simetria de distribuições.","macete":"Distribuição simétrica: média = mediana = moda, todas coincidindo no centro.","erroComum":"Achar que essas três medidas nunca podem coincidir, ou que alguma delas não é medida de tendência central.","comoBancaPensa":"Item 'limpo' que reforça a relação central entre simetria e coincidência das três principais medidas."}},"ES-089":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que em distribuições perfeitamente simétricas as três medidas coincidem, e não que a moda supera as demais.","palavraCritica":"valor superior ... raramente coincidem"},"comentario":{"resolucao":"ERRADO. Em uma distribuição perfeitamente simétrica, a moda NÃO tende a superar a média e a mediana — pelo contrário, as três medidas tendem a coincidir no mesmo valor. É nas distribuições assimétricas que essas medidas se distanciam entre si.","fundamento":"Doutrina de Estatística — medidas de tendência central e simetria de distribuições.","macete":"Simetria = coincidência das três medidas. Diferença entre elas é sinal de assimetria, não de simetria.","erroComum":"Achar que a simetria perfeita é a condição em que as medidas de tendência central mais se distanciam entre si.","comoBancaPensa":"Inverte a relação real entre simetria e coincidência das medidas de tendência central."}},"ES-090":{"cognitivo":{"motivo":"Cobrar que a igualdade entre média e mediana não garante, por si só, que a distribuição dos dados seja simétrica.","palavraCritica":"média igual à mediana ... de forma assimétrica"},"comentario":{"resolucao":"CERTO. No conjunto {0, 0, 5, 7, 13}, tanto a média quanto a mediana são iguais a 5. Ainda assim, os valores não se distribuem de forma simétrica em torno desse centro (os desvios são -5, -5, 0, +2 e +8, sem espelhamento equilibrado) — a igualdade entre média e mediana não implica, portanto, simetria da distribuição.","fundamento":"Doutrina de Estatística — relação entre média, mediana e simetria de distribuições.","macete":"Média = mediana não garante simetria — é condição necessária, mas não suficiente.","erroComum":"Achar que toda vez que média e mediana coincidem, a distribuição dos dados é automaticamente simétrica.","comoBancaPensa":"Item 'limpo' que exige entender a diferença entre uma condição necessária e uma condição suficiente para a simetria."}},"ES-091":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a igualdade entre média e mediana não é condição suficiente para concluir simetria da distribuição.","palavraCritica":"necessariamente ... simétrica"},"comentario":{"resolucao":"ERRADO. A igualdade numérica entre média e mediana não permite concluir, necessariamente, que a distribuição seja simétrica. É possível haver conjuntos de dados assimétricos (como {0, 0, 5, 7, 13}, em que ambas valem 5) em que essa igualdade ocorre sem simetria real na distribuição.","fundamento":"Doutrina de Estatística — relação entre média, mediana e simetria de distribuições.","macete":"'Sempre que média = mediana, distribuição é simétrica' está sempre errado — existem contraexemplos.","erroComum":"Tratar a igualdade entre média e mediana como prova suficiente e automática de simetria da distribuição.","comoBancaPensa":"Generaliza uma condição necessária (mas não suficiente) como se fosse garantia absoluta de simetria."}},"ES-092":{"cognitivo":{"motivo":"Cobrar a recomposição de médias ao combinar dois grupos: a partir da soma total dos dois grupos, isolar a média do subgrupo desconhecido.","palavraCritica":"inferior a 30 anos"},"comentario":{"resolucao":"CERTO. A soma das idades dos 8 policiais originais é 8×38=304. A soma das idades do grupo combinado (12 policiais, média 35) é 12×35=420. A soma das idades dos 4 novos policiais é 420−304=116, resultando em uma média de 116/4=29 anos — inferior a 30, como afirma o item.","fundamento":"Doutrina de Estatística — recomposição de médias em grupos combinados (problemas de média ponderada).","macete":"Some os totais (média × n), subtraia o grupo conhecido, divida pelo grupo restante.","erroComum":"Tentar 'estimar' a média do novo grupo sem recompor corretamente as somas totais de idade envolvidas.","comoBancaPensa":"Item 'limpo' que exige o raciocínio completo de recomposição de médias a partir de somas totais."}},"ES-093":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a média correta dos 4 novos policiais (29 anos) é inferior — e não superior — a 30 anos.","palavraCritica":"superior a 30 anos"},"comentario":{"resolucao":"ERRADO. A média de idade dos 4 novos policiais é de 29 anos (calculada por 116/4, onde 116 = 420 − 304), e não superior a 30 anos como afirma o item — 29 é inferior a 30.","fundamento":"Doutrina de Estatística — recomposição de médias em grupos combinados (problemas de média ponderada).","macete":"Sempre recomponha as somas (média × n) antes de comparar — não assuma o resultado por intuição.","erroComum":"Estimar, sem calcular, que a média do subgrupo desconhecido deveria se aproximar da média geral do grupo combinado.","comoBancaPensa":"Inverte o resultado real do cálculo de recomposição de médias para testar se o candidato de fato resolve o problema."}},"ES-094":{"cognitivo":{"motivo":"Cobrar o cálculo do primeiro quartil em um conjunto com valores repetidos, usando a mediana da metade inferior dos dados.","palavraCritica":"igual a 2"},"comentario":{"resolucao":"CERTO. A metade inferior dos dados ordenados (1, 2, 2, 2, 2, 3, 4, 4, 4, 9) é {1, 2, 2, 2, 2}, cuja mediana (valor central) é 2. Esse é o valor do primeiro quartil (Q1) do conjunto.","fundamento":"Doutrina de Estatística — cálculo de quartis em conjuntos de dados com valores repetidos.","macete":"Q1 sempre vem da metade de baixo dos dados ordenados, nunca da metade de cima.","erroComum":"Calcular o quartil a partir da metade superior dos dados, em vez da metade inferior correspondente ao Q1.","comoBancaPensa":"Item 'limpo' que exige a correta segmentação dos dados ordenados para o cálculo do primeiro quartil."}},"ES-095":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o primeiro quartil (2) corresponde à metade inferior, e não à metade superior (onde está o valor 4).","palavraCritica":"igual a 4"},"comentario":{"resolucao":"ERRADO. O valor 4 corresponde ao terceiro quartil (Q3), calculado a partir da metade superior dos dados ({3, 4, 4, 4, 9}) — e não ao primeiro quartil (Q1), que é 2, calculado a partir da metade inferior ({1, 2, 2, 2, 2}).","fundamento":"Doutrina de Estatística — cálculo de quartis em conjuntos de dados com valores repetidos.","macete":"Metade de baixo → Q1. Metade de cima → Q3. Não confundir os dois quartis extremos.","erroComum":"Calcular corretamente um quartil, mas atribuí-lo ao rótulo errado (Q1 em vez de Q3, ou vice-versa).","comoBancaPensa":"Apresenta um valor real do conjunto (o Q3 correto), mas o rotula incorretamente como sendo o primeiro quartil."}},"ES-096":{"cognitivo":{"motivo":"Cobrar que a média é sensível a valores extremos (outliers), enquanto a mediana é uma medida robusta a esse tipo de distorção.","palavraCritica":"alteração significativa ... permanecerá igual a 4 ... maior sensibilidade da média"},"comentario":{"resolucao":"CERTO. Antes da substituição, a média é 4,4 e a mediana é 4. Após substituir 6 por 60, a média salta para 15,2 (alteração significativa), enquanto a mediana permanece igual a 4 — evidenciando que a média é mais sensível a valores extremos (outliers) do que a mediana.","fundamento":"Doutrina de Estatística — sensibilidade das medidas de tendência central a valores extremos (outliers).","macete":"Outlier: média dispara, mediana quase não se move — por isso a mediana é preferida em dados com valores extremos.","erroComum":"Achar que média e mediana são igualmente afetadas pela presença de um valor discrepante no conjunto de dados.","comoBancaPensa":"Item 'limpo' que ilustra numericamente, com um exemplo concreto, a diferença de robustez entre média e mediana."}},"ES-097":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a mediana é robusta a outliers, ao contrário da média, que é sensível a eles.","palavraCritica":"ambas as medidas são igualmente sensíveis ... mesma magnitude"},"comentario":{"resolucao":"ERRADO. A mediana permanece igual a 4 mesmo após a substituição do valor 6 por 60, ao passo que a média salta de 4,4 para 15,2 — as duas medidas não reagem de forma igual ou proporcional a um valor extremo; a mediana é robusta a outliers, e a média não é.","fundamento":"Doutrina de Estatística — sensibilidade das medidas de tendência central a valores extremos (outliers).","macete":"Mediana é robusta a outliers; média não é — nunca tratá-las como igualmente sensíveis.","erroComum":"Achar que qualquer alteração em um valor do conjunto afeta média e mediana na mesma proporção.","comoBancaPensa":"Generaliza indevidamente a reação das duas medidas a um valor extremo, ignorando a robustez conhecida da mediana."}},"ES-098":{"cognitivo":{"motivo":"Fixar as condições que caracterizam um experimento binomial.","palavraCritica":"independentes ... constante"},"comentario":{"resolucao":"CERTO. São exatamente os pressupostos do modelo binomial: número fixo de ensaios (n), independência entre eles, dicotomia dos resultados (sucesso/fracasso) e probabilidade de sucesso p constante. A amostragem com reposição garante essa constância.","fundamento":"Modelo binomial — X ~ B(n, p).","macete":"n fixo + independência + 2 resultados + p constante.","erroComum":"Aplicar binomial a sorteios sem reposição.","comoBancaPensa":"Item correto que testa a distinção binomial × hipergeométrica."}},"ES-099":{"cognitivo":{"motivo":"Separar os momentos da binomial dos da Poisson.","palavraCritica":"variância também é np"},"comentario":{"resolucao":"ERRADO. A esperança está correta, E(X) = np, mas a variância é Var(X) = np(1 − p) = npq. Como 0 < q < 1, na binomial a variância é sempre INFERIOR à média. A igualdade entre média e variância é característica da distribuição de Poisson, não da binomial.","fundamento":"Modelo binomial — momentos.","macete":"Média np; variância npq.","erroComum":"Escrever Var(X) = np, confundindo com Poisson.","comoBancaPensa":"Acerta a parte fácil e cola na binomial a propriedade que identifica a Poisson."}},"ES-100":{"cognitivo":{"motivo":"Fixar a igualdade entre média e variância na Poisson.","palavraCritica":"λ²"},"comentario":{"resolucao":"ERRADO. Na distribuição de Poisson, média e variância são ambas iguais a λ: E(X) = Var(X) = λ. Essa igualdade é justamente a característica que identifica o modelo. O desvio padrão, sim, é √λ.","fundamento":"Modelo de Poisson — X ~ Poisson(λ).","macete":"Poisson: média = variância.","erroComum":"Elevar λ ao quadrado na variância.","comoBancaPensa":"Ataca a propriedade mais distintiva do modelo, apostando na confusão com desvio padrão."}},"ES-101":{"cognitivo":{"motivo":"Fixar o contexto de aplicação da Poisson.","palavraCritica":"intervalo fixo de tempo ou espaço"},"comentario":{"resolucao":"CERTO. A Poisson modela contagens de eventos raros e independentes em um intervalo fixo (tempo, área, volume), sob taxa média constante λ — como chamadas por hora ou defeitos por metro de tecido.","fundamento":"Modelo de Poisson — pressupostos.","macete":"Poisson conta ocorrências por unidade de tempo ou espaço.","erroComum":"Exigir número fixo de ensaios, como na binomial.","comoBancaPensa":"Item correto que separa contagem por intervalo de contagem por ensaios."}},"ES-102":{"cognitivo":{"motivo":"Fixar o critério que separa hipergeométrica de binomial.","palavraCritica":"sem reposição"},"comentario":{"resolucao":"CERTO. Na hipergeométrica, as extrações ocorrem sem reposição em população finita de tamanho N com K sucessos; a cada retirada a composição muda, de modo que as provas são dependentes e p não é constante — exatamente o que a distingue da binomial.","fundamento":"Modelo hipergeométrico.","macete":"Sem reposição → hipergeométrica.","erroComum":"Usar binomial em amostragem sem reposição.","comoBancaPensa":"Item correto que cobra o critério de escolha entre os dois modelos."}},"ES-103":{"cognitivo":{"motivo":"Fixar o que a geométrica conta.","palavraCritica":"primeiro sucesso"},"comentario":{"resolucao":"CERTO. A geométrica conta os ensaios independentes de Bernoulli até o primeiro sucesso, com P(X = k) = (1 − p)^(k−1)·p. É o caso particular da binomial negativa em que se aguarda apenas um sucesso.","fundamento":"Modelo geométrico.","macete":"Geométrica = tempo de espera do 1º sucesso.","erroComum":"Confundir com binomial negativa.","comoBancaPensa":"Item correto que exige separar geométrica de binomial negativa."}},"ES-104":{"cognitivo":{"motivo":"Separar binomial negativa de geométrica.","palavraCritica":"idêntica ... em qualquer situação"},"comentario":{"resolucao":"ERRADO. A binomial negativa modela o número de ensaios até o r-ésimo sucesso. A geométrica é apenas o caso particular em que r = 1; para r > 1 as distribuições não coincidem.","fundamento":"Modelo binomial negativo (Pascal).","macete":"Binomial negativa: espera o r-ésimo sucesso.","erroComum":"Tratar as duas como sinônimas.","comoBancaPensa":"Usa a relação verdadeira de caso particular para afirmar identidade falsa."}},"ES-105":{"cognitivo":{"motivo":"Fixar os axiomas da função de probabilidade.","palavraCritica":"soma ... igual a 1"},"comentario":{"resolucao":"CERTO. São as duas condições que definem uma função de probabilidade de variável discreta: não negatividade limitada por 1 e soma unitária sobre todo o suporte.","fundamento":"Axiomas da função de probabilidade.","macete":"Soma sempre 1.","erroComum":"Não checar o fechamento da tabela.","comoBancaPensa":"Item correto que prepara para questões com parâmetro a determinar."}},"ES-106":{"cognitivo":{"motivo":"Fixar as propriedades básicas da normal.","palavraCritica":"coincidem"},"comentario":{"resolucao":"CERTO. A normal é simétrica em relação à média, tem forma de sino e apresenta coincidência entre média, mediana e moda. Assimetria e curtose de excesso são nulas.","fundamento":"Distribuição normal — propriedades.","macete":"Normal: as três medidas centrais no mesmo ponto.","erroComum":"Aplicar a divergência típica de distribuições assimétricas.","comoBancaPensa":"Item correto de fundamento, base para questões de padronização."}},"ES-107":{"cognitivo":{"motivo":"Fixar a fórmula correta de padronização.","palavraCritica":"divisão pela variância"},"comentario":{"resolucao":"ERRADO. A normal padrão realmente tem média 0 e desvio padrão 1, mas a padronização é Z = (X − μ)/σ, ou seja, divide-se pelo DESVIO PADRÃO, não pela variância. Dividir por σ² não produziria escore com desvio padrão unitário.","fundamento":"Padronização — escore Z.","macete":"Z = (X − μ)/σ.","erroComum":"Usar σ² no denominador.","comoBancaPensa":"Mantém correta a parte fácil (média 0, DP 1) e altera o denominador da fórmula."}},"ES-108":{"cognitivo":{"motivo":"Fixar a correspondência correta da regra empírica 68-95-99,7.","palavraCritica":"um desvio padrão"},"comentario":{"resolucao":"ERRADO. Em um desvio padrão em torno da média (μ ± 1σ) concentram-se cerca de 68% das observações. Os 95% correspondem a μ ± 2σ, e aproximadamente 99,7% a μ ± 3σ.","fundamento":"Regra empírica (68-95-99,7).","macete":"2 sigmas ≈ 95%; 1 sigma ≈ 68%.","erroComum":"Deslocar o percentual em um sigma.","comoBancaPensa":"Aproveita que o candidato memoriza os percentuais sem parear com o número de desvios."}},"ES-109":{"cognitivo":{"motivo":"Ligar exponencial e Poisson e fixar a propriedade característica.","palavraCritica":"falta de memória"},"comentario":{"resolucao":"CERTO. Se as ocorrências seguem processo de Poisson com taxa λ, o tempo entre ocorrências consecutivas segue exponencial de parâmetro λ. A falta de memória significa que o tempo já decorrido não altera a probabilidade de espera adicional — é a única contínua com essa propriedade.","fundamento":"Distribuição exponencial — relação com Poisson.","macete":"Exponencial = tempo de espera, sem memória.","erroComum":"Dissociar exponencial de Poisson.","comoBancaPensa":"Item correto que cobra a ligação entre os dois modelos."}},"ES-110":{"cognitivo":{"motivo":"Fixar a variância da uniforme contínua.","palavraCritica":"/2"},"comentario":{"resolucao":"ERRADO. A densidade é de fato constante, f(x) = 1/(b − a) no intervalo, mas a variância da uniforme contínua é (b − a)²/12, e não (b − a)²/2. O divisor 2 pertence à média, que é o ponto médio (a + b)/2.","fundamento":"Distribuição uniforme contínua.","macete":"Média sobre 2; variância sobre 12.","erroComum":"Trocar o divisor da variância pelo da média.","comoBancaPensa":"Mantém correta a primeira metade e altera apenas o denominador da fórmula."}},"ES-111":{"cognitivo":{"motivo":"Fixar a diferença essencial entre variáveis discretas e contínuas.","palavraCritica":"exatamente um valor pontual ... zero"},"comentario":{"resolucao":"CERTO. Para variáveis contínuas, a probabilidade corresponde à área sob a função densidade em um intervalo; um único ponto delimita área nula, de modo que P(X = a) = 0. Consequência prática: incluir ou excluir o extremo não altera a probabilidade do intervalo.","fundamento":"Variáveis aleatórias contínuas — função densidade.","macete":"Ponto isolado: probabilidade zero.","erroComum":"Aplicar raciocínio de variável discreta.","comoBancaPensa":"Item correto e contraintuitivo, que separa quem entendeu densidade de quem decorou."}},"ES-112":{"cognitivo":{"motivo":"Fixar a regra da adição em sua forma geral.","palavraCritica":"− P(A ∩ B)"},"comentario":{"resolucao":"CERTO. É a regra geral da adição: P(A ∪ B) = P(A) + P(B) − P(A ∩ B). O termo subtraído corrige a dupla contagem do espaço comum; em eventos mutuamente excludentes ele é zero.","fundamento":"Axiomas de probabilidade — regra da adição.","macete":"Sempre desconte a interseção.","erroComum":"Somar direto, tratando todos os eventos como excludentes.","comoBancaPensa":"Item correto que serve de base para pegadinhas sobre exclusividade."}},"ES-113":{"cognitivo":{"motivo":"Separar exclusividade mútua de independência.","palavraCritica":"necessariamente independentes"},"comentario":{"resolucao":"ERRADO. É o oposto: eventos mutuamente excludentes com probabilidades positivas são necessariamente DEPENDENTES. Se A ocorre, B não pode ocorrer, o que é a maior dependência possível. Formalmente, P(A ∩ B) = 0, mas P(A)·P(B) > 0, violando a condição de independência.","fundamento":"Probabilidade — independência e exclusividade.","macete":"Excludente ≠ independente; com prob. positiva, são opostos.","erroComum":"Tratar os dois conceitos como sinônimos.","comoBancaPensa":"Explora a confusão terminológica mais clássica da probabilidade."}},"ES-114":{"cognitivo":{"motivo":"Fixar a definição de probabilidade condicional.","palavraCritica":"probabilidade de B"},"comentario":{"resolucao":"CERTO. Por definição, P(A|B) = P(A ∩ B)/P(B), para P(B) > 0. O condicionamento restringe o espaço amostral a B, e por isso o denominador é a probabilidade de B.","fundamento":"Probabilidade condicional.","macete":"Denominador é o evento condicionante.","erroComum":"Inverter e dividir por P(A).","comoBancaPensa":"Item correto que sustenta questões de Bayes."}},"ES-115":{"cognitivo":{"motivo":"Fixar a definição do erro tipo I e sua relação com α.","palavraCritica":"rejeitar ... verdadeira"},"comentario":{"resolucao":"CERTO. O erro tipo I é a rejeição incorreta de H₀ verdadeira, e sua probabilidade é justamente o nível de significância α — os testes são construídos para controlar esse erro.","fundamento":"Teste de hipóteses — erros tipo I e II.","macete":"Tipo I = rejeição incorreta = α.","erroComum":"Inverter com o erro tipo II.","comoBancaPensa":"Item correto sobre o par de definições mais cobrado da inferência."}},"ES-116":{"cognitivo":{"motivo":"Cobrar o trade-off entre os dois tipos de erro.","palavraCritica":"diminui simultaneamente"},"comentario":{"resolucao":"ERRADO. Com o tamanho da amostra fixo, α e β variam em sentidos opostos: ao reduzir o nível de significância, exige-se evidência mais forte para rejeitar H₀, o que aumenta a probabilidade de erro tipo II. Reduzir ambos simultaneamente só é possível aumentando o tamanho da amostra.","fundamento":"Teste de hipóteses — trade-off α × β.","macete":"Com n fixo, α e β são gangorra.","erroComum":"Achar que rigor maior reduz todos os erros.","comoBancaPensa":"Oferece um 'ganho duplo' que viola o trade-off fundamental do teste."}},"ES-117":{"cognitivo":{"motivo":"Corrigir a interpretação equivocada mais comum do p-valor.","palavraCritica":"probabilidade de a hipótese nula ser verdadeira"},"comentario":{"resolucao":"ERRADO. O p-valor é a probabilidade de se observar um resultado tão ou mais extremo que o obtido, SUPONDO a hipótese nula verdadeira. Não é a probabilidade de H₀ ser verdadeira — a estatística clássica não atribui probabilidade a hipóteses. Rejeita-se H₀ quando o p-valor é inferior a α.","fundamento":"Teste de hipóteses — p-valor (nível descritivo).","macete":"p-valor mede os dados, não a hipótese.","erroComum":"Inverter o condicionamento.","comoBancaPensa":"Explora o erro de interpretação mais difundido da inferência clássica."}},"ES-118":{"cognitivo":{"motivo":"Fixar a definição de poder do teste.","palavraCritica":"erro do tipo II"},"comentario":{"resolucao":"CERTO. O poder do teste é 1 − β, ou seja, a probabilidade de rejeitar corretamente uma hipótese nula falsa. Aumenta com o tamanho da amostra e com o afastamento entre o valor hipotético e o real.","fundamento":"Teste de hipóteses — poder.","macete":"Poder = 1 − β.","erroComum":"Confundir com o nível de confiança (1 − α).","comoBancaPensa":"Item correto que separa poder de confiança."}},"ES-119":{"cognitivo":{"motivo":"Fixar o que a não rejeição de H₀ significa — e o que não significa.","palavraCritica":"equivale a demonstrar"},"comentario":{"resolucao":"ERRADO. Não rejeitar H₀ significa apenas que a evidência amostral foi insuficiente para rejeitá-la ao nível de significância adotado — o que pode decorrer de amostra pequena ou baixo poder do teste. A hipótese nula nunca é provada; ela é apenas mantida por falta de evidência contrária.","fundamento":"Teste de hipóteses — lógica da decisão.","macete":"Não rejeitar não é provar.","erroComum":"Tratar a não rejeição como confirmação de H₀.","comoBancaPensa":"Explora a leitura intuitiva de 'aceitar a hipótese' como demonstração."}},"ES-120":{"cognitivo":{"motivo":"Fixar o campo de aplicação do qui-quadrado.","palavraCritica":"qualitativas ... observadas ... esperadas"},"comentario":{"resolucao":"CERTO. O qui-quadrado de independência avalia associação entre duas variáveis qualitativas em tabela de contingência, confrontando frequências observadas e esperadas sob a hipótese de independência, pela soma de (O − E)²/E.","fundamento":"Teste qui-quadrado de independência.","macete":"Qualitativas + contagens = qui-quadrado.","erroComum":"Exigir variáveis quantitativas.","comoBancaPensa":"Item correto que fixa o único teste do edital voltado a dados categóricos."}},"ES-121":{"cognitivo":{"motivo":"Fixar a relação entre confiança e amplitude.","palavraCritica":"menor amplitude"},"comentario":{"resolucao":"ERRADO. É o contrário: elevar o nível de confiança (de 95% para 99%, por exemplo) exige valor crítico maior e, portanto, intervalo MAIS AMPLO. Só é possível estreitar o intervalo mantendo a confiança aumentando o tamanho da amostra ou reduzindo a variabilidade.","fundamento":"Estimação intervalar — confiança × precisão.","macete":"Mais confiança = intervalo mais largo.","erroComum":"Supor ganho simultâneo de confiança e precisão.","comoBancaPensa":"Oferece um ganho sem custo, invertendo o trade-off do intervalo."}},"ES-122":{"cognitivo":{"motivo":"Corrigir a interpretação frequentista do intervalo de confiança.","palavraCritica":"daquele intervalo já calculado"},"comentario":{"resolucao":"ERRADO. Na abordagem clássica, o parâmetro é uma constante desconhecida e o intervalo já calculado ou o contém ou não. A confiança de 95% refere-se ao procedimento: se o processo de amostragem fosse repetido muitas vezes, cerca de 95% dos intervalos construídos conteriam o parâmetro.","fundamento":"Estimação intervalar — interpretação frequentista.","macete":"95% dos intervalos, não 95% de chance neste.","erroComum":"Atribuir probabilidade ao parâmetro.","comoBancaPensa":"Explora a interpretação intuitiva porém incorreta do intervalo."}},"ES-123":{"cognitivo":{"motivo":"Fixar a definição de não viés.","palavraCritica":"esperança ... igual ao parâmetro"},"comentario":{"resolucao":"CERTO. Um estimador é não viesado (não tendencioso) quando sua esperança coincide com o parâmetro. A média amostral é estimador não viesado da média populacional; a variância amostral com denominador n − 1 é não viesada da variância populacional.","fundamento":"Estimação pontual — não viés.","macete":"Não viesado: acerta na média.","erroComum":"Confundir com consistência.","comoBancaPensa":"Item correto sobre a propriedade mais cobrada de estimadores."}},"ES-124":{"cognitivo":{"motivo":"Fixar o critério que define amostragem probabilística.","palavraCritica":"conhecida e não nula"},"comentario":{"resolucao":"CERTO. A amostragem probabilística exige que cada elemento tenha probabilidade conhecida e maior que zero de integrar a amostra, condição que viabiliza o cálculo do erro amostral e a inferência para a população. As modalidades não probabilísticas (conveniência, julgamento, cotas) não atendem a esse requisito.","fundamento":"Amostragem probabilística × não probabilística.","macete":"Probabilística: chance conhecida e positiva para todos.","erroComum":"Tratar amostra grande como sinônimo de probabilística.","comoBancaPensa":"Item correto que fundamenta a distinção entre os dois grupos de técnicas."}},"ES-125":{"cognitivo":{"motivo":"Separar as duas técnicas probabilísticas mais confundidas.","palavraCritica":"homogêneos ... heterogêneos"},"comentario":{"resolucao":"CERTO. Na estratificada busca-se homogeneidade interna nos estratos (e heterogeneidade entre eles), retirando-se elementos de cada estrato. Na amostragem por conglomerados, cada grupo idealmente reproduz a população (heterogêneo internamente) e sorteiam-se conglomerados inteiros, o que reduz custo mas tende a elevar o erro amostral.","fundamento":"Amostragem estratificada e por conglomerados.","macete":"Estrato: homogêneo e todos entram. Conglomerado: heterogêneo e sorteia-se o grupo.","erroComum":"Inverter a homogeneidade interna das duas técnicas.","comoBancaPensa":"Item correto que cobra a distinção integral entre as duas."}},"ES-126":{"cognitivo":{"motivo":"Fixar a classificação da amostragem sistemática.","palavraCritica":"não probabilística"},"comentario":{"resolucao":"ERRADO. A amostragem sistemática é PROBABILÍSTICA: define-se o intervalo k = N/n, sorteia-se aleatoriamente o primeiro elemento entre os k iniciais e selecionam-se os demais de k em k. A aleatoriedade do ponto de partida garante probabilidade conhecida de seleção. São não probabilísticas as amostragens por conveniência, por julgamento e por cotas. Ressalva: a técnica pode gerar viés se a lista apresentar periodicidade coincidente com o intervalo.","fundamento":"Amostragem sistemática — classificação.","macete":"Início sorteado ⇒ probabilística.","erroComum":"Considerá-la não probabilística pela regularidade do passo.","comoBancaPensa":"Oferece um argumento plausível (regra fixa) para uma classificação errada."}},"ES-127":{"cognitivo":{"motivo":"Fixar o alcance do teorema central do limite.","palavraCritica":"ainda que a população ... não siga distribuição normal"},"comentario":{"resolucao":"CERTO. O teorema central do limite garante que, para n suficientemente grande, a distribuição da média amostral tende à normal, independentemente da distribuição da população de origem (desde que a variância seja finita). É esse resultado que sustenta a inferência baseada na normal em amostras grandes.","fundamento":"Teorema central do limite.","macete":"TCL: a média fica normal, mesmo com população torta.","erroComum":"Exigir população normal para aplicar o TCL.","comoBancaPensa":"Item correto sobre o teorema mais cobrado da inferência."}},"ES-128":{"cognitivo":{"motivo":"Fixar a fórmula do erro padrão.","palavraCritica":"pelo tamanho da amostra"},"comentario":{"resolucao":"ERRADO. O erro padrão da média é σ/√n — divide-se pela RAIZ QUADRADA do tamanho da amostra, não por n. É por isso que ganhos de precisão são cada vez mais caros: reduzir o erro à metade exige amostra quatro vezes maior.","fundamento":"Distribuição amostral da média — erro padrão.","macete":"σ sobre raiz de n.","erroComum":"Dividir por n.","comoBancaPensa":"Suprime a raiz, um dos erros de fórmula mais explorados."}},"ES-129":{"cognitivo":{"motivo":"Delimitar o que o coeficiente de Pearson mede.","palavraCritica":"qualquer relação"},"comentario":{"resolucao":"ERRADO. O intervalo de −1 a 1 está correto, mas r próximo de zero indica ausência de relação LINEAR, e não de qualquer relação. Variáveis com associação não linear forte (parabólica, por exemplo) podem apresentar coeficiente de Pearson próximo de zero.","fundamento":"Coeficiente de correlação de Pearson.","macete":"Pearson só enxerga reta.","erroComum":"Concluir independência a partir de r ≈ 0.","comoBancaPensa":"Amplia a conclusão para além do que o coeficiente mede."}},"ES-130":{"cognitivo":{"motivo":"Fixar a interpretação do R².","palavraCritica":"proporção da variabilidade"},"comentario":{"resolucao":"CERTO. O R² expressa a fração da variabilidade total da variável dependente explicada pela regressão, variando de 0 a 1. Na regressão linear simples equivale ao quadrado do coeficiente de correlação de Pearson.","fundamento":"Regressão linear — coeficiente de determinação.","macete":"R² = r² na regressão simples.","erroComum":"Confundir com o coeficiente angular.","comoBancaPensa":"Item correto sobre a medida de ajuste mais cobrada."}},"ES-131":{"cognitivo":{"motivo":"Separar associação de causalidade.","palavraCritica":"suficiente ... causa"},"comentario":{"resolucao":"ERRADO. Correlação mede associação, não causa. A relação observada pode resultar de variável confundidora, de causalidade em sentido inverso ou de mera coincidência (correlação espúria). A inferência causal exige delineamento experimental ou controle estatístico adequado.","fundamento":"Correlação × causalidade.","macete":"Correlação não prova causa.","erroComum":"Inferir causalidade de coeficiente alto.","comoBancaPensa":"Item clássico que testa rigor interpretativo."}},"ES-132":{"cognitivo":{"motivo":"Mostrar propriedade matemática genuinamente universal.","palavraCritica":"qualquer ... sempre"},"comentario":{"resolucao":"CERTO. Para X ~ Poisson(λ), demonstra-se que E(X) = Var(X) = λ, qualquer que seja o valor de λ. É propriedade definidora do modelo, não uma aproximação.","fundamento":"Distribuição de Poisson — momentos.","macete":"Poisson: média = variância.","erroComum":"Rejeitar por conter 'qualquer' e 'sempre'.","comoBancaPensa":"Usa termos absolutos em afirmação matematicamente verdadeira."}},"ES-133":{"cognitivo":{"motivo":"Fixar axioma que não admite exceção.","palavraCritica":"necessariamente"},"comentario":{"resolucao":"CERTO. A normalização é axioma da função de probabilidade: a soma sobre todo o suporte deve ser exatamente 1. Distribuição cuja soma difere de 1 simplesmente não é válida.","fundamento":"Axiomas de Kolmogorov — normalização.","macete":"Soma sempre 1.","erroComum":"Marcar ERRADO por causa de 'toda'.","comoBancaPensa":"Aplica termo absoluto a axioma, que por natureza não tem exceção."}},"ES-134":{"cognitivo":{"motivo":"Reforçar propriedade universal da normal.","palavraCritica":"Toda ... qualquer"},"comentario":{"resolucao":"CERTO. A simetria em torno da média é característica de toda a família normal; o desvio padrão determina a dispersão (curva mais achatada ou mais estreita), mas o coeficiente de assimetria permanece zero.","fundamento":"Distribuição normal — propriedades.","macete":"σ muda a largura, não a simetria.","erroComum":"Rejeitar por causa do 'toda'.","comoBancaPensa":"Termos absolutos aplicados a propriedade universal."}},"ES-135":{"cognitivo":{"motivo":"Fixar o critério definidor, que por ser definição não admite exceção.","palavraCritica":"toda ... todos"},"comentario":{"resolucao":"CERTO. É a própria definição de amostragem probabilística: probabilidade conhecida e não nula de seleção para todos os elementos, condição que viabiliza o cálculo do erro amostral. Se algum elemento não pudesse ser sorteado, tratar-se-ia de amostragem não probabilística.","fundamento":"Amostragem probabilística — definição.","macete":"É definição, não regra com exceção.","erroComum":"Buscar contraexemplo para uma definição.","comoBancaPensa":"Usa termo absoluto em enunciado que é definição conceitual."}},"ES-136":{"cognitivo":{"motivo":"Fixar a definição de mediana e sua robustez.","palavraCritica":"menos sensível a valores extremos"},"comentario":{"resolucao":"CERTO. A mediana é o valor central dos dados ordenados e, por depender apenas da posição, resiste a valores extremos — motivo pelo qual é preferida à média em distribuições assimétricas, como as de renda.","fundamento":"Estatística descritiva — medidas de tendência central.","macete":"Mediana é robusta a outlier.","erroComum":"Atribuir a robustez à média.","comoBancaPensa":"Definição correta acompanhada da propriedade que a justifica."}},"ES-137":{"cognitivo":{"motivo":"Separar as duas técnicas pelo objetivo.","palavraCritica":"mede ... estabelece um modelo"},"comentario":{"resolucao":"CERTO. A correlação quantifica intensidade e sentido da associação (r entre −1 e 1); a regressão ajusta um modelo (na forma simples, uma reta) que permite estimar a variável dependente a partir da explicativa.","fundamento":"Correlação e regressão linear.","macete":"Correlação mede, regressão prevê.","erroComum":"Tratar como sinônimos.","comoBancaPensa":"Par correto entre técnicas complementares."}},"ES-138":{"cognitivo":{"motivo":"O que define conglomerado é a unidade sorteada ser um GRUPO, e não o indivíduo.","palavraCritica":"Dez celas foram selecionadas"},"comentario":{"resolucao":"CERTO. Na amostragem por CONGLOMERADOS, a população é dividida em grupos naturalmente formados (aqui, as celas), sorteiam-se alguns grupos inteiros e pesquisam-se TODOS os elementos dos grupos sorteados. Foi exatamente o procedimento: a unidade sorteada foi a cela, não o detento, e dentro das dez celas ninguém foi selecionado — todos entraram. Não confunda com a ESTRATIFICADA, em que a população se divide em estratos homogêneos e se sorteiam indivíduos DE TODOS os estratos. A diferença prática é de custo e precisão: conglomerado é mais barato (concentra o trabalho de campo em poucos pontos) e menos preciso; estratificada é mais cara e mais precisa.","fundamento":"Técnicas de amostragem probabilística.","macete":"Conglomerado: sorteia GRUPOS e pesquisa todos. Estratificada: sorteia DENTRO de todos os grupos.","erroComum":"Responder estratificada por haver divisão da população em subgrupos.","comoBancaPensa":"Descreve o procedimento em detalhe e pede o nome; o dado decisivo é 'todos os detentos encontrados'."}},"ES-139":{"cognitivo":{"motivo":"Estratificar por variável correlacionada reduz a variância do estimador e estreita o intervalo de confiança.","palavraCritica":"mais precisa"},"comentario":{"resolucao":"CERTO. A amostragem estratificada divide a população em estratos internamente HOMOGÊNEOS quanto à variável de interesse e heterogêneos entre si. Como a variância total se decompõe em variância dentro dos estratos e entre estratos, e a estratificada só carrega a primeira, o erro padrão do estimador cai — e intervalo de confiança mais estreito é exatamente o que se chama de estimação mais precisa. A condição para o ganho é que a variável de estratificação se correlacione com a estudada; renda e estatura guardam correlação conhecida via nutrição, o que justifica o desenho. Estratificar por variável irrelevante não piora, mas também não melhora.","fundamento":"Teoria da amostragem — decomposição da variância e eficiência da estratificação.","macete":"Estratos homogêneos por dentro reduzem a variância e estreitam o intervalo.","erroComum":"Achar que qualquer estratificação melhora a precisão, independentemente da variável.","comoBancaPensa":"Liga desenho amostral a consequência inferencial, em vez de pedir a definição."}},"ES-140":{"cognitivo":{"motivo":"Alfa e potência caminham no MESMO sentido; o que se opõe a alfa é beta.","palavraCritica":"diminuiria"},"comentario":{"resolucao":"ERRADO — a potência AUMENTA. O nível de significância (alfa) é a probabilidade do erro tipo I, rejeitar H0 verdadeira. Elevá-lo de 0,01 para 0,05 amplia a região de rejeição, tornando mais fácil rejeitar H0 — tanto quando ela é verdadeira (mais erro tipo I) quanto quando é falsa (mais acerto). E potência é justamente 1 - beta, a probabilidade de rejeitar H0 falsa. Logo, subir alfa reduz beta e aumenta a potência. O trade-off real é entre os DOIS ERROS, não entre alfa e potência: com n fixo, diminuir um tipo de erro aumenta o outro. A única forma de melhorar os dois ao mesmo tempo é aumentar a amostra — que é exatamente o que ES-142 cobra.","fundamento":"Teoria dos testes de hipóteses — erros tipo I e II, potência.","macete":"Alfa sobe, beta desce, potência sobe. Alfa e potência andam juntas.","erroComum":"Supor que qualquer aumento de alfa piora o teste em tudo.","comoBancaPensa":"Aposta na intuição de que 'aumentar o erro admitido piora o teste'."}},"ES-141":{"cognitivo":{"motivo":"Interpretação direta da potência como probabilidade de detecção sob uma alternativa específica.","palavraCritica":"verdadeiro valor"},"comentario":{"resolucao":"CERTO. POTÊNCIA é a probabilidade de rejeitar H0 quando H0 é falsa — a chance de o teste DETECTAR um efeito que realmente existe. Potência de 0,9 significa 90% de probabilidade de detecção, e portanto 10% de erro tipo II (beta), ou seja, de deixar passar o efeito. Duas precisões que a banca costuma cobrar em seguida: a potência é sempre calculada CONTRA UM VALOR ESPECÍFICO da alternativa — quanto maior o efeito real, maior a potência —, e por isso não existe 'a potência do teste' em abstrato. Por convenção, estudos são planejados para potência mínima de 0,80.","fundamento":"Teoria dos testes de hipóteses — potência e erro tipo II.","macete":"Potência = chance de enxergar o efeito que existe. 1 - beta.","erroComum":"Ler potência como confiança do intervalo, ou como complemento de alfa.","comoBancaPensa":"Enuncia a definição em linguagem corrente para testar se o candidato a reconhece fora do jargão."}},"ES-142":{"cognitivo":{"motivo":"Fecha o bloco: o trade-off entre os dois erros só é rompido aumentando n.","palavraCritica":"aumentado o tamanho da amostra"},"comentario":{"resolucao":"CERTO, e é a chave de todo o bloco. Com n FIXO, alfa e beta se opõem: reduzir um aumenta o outro. Aumentar n reduz o erro padrão (que decresce na razão da raiz de n), estreitando as distribuições amostrais sob H0 e sob H1 e diminuindo a sobreposição entre elas — o que permite ser mais rigoroso (alfa menor) e ainda assim mais sensível (potência maior). É por isso que o cálculo do tamanho amostral é etapa obrigatória no planejamento de um estudo: fixam-se alfa, a potência desejada e o efeito mínimo de interesse, e daí se deriva o n necessário.","fundamento":"Teoria dos testes de hipóteses — relação entre n, alfa, beta e potência.","macete":"Amostra maior compra os dois: rigor e sensibilidade.","erroComum":"Aplicar o trade-off alfa/beta como se valesse mesmo com n variável.","comoBancaPensa":"Usa 'simultaneamente' para induzir a resposta ERRADO em quem decorou o trade-off sem a condição de n fixo."}},"ES-143":{"cognitivo":{"motivo":"A normal é uma família de dois parâmetros — média e variância a determinam por completo.","palavraCritica":"além da"},"comentario":{"resolucao":"ERRADO. A distribuição normal fica COMPLETAMENTE determinada por dois parâmetros: a média (mu) e a variância (sigma ao quadrado). Conhecidos os dois, toda a curva está definida, e nenhuma outra informação amostral acrescenta nada à estimação pontual. Mais que isso: a média e a variância amostrais são estatísticas SUFICIENTES para a normal, o que significa, tecnicamente, que resumem toda a informação que a amostra carrega sobre os parâmetros. Assimetria e curtose, por exemplo, são fixas na normal (0 e 3), e por isso não servem para estimar coisa alguma — servem, sim, para TESTAR se a normalidade é plausível, que é problema diferente.","fundamento":"Distribuição normal — parâmetros e estatísticas suficientes.","macete":"Normal = dois parâmetros. Média e variância esgotam a informação.","erroComum":"Confundir estimar os parâmetros com verificar a aderência à normalidade.","comoBancaPensa":"Sugere que 'mais informação é sempre melhor', o que é falso quando há suficiência."}},"ES-144":{"cognitivo":{"motivo":"Fórmula objetiva: a média da uniforme é (a+b)/2, e o item apaga o 'a'.","palavraCritica":"b/2"},"comentario":{"resolucao":"ERRADO. A média amostral é estimador NÃO VIESADO da média populacional, de modo que seu valor esperado é a própria média da população. Para a uniforme contínua em [a, b], essa média é (a + b)/2 — o ponto médio do intervalo, por simetria da densidade. O item escreve b/2, expressão que só coincidiria com a correta no caso particular de a = 0. Guarde o par completo da uniforme contínua, que costuma ser cobrado junto: média (a+b)/2 e variância (b-a)²/12.","fundamento":"Distribuição uniforme contínua — momentos; propriedade do estimador não viesado.","macete":"Uniforme: média é o meio do intervalo, (a+b)/2.","erroComum":"Aceitar b/2 por parecer a metade do intervalo quando se ignora o limite inferior.","comoBancaPensa":"Suprime um termo da fórmula, deixando uma expressão que funciona num caso particular."}},"ES-145":{"cognitivo":{"motivo":"Par direto de ES-144: a outra metade da fórmula da uniforme.","palavraCritica":"12"},"comentario":{"resolucao":"CERTO. A variância da uniforme contínua em [a, b] é (b - a)²/12, e o desvio padrão, portanto, (b - a)/raiz de 12. Note a coerência interna da fórmula: a variância depende só da AMPLITUDE do intervalo, não de onde ele está na reta — deslocar o intervalo não muda a dispersão, o que é exatamente o esperado. O denominador 12 é o alvo preferido de adulteração nas versões seguintes (aparece como 2, 4 ou 6). Junte com ES-144 e o par fica completo: média (a+b)/2, variância (b-a)²/12.","fundamento":"Distribuição uniforme contínua — momentos.","macete":"Uniforme: média soma e divide por 2; variância subtrai, eleva ao quadrado e divide por 12.","erroComum":"Trocar o denominador ou usar (b+a) no lugar de (b-a).","comoBancaPensa":"Cobra a fórmula literal; a versão errada mexe no denominador."}},"ES-146":{"cognitivo":{"motivo":"As tarefas mais características da mineração — agrupamento e regras de associação — são NÃO supervisionadas.","palavraCritica":"exclusivamente"},"comentario":{"resolucao":"ERRADO. A mineração de dados abrange tanto o aprendizado SUPERVISIONADO (classificação e regressão, com dados rotulados) quanto o NÃO SUPERVISIONADO (agrupamento, regras de associação, detecção de anomalias, redução de dimensionalidade), além de abordagens semissupervisionadas. Aliás, as tarefas mais emblemáticas da área são não supervisionadas: a segmentação de clientes por clustering e a análise de cesta de compras por regras de associação. Em investigação criminal, a detecção de anomalias em transações financeiras é exemplo direto — não há rótulo prévio de 'suspeito' para aprender.","fundamento":"Fundamentos de mineração de dados e aprendizado de máquina.","macete":"Supervisionado tem rótulo. Não supervisionado descobre a estrutura sozinho.","erroComum":"Reduzir mineração a modelos preditivos com variável alvo.","comoBancaPensa":"O 'exclusivamente' faz todo o trabalho; sem ele o item seria correto."}},"ES-147":{"cognitivo":{"motivo":"Definição-base, par direto de ES-146.","palavraCritica":"rotulados"},"comentario":{"resolucao":"CERTO. No aprendizado SUPERVISIONADO, o modelo é treinado com exemplos em que a resposta correta já é conhecida — os dados ROTULADOS — e aprende a função que mapeia entradas em saídas, para depois generalizar sobre dados novos. Divide-se em CLASSIFICAÇÃO, quando a saída é categórica (fraude/não fraude), e REGRESSÃO, quando é numérica (valor previsto). O nome 'supervisionado' vem daí: o rótulo funciona como professor que corrige o modelo a cada erro durante o treino. O risco típico é o overfitting — decorar o conjunto de treino e generalizar mal —, controlado por separação entre treino, validação e teste.","fundamento":"Fundamentos de aprendizado de máquina.","macete":"Rótulo é o gabarito do treino. Com gabarito, é supervisionado.","erroComum":"Confundir com o não supervisionado, que não tem variável alvo.","comoBancaPensa":"Item de fixação, sempre acompanhado de outro com 'exclusivamente' ou 'somente'."}},"ES-148":{"cognitivo":{"motivo":"Reconhecer o ponto: leitura de gráfico — crescimento e estabilização.","palavraCritica":"aumentou continuamente"},"comentario":{"resolucao":"ERRADO. A velocidade cresce só até 4.000 m; daí até 8.000 m (altitude máxima) permanece constante em 800 km/h. Não aumentou continuamente até a altitude máxima.","fundamento":"Leitura de gráfico de linhas.","macete":"Trecho horizontal = valor constante.","erroComum":"Achar que o fim do crescimento coincide com o fim do voo.","comoBancaPensa":"Ignora o patamar."}},"ES-149":{"cognitivo":{"motivo":"Reconhecer o ponto: taxa de variação no trecho linear.","palavraCritica":"1 km/h para cada acréscimo de 5 m"},"comentario":{"resolucao":"CERTO. No trecho crescente, 800 km/h em 4.000 m: 800/4.000 = 0,2 km/h por metro = 1 km/h a cada 5 m.","fundamento":"Taxa de variação.","macete":"Δy/Δx.","erroComum":"Inverter a razão.","comoBancaPensa":"Conta simples."}},"ES-150":{"cognitivo":{"motivo":"Reconhecer o ponto: gráfico com eixos trocados.","palavraCritica":"de forma correta"},"comentario":{"resolucao":"ERRADO. O gráfico proposto põe 5, 10 e 25 (frequências) no eixo das idades e alturas de 7 a 9 nas barras: os papéis de idade e frequência estão trocados. O correto seria barras de altura 25, 10 e 5 nas idades 7, 8 e 9.","fundamento":"Gráfico de barras.","macete":"Eixo horizontal: categorias; vertical: frequências.","erroComum":"Não conferir os eixos.","comoBancaPensa":"Inverte os eixos."}},"ES-151":{"cognitivo":{"motivo":"Reconhecer o ponto: frequência relativa.","palavraCritica":"25%"},"comentario":{"resolucao":"CERTO. 10 crianças de 8 anos em 40: 10/40 = 25%.","fundamento":"Frequência relativa.","macete":"Parte ÷ total.","erroComum":"Usar 25 (frequência dos 7 anos).","comoBancaPensa":"Confusão de linha."}},"ES-152":{"cognitivo":{"motivo":"Reconhecer o ponto: comparação relativa entre grupos.","palavraCritica":"mais de 50%"},"comentario":{"resolucao":"CERTO. Homens: 10 + 15 + 30 = 55; mulheres: 5 + 10 + 20 = 35. 55/35 ≈ 1,57: a proporção de homens supera a de mulheres em cerca de 57%, mais de 50%.","fundamento":"Comparação de proporções.","macete":"'Maior em x%' = razão − 1.","erroComum":"Comparar diferença absoluta.","comoBancaPensa":"Exige razão relativa."}},"ES-153":{"cognitivo":{"motivo":"Reconhecer o ponto: frequência relativa de classe.","palavraCritica":"menor que 0,3"},"comentario":{"resolucao":"CERTO. A classe 1,61 a 1,70 tem 4 dos 20 alunos: 4/20 = 0,2 < 0,3.","fundamento":"Frequência relativa.","macete":"Parte ÷ total.","erroComum":"Somar classes.","comoBancaPensa":"Conta direta."}},"ES-154":{"cognitivo":{"motivo":"Reconhecer o ponto: combinação de dois gráficos.","palavraCritica":"menos de 5.500 mulheres"},"comentario":{"resolucao":"ERRADO. Menores de 20 anos: 15% + 20% = 35% de 31.700 = 11.095 pessoas. Se em cada faixa há mais mulheres que homens, elas são mais da metade: mais de 5.547 — não menos de 5.500.","fundamento":"Leitura combinada de gráficos.","macete":"Some as faixas e tome mais da metade.","erroComum":"Usar só uma faixa.","comoBancaPensa":"Exige combinar os gráficos."}},"ES-155":{"cognitivo":{"motivo":"Reconhecer o ponto: crescimento relativo por década.","palavraCritica":"década de 1990 a 2000"},"comentario":{"resolucao":"CERTO. Taxas: 1980–90: 21,8/19,2 ≈ +13,5%; 1990–2000: 26,2/21,8 ≈ +20,2%; 2000–10: ≈ +9,5%; 2010–20: ≈ +10,5%. O maior crescimento proporcional foi de 1990 a 2000.","fundamento":"Variação percentual.","macete":"Proporcional = relativo, não absoluto.","erroComum":"Comparar diferenças absolutas.","comoBancaPensa":"Absoluto x relativo."}},"ES-156":{"cognitivo":{"motivo":"Reconhecer o ponto: projeção com taxa constante.","palavraCritica":"superior a 38 mil"},"comentario":{"resolucao":"ERRADO. Taxa 2010–2020: 31,7/28,7 ≈ 1,1045. Em 2030: 31,7 × 1,1045 ≈ 35,0 mil, não superior a 38 mil.","fundamento":"Projeção por taxa.","macete":"Multiplique pelo mesmo fator.","erroComum":"Somar a diferença absoluta.","comoBancaPensa":"Valor inflado."}},"ES-157":{"cognitivo":{"motivo":"Reconhecer o ponto: soma de faixas.","palavraCritica":"pelos menos 15 mil"},"comentario":{"resolucao":"CERTO. 20 a 49 anos: 17% + 22% + 12% = 51% de 31.700 ≈ 16.167 pessoas: pelo menos 15 mil posições.","fundamento":"Porcentagem de gráfico de setores.","macete":"Some as fatias e aplique ao total.","erroComum":"Esquecer uma faixa.","comoBancaPensa":"Combina gráficos."}},"ES-158":{"cognitivo":{"motivo":"Reconhecer o ponto: menor diferença ano a ano.","palavraCritica":"ocorreu em 2014"},"comentario":{"resolucao":"CERTO. Anos iniciais − ensino médio: 2013: 242.749; 2014: 235.524; 2015: 236.014; 2016: 244.044; 2017: 251.923. A menor diferença é a de 2014.","fundamento":"Leitura de tabela.","macete":"Calcule todas as diferenças.","erroComum":"Comparar só dois anos.","comoBancaPensa":"Valores próximos (2014 x 2015)."}},"ES-159":{"cognitivo":{"motivo":"Reconhecer o ponto: menor variação entre 2013 e 2017.","palavraCritica":"educação infantil"},"comentario":{"resolucao":"ERRADO. Variações 2013–2017: infantil +78.730; anos iniciais +11.371; anos finais −38.171; ensino médio +2.197. A menor variação foi a do ensino médio; a da educação infantil foi a maior.","fundamento":"Variação absoluta.","macete":"Compare os módulos das variações.","erroComum":"Olhar só os valores finais.","comoBancaPensa":"Inverte maior e menor."}},"ES-160":{"cognitivo":{"motivo":"Reconhecer o ponto: tendência nas escolas especiais (gabarito do material).","palavraCritica":"decréscimo"},"comentario":{"resolucao":"ERRADO, segundo o gabarito do material. Observação: pelo gráfico, as matrículas nas escolas especiais caem de cerca de 16 mil para 8.910, o que configuraria decréscimo. A anotação do professor troca 'decréscimo' por 'acréscimo' e soma as duas redes (de 32.527 para 36.450 estudantes). O gabarito do QAP foi mantido; pela leitura literal do gráfico, o item estaria correto.","fundamento":"Leitura de gráfico de linhas.","macete":"Leia a série pedida no item.","erroComum":"Misturar as duas séries.","comoBancaPensa":"Explora a leitura do total x da série."}},"ES-161":{"cognitivo":{"motivo":"Reconhecer o ponto: estabilidade só em uma série.","palavraCritica":"tanto nas escolas regulares quanto nas escolas especiais"},"comentario":{"resolucao":"ERRADO. De 2008 a 2009, as escolas regulares ficaram estáveis, mas as especiais continuaram caindo. A estabilidade não vale para as duas.","fundamento":"Leitura de gráfico.","macete":"Confira cada série.","erroComum":"Generalizar.","comoBancaPensa":"Junta duas séries."}},"ES-162":{"cognitivo":{"motivo":"Reconhecer o ponto: menor crescimento entre edições.","palavraCritica":"área de ciência"},"comentario":{"resolucao":"ERRADO. De 2003 a 2009: leitura 403 → 412 (+9, com queda em 2006); ciência 390 → 405 (+15); matemática 356 → 386 (+30). O menor crescimento foi em leitura.","fundamento":"Leitura de gráfico.","macete":"Compare as variações no período pedido.","erroComum":"Olhar só uma edição.","comoBancaPensa":"Troca a área."}},"ES-163":{"cognitivo":{"motivo":"Reconhecer o ponto: padrão da série.","palavraCritica":"dois momentos de aumento"},"comentario":{"resolucao":"CERTO. Ciência: 375 → 390 (aumento), 390 → 390 (estagnação), 390 → 405 (aumento), 405 → 405 (estagnação).","fundamento":"Leitura de gráfico.","macete":"Descreva cada intervalo.","erroComum":"Contar mal os trechos.","comoBancaPensa":"Descrição de série."}},"ES-164":{"cognitivo":{"motivo":"Reconhecer o ponto: comparação em todas as edições.","palavraCritica":"Em todas as edições"},"comentario":{"resolucao":"CERTO. Leitura supera ciência e matemática em todas as edições: 396 > 375, 334; 403 > 390, 356; 393 > 390, 370; 412 > 405, 386; 410 > 405, 391.","fundamento":"Leitura de gráfico.","macete":"Para 'todas', confira uma a uma.","erroComum":"Achar que algum ano inverte.","comoBancaPensa":"Termo absoluto verdadeiro."}},"ES-165":{"cognitivo":{"motivo":"Reconhecer o ponto: variação do total.","palavraCritica":"mais de 200 processos"},"comentario":{"resolucao":"ERRADO. Total de 2010: 200 + 30 + 600 = 830; de 2012: 260 + 50 + 700 = 1.010. Acréscimo de 180, não mais de 200.","fundamento":"Leitura de tabela.","macete":"Some as colunas de cada ano.","erroComum":"Comparar só uma coluna.","comoBancaPensa":"Limite próximo."}},"ES-166":{"cognitivo":{"motivo":"Reconhecer o ponto: tabela acumulada.","palavraCritica":"representa, corretamente"},"comentario":{"resolucao":"ERRADO. Acumulando os novos registros: girocópteros 41, 44, 45, 50; helicópteros 24, 26, 26, 26; motoplanadores 6, 6, 6, 7. O quadro do item (41, 44, 43, 41 / 24, 25, 24, 24 / 6, 11, 6, 7) não corresponde.","fundamento":"Frequência acumulada.","macete":"Sem descredenciamento, o total só cresce.","erroComum":"Somar errado.","comoBancaPensa":"Quadro com quedas impossíveis."}},"ES-167":{"cognitivo":{"motivo":"Reconhecer o ponto: valor total.","palavraCritica":"inferior a 3 milhões"},"comentario":{"resolucao":"ERRADO. 41 × 10 mil + 24 × 800 mil + 6 × 120 mil = 410 mil + 19,2 milhões + 720 mil ≈ 20,3 milhões, muito acima de 3 milhões.","fundamento":"Média ponderada / soma.","macete":"Multiplique quantidade por preço.","erroComum":"Esquecer um tipo.","comoBancaPensa":"Valor muito abaixo."}},"ES-168":{"cognitivo":{"motivo":"Reconhecer o ponto: estatística x parâmetro.","palavraCritica":"parâmetro"},"comentario":{"resolucao":"CERTO. Estatística é uma medida calculada na amostra; parâmetro descreve uma característica da população.","fundamento":"Conceitos básicos de inferência.","macete":"Amostra → estatística; população → parâmetro.","erroComum":"Inverter os termos.","comoBancaPensa":"Conceito."}},"ES-169":{"cognitivo":{"motivo":"Reconhecer o ponto: amostra.","palavraCritica":"subconjunto da população"},"comentario":{"resolucao":"CERTO. Amostra é um subconjunto (parte) da população, usado para inferir sobre ela.","fundamento":"Conceitos básicos.","macete":"Amostra ⊂ população.","erroComum":"Confundir com censo.","comoBancaPensa":"Conceito."}},"ES-170":{"cognitivo":{"motivo":"Reconhecer o ponto: classificação de variáveis.","palavraCritica":"qualitativa ordinal"},"comentario":{"resolucao":"ERRADO. Tipo de minério (hematita, itabirito) é qualitativa NOMINAL, sem ordem natural. Além disso, profundidade (com valores como 250,5 m) é contínua e a produção mensal, registrada em número inteiro, é discreta — o item inverte as duas.","fundamento":"Tipos de variáveis.","macete":"Nominal: sem ordem; ordinal: com ordem.","erroComum":"Ver ordem onde não há.","comoBancaPensa":"Vários erros juntos."}},"ES-171":{"cognitivo":{"motivo":"Reconhecer o ponto: variável contínua.","palavraCritica":"contínuas"},"comentario":{"resolucao":"CERTO. Variáveis contínuas assumem qualquer valor num intervalo real, inclusive não inteiros (altura, peso, tempo).","fundamento":"Tipos de variáveis.","macete":"Contínua = mede; discreta = conta.","erroComum":"Achar que precisa ser inteira.","comoBancaPensa":"Conceito."}},"ES-172":{"cognitivo":{"motivo":"Reconhecer o ponto: variável dicotômica.","palavraCritica":"dicotômica"},"comentario":{"resolucao":"CERTO. Variável dicotômica é qualitativa com duas categorias (sim/não); é comum codificá-la com valores numéricos (0 e 1).","fundamento":"Tipos de variáveis.","macete":"Código numérico não torna a variável quantitativa.","erroComum":"Achar que número = quantitativa.","comoBancaPensa":"Conceito."}},"ES-173":{"cognitivo":{"motivo":"Reconhecer o ponto: faixa salarial (visão da banca).","palavraCritica":"métrica"},"comentario":{"resolucao":"CERTO, segundo o gabarito. A banca considerou a faixa salarial uma variável métrica por derivar de uma grandeza numérica (o salário) e preservar distâncias entre as faixas. Observação: em muitos manuais, faixas de valor marcadas pelo respondente são tratadas como variável ordinal; vale guardar a posição da banca neste item.","fundamento":"Níveis de mensuração.","macete":"Faixas de grandeza numérica foram tratadas como métricas pela banca.","erroComum":"Classificar como nominal.","comoBancaPensa":"Item de classificação discutível."}},"ES-174":{"cognitivo":{"motivo":"Reconhecer o ponto: dummies para k categorias.","palavraCritica":"variável dummy"},"comentario":{"resolucao":"ERRADO. Uma dummy é binária e codifica só 2 situações. Para 3 categorias são necessárias 2 dummies (k − 1).","fundamento":"Variáveis dummy.","macete":"k categorias → k − 1 dummies.","erroComum":"Achar que uma basta.","comoBancaPensa":"Conceito."}},"ES-175":{"cognitivo":{"motivo":"Reconhecer o ponto: média exige variável métrica.","palavraCritica":"métrica"},"comentario":{"resolucao":"CERTO. A média aritmética pressupõe valores numéricos com distâncias significativas (variável métrica). Para nominal usa-se a moda; para ordinal, a mediana.","fundamento":"Medidas por tipo de variável.","macete":"Média → métrica; mediana → ordinal; moda → qualquer.","erroComum":"Calcular média de códigos.","comoBancaPensa":"Conceito."}},"ES-176":{"cognitivo":{"motivo":"Reconhecer o ponto: ordinal é qualitativa.","palavraCritica":"quantitativas podem ser do tipo ordinais"},"comentario":{"resolucao":"ERRADO. Variáveis ordinais são qualitativas (categorias com ordem). As quantitativas são discretas ou contínuas.","fundamento":"Tipos de variáveis.","macete":"Ordinal fica do lado qualitativo.","erroComum":"Achar que ordem = número.","comoBancaPensa":"Troca a classificação."}},"ES-177":{"cognitivo":{"motivo":"Reconhecer o ponto: frequência relativa por linha.","palavraCritica":"estado E"},"comentario":{"resolucao":"CERTO. Corrupção / total do estado: A 15/67 ≈ 22%; B 20/63 ≈ 32%; C 12/55 ≈ 22%; D 5/55 ≈ 9%; E 30/65 ≈ 46%. A maior é a do estado E.","fundamento":"Frequência relativa.","macete":"Divida pelo total da linha.","erroComum":"Comparar valores absolutos.","comoBancaPensa":"Leitura de tabela."}},"ES-178":{"cognitivo":{"motivo":"Reconhecer o ponto: papel das cores.","palavraCritica":"pouca influência"},"comentario":{"resolucao":"ERRADO. Cores influenciam fortemente a leitura: destacam grupos, sugerem ordem e podem distorcer comparações. Não são mero detalhe estético.","fundamento":"Visualização de dados.","macete":"Cor é informação.","erroComum":"Tratar como estética.","comoBancaPensa":"Minimiza um fator relevante."}},"ES-179":{"cognitivo":{"motivo":"Reconhecer o ponto: dashboards interativos.","palavraCritica":"Dashboards interativos"},"comentario":{"resolucao":"CERTO. Dashboards interativos permitem filtrar e detalhar (drill-down), explorando os dados em vários níveis e apoiando decisões.","fundamento":"Visualização de dados.","macete":"Interatividade = níveis de detalhe.","erroComum":"Achar que só resumem.","comoBancaPensa":"Conceito."}},"ES-180":{"cognitivo":{"motivo":"Reconhecer o ponto: gráfico de barras.","palavraCritica":"Gráficos de barras"},"comentario":{"resolucao":"CERTO. Barras comparam bem quantidades entre categorias.","fundamento":"Escolha de gráfico.","macete":"Comparar categorias → barras.","erroComum":"Preferir pizza.","comoBancaPensa":"Conceito."}},"ES-181":{"cognitivo":{"motivo":"Reconhecer o ponto: limites do gráfico de pizza.","palavraCritica":"melhor escolha"},"comentario":{"resolucao":"ERRADO. Pizza só funciona bem com poucas categorias e partes de um todo; para muitos dados ou categorias, ela dificulta a comparação.","fundamento":"Escolha de gráfico.","macete":"Pizza: poucas fatias.","erroComum":"Achar que serve para tudo.","comoBancaPensa":"Termo absoluto."}},"ES-182":{"cognitivo":{"motivo":"Reconhecer o ponto: gráfico de setores para qualitativa.","palavraCritica":"gráfico de setores"},"comentario":{"resolucao":"CERTO. A distribuição de uma variável qualitativa (proporção de cada categoria) pode ser mostrada em setores.","fundamento":"Escolha de gráfico.","macete":"Setores = partes de um todo.","erroComum":"Achar que só serve barra.","comoBancaPensa":"Conceito."}},"ES-183":{"cognitivo":{"motivo":"Reconhecer o ponto: percentual complementar.","palavraCritica":"igual ou superior a 15%"},"comentario":{"resolucao":"ERRADO. Investimentos = 100% − 60% − 30% = 10%, não 15% ou mais.","fundamento":"Distribuição percentual.","macete":"As partes somam 100%.","erroComum":"Erro de conta.","comoBancaPensa":"Conta direta."}},"ES-184":{"cognitivo":{"motivo":"Reconhecer o ponto: altura é dado numérico.","palavraCritica":"dado numérico"},"comentario":{"resolucao":"CERTO. Altura é medida em escala numérica: variável quantitativa contínua.","fundamento":"Tipos de variáveis.","macete":"Medida → numérica.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-185":{"cognitivo":{"motivo":"Reconhecer o ponto: variável qualitativa.","palavraCritica":"Variáveis qualitativas"},"comentario":{"resolucao":"CERTO. Qualitativas expressam categorias que classificam os indivíduos.","fundamento":"Tipos de variáveis.","macete":"Qualitativa = categoria.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-186":{"cognitivo":{"motivo":"Reconhecer o ponto: representar discreta como contínua.","palavraCritica":"não é possível"},"comentario":{"resolucao":"ERRADO. Também é possível representar uma variável discreta como contínua, por exemplo agrupando valores em classes e usando histograma.","fundamento":"Representação gráfica.","macete":"Agrupar em classes aproxima do contínuo.","erroComum":"Achar que só vale num sentido.","comoBancaPensa":"Assimetria inventada."}},"ES-187":{"cognitivo":{"motivo":"Reconhecer o ponto: tamanho da amostra na acumulada.","palavraCritica":"210 observações"},"comentario":{"resolucao":"ERRADO. Na frequência acumulada, o último valor é o total: n = 60. 210 é a soma das acumuladas, que não tem significado.","fundamento":"Frequência acumulada.","macete":"Último acumulado = n.","erroComum":"Somar a coluna.","comoBancaPensa":"Erro clássico."}},"ES-188":{"cognitivo":{"motivo":"Reconhecer o ponto: tamanho da amostra na acumulada.","palavraCritica":"igual a 1.010"},"comentario":{"resolucao":"ERRADO. O último valor acumulado é o total: n = 250. 1.010 é a soma indevida das acumuladas.","fundamento":"Frequência acumulada.","macete":"Último acumulado = n.","erroComum":"Somar a coluna.","comoBancaPensa":"Erro clássico."}},"ES-189":{"cognitivo":{"motivo":"Reconhecer o ponto: gráfico de frequências acumuladas.","palavraCritica":"representa corretamente"},"comentario":{"resolucao":"ERRADO. O gráfico apresentado usa as alturas 120, 180, 220, 240 e 250 — as frequências acumuladas. A distribuição de frequências (simples) teria alturas 120, 60, 40, 20 e 10.","fundamento":"Frequência simples x acumulada.","macete":"Desacumule: subtraia o anterior.","erroComum":"Plotar a acumulada.","comoBancaPensa":"Usa a coluna errada."}},"ES-190":{"cognitivo":{"motivo":"Reconhecer o ponto: perda de informação na tabela.","palavraCritica":"recuperar os valores originais"},"comentario":{"resolucao":"ERRADO. A tabela de frequências diz quantas vezes cada categoria aparece, mas perde a ordem e a identificação de cada observação: não se recupera a série original.","fundamento":"Tabelas de frequência.","macete":"Resumir é perder detalhe.","erroComum":"Achar que nada se perde.","comoBancaPensa":"Conceito."}},"ES-191":{"cognitivo":{"motivo":"Reconhecer o ponto: gráfico de pontos.","palavraCritica":"representa corretamente"},"comentario":{"resolucao":"CERTO. O gráfico de pontos mostra 1 ponto em 0, 4 em 1, 1 em 2, 3 em 3 e 1 em 7, exatamente as frequências de {0, 1, 1, 1, 1, 2, 3, 3, 3, 7}.","fundamento":"Gráfico de pontos.","macete":"Conte os pontos por valor.","erroComum":"Esquecer o valor isolado.","comoBancaPensa":"Leitura de gráfico."}},"ES-192":{"cognitivo":{"motivo":"Reconhecer o ponto: box-plot para variável qualitativa.","palavraCritica":"diagrama de caixa"},"comentario":{"resolucao":"ERRADO. Escolaridade em três categorias é variável qualitativa (ordinal). O box-plot exige variável quantitativa (quartis, mediana); aqui cabem barras ou setores.","fundamento":"Escolha de gráfico.","macete":"Box-plot = dados numéricos.","erroComum":"Usar box-plot para categorias.","comoBancaPensa":"Gráfico inadequado."}},"ES-193":{"cognitivo":{"motivo":"Reconhecer o ponto: histograma — alturas.","palavraCritica":"proporcional à frequência"},"comentario":{"resolucao":"CERTO, segundo a banca. Em histogramas com classes de mesma amplitude, a altura das barras é proporcional à frequência de cada classe (com amplitudes diferentes, o rigor é a área ser proporcional).","fundamento":"Histograma.","macete":"Classes iguais: altura ∝ frequência.","erroComum":"Esquecer a ressalva das amplitudes.","comoBancaPensa":"Conceito."}},"ES-194":{"cognitivo":{"motivo":"Reconhecer o ponto: número de classes e perda de informação.","palavraCritica":"quanto maior for o número de classes"},"comentario":{"resolucao":"ERRADO. Quanto MAIS classes, mais estreitas elas são e MENOR a perda de informação. A perda aumenta quando há poucas classes largas.","fundamento":"Agrupamento em classes.","macete":"Mais classes, mais detalhe.","erroComum":"Inverter a relação.","comoBancaPensa":"Inverte a relação."}},"ES-195":{"cognitivo":{"motivo":"Reconhecer o ponto: média dos vizinhos ⇒ PA.","palavraCritica":"inferior a 40"},"comentario":{"resolucao":"ERRADO. Se cada termo é a média do anterior e do seguinte, a sequência é uma PA. Com ..., 21, 24, a razão é 3: os três anteriores a 21 são 18, 15 e 12, cuja soma é 45, não inferior a 40.","fundamento":"Média aritmética e PA.","macete":"Termo = média dos vizinhos ⇔ PA.","erroComum":"Achar a razão errada.","comoBancaPensa":"Liga média a sequência."}},"ES-196":{"cognitivo":{"motivo":"Reconhecer o ponto: média ponderada.","palavraCritica":"igual ou inferior a 3,0"},"comentario":{"resolucao":"ERRADO. Soma: 0×20 + 1×20 + 2×30 + 3×30 + 4×40 + 5×60 = 630. Média = 630/200 = 3,15, superior a 3.","fundamento":"Média ponderada.","macete":"Σ(x·f)/n.","erroComum":"Média simples das notas (2,5).","comoBancaPensa":"Limite próximo."}},"ES-197":{"cognitivo":{"motivo":"Reconhecer o ponto: segundo quartil = mediana.","palavraCritica":"segundo quartil"},"comentario":{"resolucao":"ERRADO. Q2 é a mediana: média da 100.ª e da 101.ª observações. Acumuladas: 0 → 20; 1 → 40; 2 → 70; 3 → 100; 4 → 140. A 100.ª é 3 e a 101.ª é 4: Q2 = 3,5, não 3.","fundamento":"Quartis em dados tabelados.","macete":"Q2 = mediana; use as acumuladas.","erroComum":"Pegar só a 100.ª.","comoBancaPensa":"Posição de fronteira."}},"ES-198":{"cognitivo":{"motivo":"Reconhecer o ponto: média não informa a mediana.","palavraCritica":"mais da metade"},"comentario":{"resolucao":"ERRADO. Uma média 8,0 não garante que mais da metade tenha nota ≥ 8,0: notas muito altas de poucos podem puxar a média. A informação seria da mediana, não da média.","fundamento":"Média x mediana.","macete":"Metade acima/abaixo é papel da mediana.","erroComum":"Confundir média e mediana.","comoBancaPensa":"Troca de medidas."}},"ES-199":{"cognitivo":{"motivo":"Reconhecer o ponto: média ponderada.","palavraCritica":"igual a 5,5"},"comentario":{"resolucao":"ERRADO. (4×8 + 5×10 + 6×6 + 7×1)/25 = 125/25 = 5,0, não 5,5.","fundamento":"Média ponderada.","macete":"Σ(x·f)/n.","erroComum":"Média simples (5,5).","comoBancaPensa":"Usa a média simples dos valores."}},"ES-200":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana e moda.","palavraCritica":"mesmo valor da moda"},"comentario":{"resolucao":"CERTO. A moda é 5,0 (frequência 10). A mediana é a 13.ª nota: acumuladas 8 (nota 4) e 18 (nota 5) ⇒ 5,0. Iguais.","fundamento":"Mediana e moda.","macete":"Mediana pela acumulada.","erroComum":"Errar a posição.","comoBancaPensa":"Conta direta."}},"ES-201":{"cognitivo":{"motivo":"Reconhecer o ponto: média por unidade.","palavraCritica":"inferior a 60"},"comentario":{"resolucao":"ERRADO. Totais: 67 + 63 + 55 + 55 + 65 = 305. Média = 305/5 = 61, não inferior a 60.","fundamento":"Média aritmética.","macete":"Some os totais.","erroComum":"Errar a soma.","comoBancaPensa":"Limite próximo."}},"ES-202":{"cognitivo":{"motivo":"Reconhecer o ponto: moda entre categorias.","palavraCritica":"tráfico de entorpecentes"},"comentario":{"resolucao":"CERTO. Totais por tipo: tráfico 135; lavagem 88; corrupção 82. A categoria mais frequente (moda) é o tráfico de entorpecentes.","fundamento":"Moda de variável qualitativa.","macete":"Moda = categoria mais frequente.","erroComum":"Olhar só um estado.","comoBancaPensa":"Leitura de tabela."}},"ES-203":{"cognitivo":{"motivo":"Reconhecer o ponto: média com classes pelos quartis.","palavraCritica":"superior a 18"},"comentario":{"resolucao":"CERTO. Classes [2, 12], [12, 18], [18, 24] e [24, 60], cada uma com 25% dos dados. Pontos médios: 7, 15, 21 e 42. Média = (7 + 15 + 21 + 42)/4 = 21,25, superior a 18.","fundamento":"Média de dados agrupados.","macete":"Cada quartil delimita 25%.","erroComum":"Usar a mediana como média.","comoBancaPensa":"Exige montar as classes."}},"ES-204":{"cognitivo":{"motivo":"Reconhecer o ponto: média de histograma.","palavraCritica":"R$ 3.300"},"comentario":{"resolucao":"CERTO. Pontos médios × frequências: 1.000×50 + 3.000×20 + 5.000×10 + 7.000×10 + 9.000×5 + 11.000×5 = 330.000. Média = 330.000/100 = R$ 3.300.","fundamento":"Média de dados agrupados.","macete":"Use o ponto médio de cada classe.","erroComum":"Usar os limites.","comoBancaPensa":"Cálculo."}},"ES-205":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana de histograma.","palavraCritica":"R$ 6.000"},"comentario":{"resolucao":"ERRADO. As 50 primeiras observações estão na classe 0–2.000; a mediana (entre a 50.ª e a 51.ª) fica em R$ 2.000, longe de R$ 6.000.","fundamento":"Mediana de dados agrupados.","macete":"Ache a classe que contém 50%.","erroComum":"Pegar o meio do eixo.","comoBancaPensa":"Confunde meio do intervalo com mediana."}},"ES-206":{"cognitivo":{"motivo":"Reconhecer o ponto: moda de histograma.","palavraCritica":"superior a R$ 6.000"},"comentario":{"resolucao":"ERRADO. A classe modal é 0–2.000 (50 observações); a moda está abaixo de R$ 2.000.","fundamento":"Moda de dados agrupados.","macete":"Classe modal = barra mais alta.","erroComum":"Escolher outra classe.","comoBancaPensa":"Valor oposto."}},"ES-207":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana — ordenar antes.","palavraCritica":"igual a 98"},"comentario":{"resolucao":"ERRADO. Ordenando: 98, 102, 105, 110, 115. A mediana é 105. 98 é o mínimo.","fundamento":"Mediana.","macete":"Ordene os dados.","erroComum":"Pegar o valor do meio sem ordenar.","comoBancaPensa":"Dados fora de ordem."}},"ES-208":{"cognitivo":{"motivo":"Reconhecer o ponto: q1 x média.","palavraCritica":"inferior à média"},"comentario":{"resolucao":"CERTO. Média = 530/5 = 106. Q1 fica entre 98 e 102 (por qualquer método usual, no máximo 102), inferior a 106.","fundamento":"Quartis.","macete":"Q1 cai na metade inferior.","erroComum":"Confundir Q1 com mediana.","comoBancaPensa":"Comparação."}},"ES-209":{"cognitivo":{"motivo":"Reconhecer o ponto: média x mediana.","palavraCritica":"média é superior à mediana"},"comentario":{"resolucao":"CERTO. Ordenando os 12 valores: 1,7; 1,7; 1,8; 1,8; 1,8; 1,9; 1,9; 2,0; 2,0; 2,1; 2,1; 2,2. Mediana = (1,9 + 1,9)/2 = 1,9. Média 1,92 > 1,9.","fundamento":"Mediana com n par.","macete":"Média dos dois centrais.","erroComum":"Errar a ordenação.","comoBancaPensa":"Valores próximos."}},"ES-210":{"cognitivo":{"motivo":"Reconhecer o ponto: média x moda.","palavraCritica":"110% do valor da moda"},"comentario":{"resolucao":"ERRADO. Moda = 1,8 (três ocorrências). 110% de 1,8 = 1,98; a média 1,92 não supera esse valor.","fundamento":"Moda.","macete":"Calcule o limite pedido.","erroComum":"Errar a moda.","comoBancaPensa":"Limite próximo."}},"ES-211":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana de 7 valores.","palavraCritica":"mediana igual a 8"},"comentario":{"resolucao":"ERRADO. Com 7 valores ordenados, a mediana é o 4.º: 6.","fundamento":"Mediana.","macete":"n ímpar: posição (n + 1)/2.","erroComum":"Errar a posição.","comoBancaPensa":"Conta direta."}},"ES-212":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana com n par.","palavraCritica":"R$ 62,5 mil"},"comentario":{"resolucao":"ERRADO. 20 valores: mediana = média do 10.º e 11.º (51 e 52) = 51,5 mil. 62,5 mil é o ponto médio entre mínimo e máximo.","fundamento":"Mediana.","macete":"Use as posições centrais.","erroComum":"Fazer (45 + 80)/2.","comoBancaPensa":"Confunde mediana com ponto médio."}},"ES-213":{"cognitivo":{"motivo":"Reconhecer o ponto: moda.","palavraCritica":"R$ 47 mil"},"comentario":{"resolucao":"CERTO. 47 aparece três vezes, mais que qualquer outro valor: moda = 47 mil.","fundamento":"Moda.","macete":"Valor mais frequente.","erroComum":"Escolher 45 (duas vezes).","comoBancaPensa":"Conta direta."}},"ES-214":{"cognitivo":{"motivo":"Reconhecer o ponto: primeiro quartil.","palavraCritica":"910 mil"},"comentario":{"resolucao":"ERRADO. Ordenando: 790, 820, 860, 870, 910. 910 é o máximo; Q1 fica entre 790 e 820.","fundamento":"Quartis.","macete":"Q1 na parte baixa.","erroComum":"Confundir com o máximo.","comoBancaPensa":"Valor do extremo."}},"ES-215":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana.","palavraCritica":"860 mil"},"comentario":{"resolucao":"CERTO. Ordenados: 790, 820, 860, 870, 910. Mediana (3.º) = 860.","fundamento":"Mediana.","macete":"Ordene.","erroComum":"Não ordenar (870).","comoBancaPensa":"Dados fora de ordem."}},"ES-216":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana com n par.","palavraCritica":"R$ 2,50"},"comentario":{"resolucao":"CERTO. Ordenados: 0, 0, 0, 1, 2, 3, 3, 3, 4, 5. Mediana = (2 + 3)/2 = 2,5.","fundamento":"Mediana.","macete":"Ordene e tome os dois centrais.","erroComum":"Não ordenar.","comoBancaPensa":"Dados fora de ordem."}},"ES-217":{"cognitivo":{"motivo":"Reconhecer o ponto: distribuição bimodal.","palavraCritica":"R$ 5,00"},"comentario":{"resolucao":"ERRADO. 0 e 3 aparecem três vezes cada: a distribuição é bimodal (0 e 3). 5 aparece uma vez.","fundamento":"Moda.","macete":"Pode haver mais de uma moda.","erroComum":"Pegar o maior valor.","comoBancaPensa":"Confunde moda com máximo."}},"ES-218":{"cognitivo":{"motivo":"Reconhecer o ponto: simetria perfeita.","palavraCritica":"perfeitamente simétrico"},"comentario":{"resolucao":"CERTO. Em distribuição simétrica (e unimodal), média, mediana e moda coincidem; as três são medidas de tendência central.","fundamento":"Medidas de tendência central.","macete":"Simétrica: média = mediana = moda.","erroComum":"Achar que a moda difere.","comoBancaPensa":"Conceito."}},"ES-219":{"cognitivo":{"motivo":"Reconhecer o ponto: média de cinco anos.","palavraCritica":"superior a 6.100"},"comentario":{"resolucao":"CERTO. 2015–2019: 6.038 + 6.027 + 6.000 + 6.111 + 6.432 = 30.608; média = 6.121,6, superior a 6.100.","fundamento":"Média.","macete":"Some e divida.","erroComum":"Pegar anos errados.","comoBancaPensa":"Limite próximo."}},"ES-220":{"cognitivo":{"motivo":"Reconhecer o ponto: novo valor e média.","palavraCritica":"diminuirá"},"comentario":{"resolucao":"ERRADO. A média 2015–2019 é 6.121,6. Um valor de 2020 só baixa a média se for menor que 6.121,6; valores entre 6.121,6 e 6.200 a aumentariam. Ser inferior a 6.200 não basta.","fundamento":"Efeito de um novo dado na média.","macete":"Compare o novo valor com a média atual.","erroComum":"Comparar com 6.200.","comoBancaPensa":"Limite errado."}},"ES-221":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana — ordenar, não usar anos.","palavraCritica":"2009 e 2010"},"comentario":{"resolucao":"ERRADO. Com 20 valores, a mediana é a média do 10.º e do 11.º valores ORDENADOS: 5.990 (2008) e 6.000 (2017). Usar os anos centrais da série (2009 e 2010) ignora a ordenação.","fundamento":"Mediana.","macete":"Ordene os valores, não os anos.","erroComum":"Pegar o meio cronológico.","comoBancaPensa":"Ordem temporal x ordem de valor."}},"ES-222":{"cognitivo":{"motivo":"Reconhecer o ponto: série amodal.","palavraCritica":"amodal"},"comentario":{"resolucao":"CERTO. Os 20 valores são todos diferentes; nenhum se repete. A série não tem moda (amodal).","fundamento":"Moda.","macete":"Sem repetição, sem moda.","erroComum":"Escolher o maior.","comoBancaPensa":"Conceito."}},"ES-223":{"cognitivo":{"motivo":"Reconhecer o ponto: média.","palavraCritica":"superior a 2"},"comentario":{"resolucao":"CERTO. Soma = 0 + 4 + 2 + 9 + 7 = 22; média = 22/10 = 2,2.","fundamento":"Média.","macete":"Some todos os valores.","erroComum":"Esquecer repetições.","comoBancaPensa":"Conta direta."}},"ES-224":{"cognitivo":{"motivo":"Reconhecer o ponto: primeiro quartil.","palavraCritica":"igual a 1"},"comentario":{"resolucao":"CERTO. Ordenados: 0, 1, 1, 1, 1, 2, 3, 3, 3, 7. A metade inferior (0, 1, 1, 1, 1) tem mediana 1: Q1 = 1.","fundamento":"Quartis.","macete":"Q1 = mediana da metade inferior.","erroComum":"Usar a posição errada.","comoBancaPensa":"Conta direta."}},"ES-225":{"cognitivo":{"motivo":"Reconhecer o ponto: moda.","palavraCritica":"igual a 7"},"comentario":{"resolucao":"ERRADO. A moda é 1 (quatro ocorrências). 7 é o máximo, que aparece uma vez.","fundamento":"Moda.","macete":"Mais frequente, não maior.","erroComum":"Confundir com o máximo.","comoBancaPensa":"Confusão clássica."}},"ES-226":{"cognitivo":{"motivo":"Reconhecer o ponto: média combinada.","palavraCritica":"inferior a 25 anos"},"comentario":{"resolucao":"CERTO. Soma antiga: 10 × 40 = 400. Soma nova: 16 × 34 = 544. Os 6 novos somam 144: média = 24, inferior a 25.","fundamento":"Média ponderada de grupos.","macete":"Trabalhe com somas.","erroComum":"Fazer média das médias.","comoBancaPensa":"Exige somas."}},"ES-227":{"cognitivo":{"motivo":"Reconhecer o ponto: média amostral.","palavraCritica":"superior a 1,5 m"},"comentario":{"resolucao":"ERRADO. Soma: 2,0 + 1,0 + 1,5 + 1,0 + 1,5 + 2,0 + 1,0 + 1,5 + 1,0 + 0,5 = 13,0; média = 1,3 m, inferior a 1,5.","fundamento":"Média.","macete":"Some e divida por 10.","erroComum":"Errar a soma.","comoBancaPensa":"Conta direta."}},"ES-228":{"cognitivo":{"motivo":"Reconhecer o ponto: média ponderada x moda.","palavraCritica":"igual a 7 anos"},"comentario":{"resolucao":"ERRADO. (7×25 + 8×10 + 9×5)/40 = 300/40 = 7,5 anos. 7 é a moda, não a média.","fundamento":"Média ponderada.","macete":"Σ(x·f)/n.","erroComum":"Confundir com a moda.","comoBancaPensa":"Usa a moda."}},"ES-229":{"cognitivo":{"motivo":"Reconhecer o ponto: média a partir de acumuladas.","palavraCritica":"inferior a 1"},"comentario":{"resolucao":"CERTO. Frequências simples: 120, 60, 40, 20, 10 (n = 250). Média = (0 + 60 + 80 + 60 + 40)/250 = 240/250 = 0,96.","fundamento":"Média de dados tabelados.","macete":"Desacumule antes.","erroComum":"Usar as acumuladas.","comoBancaPensa":"Tabela acumulada."}},"ES-230":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana a partir de acumuladas.","palavraCritica":"mediana de x é igual a 2"},"comentario":{"resolucao":"ERRADO. A mediana é a 125.ª/126.ª observação: as 120 primeiras são 0 e as de 121 a 180 são 1. Mediana = 1.","fundamento":"Mediana.","macete":"Localize a posição na acumulada.","erroComum":"Pegar o valor do meio (2).","comoBancaPensa":"Valor do meio da tabela."}},"ES-231":{"cognitivo":{"motivo":"Reconhecer o ponto: moda a partir de acumuladas.","palavraCritica":"moda da variável x é igual a 4"},"comentario":{"resolucao":"ERRADO. A maior frequência simples é a de x = 0 (120): moda = 0. A frequência acumulada máxima em x = 4 não indica moda.","fundamento":"Moda.","macete":"Moda vem da frequência simples.","erroComum":"Usar a acumulada.","comoBancaPensa":"Confunde acumulada com simples."}},"ES-232":{"cognitivo":{"motivo":"Reconhecer o ponto: média por pontos médios.","palavraCritica":"superior a 65"},"comentario":{"resolucao":"CERTO. Σ(ponto médio × %): 5×0,02 + 15×0,08 + 25×0,14 + 35×0,16 + 50×0,20 + 70×0,12 + 90×0,08 + 120×0,08 + 160×0,06 + 220×0,06 = 68,4, superior a 65.","fundamento":"Média de dados agrupados.","macete":"Use os pontos médios.","erroComum":"Esquecer as classes largas.","comoBancaPensa":"Classes com amplitudes diferentes."}},"ES-233":{"cognitivo":{"motivo":"Reconhecer o ponto: terceiro quartil por interpolação.","palavraCritica":"superior a 90"},"comentario":{"resolucao":"ERRADO. Acumulado: até 80 → 72%; a classe 80–100 tem 8%. Faltam 3 pontos para 75%: Q3 = 80 + 20 × 3/8 = 87,5, não superior a 90.","fundamento":"Quartis em dados agrupados.","macete":"Interpole dentro da classe.","erroComum":"Pegar o limite superior da classe.","comoBancaPensa":"Interpolação."}},"ES-234":{"cognitivo":{"motivo":"Reconhecer o ponto: classe modal (visão da banca).","palavraCritica":"moda da série será igual a 35"},"comentario":{"resolucao":"ERRADO, segundo o gabarito. A banca toma como modal a classe de maior frequência, 40–60 (20%), cujo ponto médio é 50 — não 35. Observação: com classes de amplitudes diferentes, há quem escolha a classe modal pela densidade (frequência ÷ amplitude), o que apontaria 30–40 (ponto médio 35); a banca não adotou esse critério.","fundamento":"Moda de dados agrupados.","macete":"Pela banca: maior frequência.","erroComum":"Escolher a barra mais alta do desenho.","comoBancaPensa":"Amplitudes diferentes confundem."}},"ES-235":{"cognitivo":{"motivo":"Reconhecer o ponto: q1 = Q3.","palavraCritica":"primeiro quartil é igual ao terceiro quartil"},"comentario":{"resolucao":"CERTO. Ordenados: 0, 0, 1, 2 (onze vezes), 3, 6. As posições do 1.º e do 3.º quartis (por volta da 4.ª/5.ª e da 12.ª/13.ª observações) caem no bloco de valores 2: Q1 = Q3 = 2.","fundamento":"Quartis.","macete":"Bloco grande de valores iguais absorve os quartis.","erroComum":"Achar que Q1 < Q3 sempre.","comoBancaPensa":"Dados concentrados."}},"ES-236":{"cognitivo":{"motivo":"Reconhecer o ponto: média, mediana e moda (gabarito do material).","palavraCritica":"iguais a 2"},"comentario":{"resolucao":"ERRADO, segundo o gabarito do material. Observação: com 2 zeros, um 1, onze 2, um 3 e um 6, a soma é 0 + 1 + 22 + 3 + 6 = 32 e a média é 32/16 = 2; mediana e moda também valem 2, o que tornaria o item correto. A anotação do professor soma 30 (média 1,875), o que parece erro de conta. O gabarito do QAP foi mantido.","fundamento":"Média, mediana e moda.","macete":"Some valor × frequência com cuidado.","erroComum":"Errar a soma.","comoBancaPensa":"Item de cálculo."}},"ES-237":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana com acumuladas.","palavraCritica":"igual a 2,5"},"comentario":{"resolucao":"CERTO. Acumuladas: 5, 15, 30, 45, 55, 60 (n = 60). A 30.ª observação é 2 e a 31.ª é 3: mediana = 2,5.","fundamento":"Mediana.","macete":"n par: média das centrais.","erroComum":"Pegar só a 30.ª.","comoBancaPensa":"Posição de fronteira."}},"ES-238":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana de seis valores.","palavraCritica":"inferior a 8 anos e 6 meses"},"comentario":{"resolucao":"ERRADO. Tempos: 2, 4, 8, 10, 12, 14. Mediana = (8 + 10)/2 = 9 anos, não inferior a 8,5.","fundamento":"Mediana.","macete":"n par: média dos centrais.","erroComum":"Pegar 8.","comoBancaPensa":"Limite próximo."}},"ES-239":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana x média.","palavraCritica":"mediana dessa sequência"},"comentario":{"resolucao":"CERTO. Ordenando: 1,57; 1,74; 1,74; 1,75; 1,77; 1,78; 1,8; 1,9; 1,95; 2. Mediana = (1,77 + 1,78)/2 = 1,775, inferior à média 1,8.","fundamento":"Mediana.","macete":"n = 10: média do 5.º e 6.º.","erroComum":"Errar a ordenação.","comoBancaPensa":"Valores próximos."}},"ES-240":{"cognitivo":{"motivo":"Reconhecer o ponto: moda x média.","palavraCritica":"10% superior"},"comentario":{"resolucao":"ERRADO. A moda é 1,74 (duas ocorrências), inferior à média 1,8. Não é 10% superior (seria 1,98).","fundamento":"Moda.","macete":"Moda = valor repetido.","erroComum":"Errar a moda.","comoBancaPensa":"Inverte a relação."}},"ES-241":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana de série recursiva.","palavraCritica":"mediana da série é 0"},"comentario":{"resolucao":"ERRADO. Termos: 3, −2, 1, −1, 0, −1, −1, −2, −3, −5, −8. Ordenados: −8, −5, −3, −2, −2, −1, −1, −1, 0, 1, 3. Mediana (6.º) = −1, não 0.","fundamento":"Mediana.","macete":"Gere os termos e ordene.","erroComum":"Não ordenar.","comoBancaPensa":"Exige gerar a sequência."}},"ES-242":{"cognitivo":{"motivo":"Reconhecer o ponto: moda de série recursiva.","palavraCritica":"moda da série é −1"},"comentario":{"resolucao":"CERTO. Termos: 3, −2, 1, −1, 0, −1, −1, −2, −3, −5, −8, −13, ... Para n ≥ 6, −1 aparece mais vezes (duas e depois três); os termos seguintes são todos distintos e decrescentes e não alcançam essa frequência.","fundamento":"Moda.","macete":"Veja quais termos se repetem.","erroComum":"Achar que −2 empata.","comoBancaPensa":"Exige observar o padrão."}},"ES-243":{"cognitivo":{"motivo":"Reconhecer o ponto: média = mediana sem simetria.","palavraCritica":"assimétrica"},"comentario":{"resolucao":"CERTO. {0, 0, 4, 6, 10}: média 20/5 = 4 e mediana 4. Mas os desvios não são espelhados (−4, −4, 0, 2, 6): a distribuição é assimétrica. Média = mediana não garante simetria.","fundamento":"Simetria e medidas centrais.","macete":"Igualdade média–mediana não prova simetria.","erroComum":"Concluir simetria.","comoBancaPensa":"Contraexemplo clássico."}},"ES-244":{"cognitivo":{"motivo":"Reconhecer o ponto: amplitude.","palavraCritica":"amplitude"},"comentario":{"resolucao":"ERRADO. Totais: 67, 63, 55, 55, 65. Amplitude = 67 − 55 = 12, não 14.","fundamento":"Amplitude total.","macete":"Máximo − mínimo.","erroComum":"Usar valores de uma coluna.","comoBancaPensa":"Valor próximo."}},"ES-245":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão.","palavraCritica":"inferior a 5"},"comentario":{"resolucao":"ERRADO. Média 61; desvios: 6, 2, −6, −6, 4; soma dos quadrados = 128. Desvio padrão populacional = √(128/5) ≈ 5,06; amostral = √(128/4) ≈ 5,66. Em qualquer caso, não é inferior a 5.","fundamento":"Desvio padrão.","macete":"Some os quadrados dos desvios.","erroComum":"Esquecer de elevar ao quadrado.","comoBancaPensa":"Limite próximo."}},"ES-246":{"cognitivo":{"motivo":"Reconhecer o ponto: variância de dados tabelados.","palavraCritica":"superior a 1"},"comentario":{"resolucao":"CERTO. Média 3,15. Σx²f = 0 + 20 + 120 + 270 + 640 + 1.500 = 2.550. Variância amostral = (2.550 − 200 × 3,15²)/199 ≈ 2,84, superior a 1.","fundamento":"Variância.","macete":"Use Σx²f − n·média².","erroComum":"Dividir por n − 1 ou n não muda a conclusão.","comoBancaPensa":"Conta longa."}},"ES-247":{"cognitivo":{"motivo":"Reconhecer o ponto: limite do desvio padrão pela amplitude.","palavraCritica":"igual ou inferior a 36"},"comentario":{"resolucao":"CERTO. Para dados entre 2 e 60 (amplitude 58), o desvio padrão não passa de metade da amplitude (29 meses, com o fator n/(n − 1) desprezível para n = 1.000). Logo é inferior a 36.","fundamento":"Limites do desvio padrão.","macete":"DP máximo ≈ amplitude/2.","erroComum":"Achar que precisa dos dados.","comoBancaPensa":"Usa uma cota."}},"ES-248":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão de dados agrupados.","palavraCritica":"inferior a R$ 6.000"},"comentario":{"resolucao":"CERTO. Com pontos médios e média 3.300: Σf(x − 3.300)² = 50 × 2.300² + 20 × 300² + 10 × 1.700² + 10 × 3.700² + 5 × 5.700² + 5 × 7.700² = 891 milhões; dividindo por 99, a variância é cerca de 9 milhões e o desvio padrão ≈ R$ 3.000, inferior a 6.000.","fundamento":"Desvio padrão de dados agrupados.","macete":"Use os pontos médios.","erroComum":"Calcular sem agrupar.","comoBancaPensa":"Exige cálculo."}},"ES-249":{"cognitivo":{"motivo":"Reconhecer o ponto: variância amostral.","palavraCritica":"44,5"},"comentario":{"resolucao":"CERTO. Média 106; desvios: −1, 9, −8, −4, 4; quadrados: 1 + 81 + 64 + 16 + 16 = 178. Variância amostral = 178/4 = 44,5.","fundamento":"Variância amostral.","macete":"Divida por n − 1.","erroComum":"Dividir por n (35,6).","comoBancaPensa":"n − 1 x n."}},"ES-250":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão a partir da variância.","palavraCritica":"inferior a 0,13"},"comentario":{"resolucao":"ERRADO. DP = √0,025 ≈ 0,158, superior a 0,13.","fundamento":"Desvio padrão.","macete":"DP = √variância.","erroComum":"Errar a raiz.","comoBancaPensa":"Raiz de número pequeno."}},"ES-251":{"cognitivo":{"motivo":"Reconhecer o ponto: ordem de grandeza do desvio padrão.","palavraCritica":"inferior a R$ 18 mil"},"comentario":{"resolucao":"CERTO. Média 54,6 mil; a maior parte dos valores está entre 45 e 60. O desvio padrão amostral é ≈ 9,9 mil, bem abaixo de 18 mil (a amplitude total é 35 mil).","fundamento":"Desvio padrão.","macete":"DP < amplitude/2 = 17,5.","erroComum":"Confundir com a amplitude.","comoBancaPensa":"Estimativa."}},"ES-252":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão amostral.","palavraCritica":"igual a 50 mil"},"comentario":{"resolucao":"ERRADO. Média 850; desvios: −30, −60, 20, 60, 10; quadrados: 900 + 3.600 + 400 + 3.600 + 100 = 8.600. DP amostral = √(8.600/4) ≈ 46,4 mil, não 50.","fundamento":"Desvio padrão.","macete":"Divida por n − 1.","erroComum":"Arredondar demais.","comoBancaPensa":"Valor próximo."}},"ES-253":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão amostral.","palavraCritica":"inferior a R$ 2,00"},"comentario":{"resolucao":"CERTO. Média 2,1; Σ(x − 2,1)² = 28,9. Variância amostral = 28,9/9 ≈ 3,21; DP ≈ 1,79, inferior a 2.","fundamento":"Desvio padrão.","macete":"Calcule a soma dos quadrados.","erroComum":"Dividir errado.","comoBancaPensa":"Limite próximo."}},"ES-254":{"cognitivo":{"motivo":"Reconhecer o ponto: amplitude.","palavraCritica":"amplitude"},"comentario":{"resolucao":"ERRADO. Amplitude = 13 − 5 = 8, não 9 (9 é a mediana).","fundamento":"Amplitude.","macete":"Máximo − mínimo.","erroComum":"Confundir com a mediana.","comoBancaPensa":"Usa outra medida."}},"ES-255":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio médio.","palavraCritica":"desvio em relação à média"},"comentario":{"resolucao":"ERRADO. Média = 60/8 = 7,5. Desvios absolutos: 0,5; 2,5; 2,5; 1,5; 0,5; 3,5; 1,5; 1,5 — soma 14. Desvio médio = 14/8 = 1,75, não 1,5. (A soma dos desvios com sinal é sempre 0.)","fundamento":"Desvio médio absoluto.","macete":"Use valores absolutos.","erroComum":"Somar com sinal.","comoBancaPensa":"Valor próximo."}},"ES-256":{"cognitivo":{"motivo":"Reconhecer o ponto: amplitude interquartil x amplitude total.","palavraCritica":"inferior a 43"},"comentario":{"resolucao":"CERTO. A amplitude interquartil (Q3 − Q1) nunca supera a amplitude total, que é 40. Logo é inferior a 43.","fundamento":"Medidas de dispersão.","macete":"Q3 − Q1 ≤ máximo − mínimo.","erroComum":"Tentar calcular os quartis.","comoBancaPensa":"Atalho lógico."}},"ES-257":{"cognitivo":{"motivo":"Reconhecer o ponto: amplitude grande e variância pequena.","palavraCritica":"amplitude seja um valor grande"},"comentario":{"resolucao":"CERTO. Um único valor extremo aumenta muito a amplitude, mas pouco a variância se os demais forem concentrados (ex.: 999 valores iguais e um outlier).","fundamento":"Sensibilidade das medidas.","macete":"Amplitude depende só dos extremos.","erroComum":"Achar que andam juntas.","comoBancaPensa":"Conceito."}},"ES-258":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão a partir do boxplot.","palavraCritica":"igual ou inferior a R$ 10 mil"},"comentario":{"resolucao":"CERTO. O boxplot vai de 30 a 50 (amplitude 20); o desvio padrão não passa de 10. Além disso, sob normalidade, DP ≈ IQR/1,35 = 7/1,35 ≈ 5,2 mil.","fundamento":"Boxplot e dispersão.","macete":"DP ≤ amplitude/2.","erroComum":"Achar que precisa dos dados.","comoBancaPensa":"Estimativa."}},"ES-259":{"cognitivo":{"motivo":"Reconhecer o ponto: coeficiente de variação.","palavraCritica":"coeficiente de variação"},"comentario":{"resolucao":"CERTO. CV 2020 = 1,6/3,5 ≈ 45,7%; CV 2024 = 1,4/4 = 35%. A variabilidade relativa foi maior em 2020.","fundamento":"Coeficiente de variação.","macete":"CV = DP/média.","erroComum":"Comparar só os DPs.","comoBancaPensa":"Conta direta."}},"ES-260":{"cognitivo":{"motivo":"Reconhecer o ponto: menor CV.","palavraCritica":"vara C"},"comentario":{"resolucao":"CERTO. CVs: A 12/50 = 24%; B 13,5/44 ≈ 31%; C 1,5/64 ≈ 2,3%; D 18,5/64 ≈ 29%. A vara C tem o menor.","fundamento":"Coeficiente de variação.","macete":"CV = DP/média.","erroComum":"Olhar só a mediana.","comoBancaPensa":"Leitura de tabela."}},"ES-261":{"cognitivo":{"motivo":"Reconhecer o ponto: amplitude x coeficiente de variação.","palavraCritica":"amplitude"},"comentario":{"resolucao":"ERRADO. DP ÷ média é o coeficiente de variação (dispersão relativa). A amplitude é máximo − mínimo, medida de dispersão absoluta.","fundamento":"Medidas de dispersão.","macete":"CV = DP/média; amplitude = máx − mín.","erroComum":"Trocar os nomes.","comoBancaPensa":"Troca de conceito."}},"ES-262":{"cognitivo":{"motivo":"Reconhecer o ponto: variância e soma de constante.","palavraCritica":"σ2 + k"},"comentario":{"resolucao":"ERRADO. Somar uma constante desloca os dados, mas não altera a dispersão: Var(X + k) = σ².","fundamento":"Propriedades da variância.","macete":"Soma não muda variância; multiplicação por c multiplica por c².","erroComum":"Somar k à variância.","comoBancaPensa":"Propriedade."}},"ES-263":{"cognitivo":{"motivo":"Reconhecer o ponto: comparar desvios padrão.","palavraCritica":"inferior"},"comentario":{"resolucao":"ERRADO. Precipitação: 50, 60, 40, 70, 50 (média 54); volume: 140, 150, 150, 170, 160 (média 154). Os desvios em relação à média são idênticos (−4, 6, −14, 16, −4 e −14, −4, −4, 16, 6, em outra ordem): mesmos desvios padrão (≈ 11,4).","fundamento":"Desvio padrão.","macete":"Mesmos desvios, mesmo DP.","erroComum":"Comparar médias.","comoBancaPensa":"Dados deslocados."}},"ES-264":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio máximo.","palavraCritica":"mais dispersas"},"comentario":{"resolucao":"CERTO. 2000–2004 (média 4.344): maior desvio |3.563 − 4.344| = 781. 2015–2019 (média 6.121,6): maior desvio |6.432 − 6.121,6| ≈ 310. Os primeiros cinco anos são mais dispersos.","fundamento":"Desvio máximo.","macete":"Maior distância à média.","erroComum":"Usar a amplitude errada.","comoBancaPensa":"Cálculo."}},"ES-265":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio médio de dados agrupados.","palavraCritica":"superior a 40"},"comentario":{"resolucao":"CERTO. Com média 68,4 e pontos médios, Σ|x − 68,4| × f ≈ 41,3, superior a 40.","fundamento":"Desvio médio.","macete":"Pondere as distâncias absolutas.","erroComum":"Esquecer as caudas.","comoBancaPensa":"Cálculo."}},"ES-266":{"cognitivo":{"motivo":"Reconhecer o ponto: maior contribuição à variância.","palavraCritica":"(30, 40)"},"comentario":{"resolucao":"ERRADO. Contribuição de cada classe: f × (x − 68,4)². A classe 180–260 (ponto médio 220, a 151,6 da média, com 6%) contribui ≈ 1.379, muito mais que a classe 30–40 (≈ 178). Valores distantes pesam mais.","fundamento":"Variância.","macete":"O quadrado do desvio amplifica as caudas.","erroComum":"Escolher a classe mais frequente.","comoBancaPensa":"Frequência x distância."}},"ES-267":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão amostral.","palavraCritica":"superior a 2"},"comentario":{"resolucao":"ERRADO. Média 2; desvios ao quadrado: 4, 4, 1, 0 (×11), 1, 16 ⇒ soma 26. Variância amostral = 26/15 ≈ 1,73; DP ≈ 1,32, não superior a 2.","fundamento":"Desvio padrão.","macete":"Muitos valores na média reduzem o DP.","erroComum":"Usar a amplitude.","comoBancaPensa":"Concentração."}},"ES-268":{"cognitivo":{"motivo":"Reconhecer o ponto: variância de dados acumulados.","palavraCritica":"inferior a 2"},"comentario":{"resolucao":"CERTO. Frequências simples: 5, 10, 15, 15, 10, 5 (n = 60), simétricas em torno de 2,5. Σf(x − 2,5)² = 5×6,25 + 10×2,25 + 15×0,25 + 15×0,25 + 10×2,25 + 5×6,25 = 115. Variância amostral = 115/59 ≈ 1,95.","fundamento":"Variância.","macete":"Desacumule primeiro.","erroComum":"Usar as acumuladas.","comoBancaPensa":"Limite próximo."}},"ES-269":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão amostral.","palavraCritica":"inferior a 2"},"comentario":{"resolucao":"CERTO. Média 2,2; Σ(x − 2,2)² = 35,6. Variância amostral = 35,6/9 ≈ 3,96; DP ≈ 1,99, inferior a 2.","fundamento":"Desvio padrão.","macete":"Conta cuidadosa — o limite é apertado.","erroComum":"Arredondar e errar.","comoBancaPensa":"Limite muito próximo."}},"ES-270":{"cognitivo":{"motivo":"Reconhecer o ponto: precisão x exatidão.","palavraCritica":"mais exatos"},"comentario":{"resolucao":"ERRADO. Menor desvio padrão indica maior PRECISÃO (repetibilidade). EXATIDÃO é a proximidade do valor verdadeiro e depende do viés, que o desvio padrão não mede.","fundamento":"Metrologia.","macete":"Precisão = dispersão; exatidão = acerto do alvo.","erroComum":"Usar como sinônimos.","comoBancaPensa":"Troca de conceito."}},"ES-271":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão.","palavraCritica":"inferior a 0,11"},"comentario":{"resolucao":"ERRADO. DP = √0,014 ≈ 0,118, superior a 0,11.","fundamento":"Desvio padrão.","macete":"√0,014.","erroComum":"Errar a raiz.","comoBancaPensa":"Limite próximo."}},"ES-272":{"cognitivo":{"motivo":"Reconhecer o ponto: coeficiente de variação.","palavraCritica":"inferior a 7%"},"comentario":{"resolucao":"CERTO. CV = 0,118/1,8 ≈ 6,6%, inferior a 7%: dispersão relativa baixa.","fundamento":"Coeficiente de variação.","macete":"CV = DP/média.","erroComum":"Usar a variância.","comoBancaPensa":"Conta."}},"ES-273":{"cognitivo":{"motivo":"Reconhecer o ponto: variância amostral.","palavraCritica":"igual a 14"},"comentario":{"resolucao":"CERTO. Média 14; desvios: −4, −2, −2, 4, 4; quadrados: 16 + 4 + 4 + 16 + 16 = 56. 56/4 = 14.","fundamento":"Variância amostral.","macete":"Divida por n − 1.","erroComum":"Dividir por 5 (11,2).","comoBancaPensa":"n − 1."}},"ES-274":{"cognitivo":{"motivo":"Reconhecer o ponto: razão de variâncias.","palavraCritica":"0,36"},"comentario":{"resolucao":"CERTO. X: 25, 20, 20, 20 (média 21,25): S(X) = 18,75/3 = 6,25. Y: 13, 10, 12, 10 (média 11,25): S(Y) = 6,75/3 = 2,25. 2,25/6,25 = 0,36.","fundamento":"Variância amostral.","macete":"Calcule as duas.","erroComum":"Errar uma média.","comoBancaPensa":"Duas contas."}},"ES-275":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão de série recursiva.","palavraCritica":"desvio padrão"},"comentario":{"resolucao":"ERRADO. Seis primeiros termos: 3, −2, 1, −1, 0, −1 (média 0). Σx² = 9 + 4 + 1 + 1 + 0 + 1 = 16. DP = √(16/6) ≈ 1,63 (ou √(16/5) ≈ 1,79), não 4. 4 é a raiz da soma dos quadrados.","fundamento":"Desvio padrão.","macete":"Divida antes de tirar a raiz.","erroComum":"Esquecer de dividir.","comoBancaPensa":"Erro de fórmula."}},"ES-276":{"cognitivo":{"motivo":"Reconhecer o ponto: coeficiente de variação.","palavraCritica":"superior a 0,008"},"comentario":{"resolucao":"ERRADO. Média = 6,456/5 = 1,2912. CV = 0,0092/1,2912 ≈ 0,0071, inferior a 0,008.","fundamento":"Coeficiente de variação.","macete":"CV = DP/média.","erroComum":"Dividir pela soma.","comoBancaPensa":"Valor próximo."}},"ES-277":{"cognitivo":{"motivo":"Reconhecer o ponto: cV e variância.","palavraCritica":"dobro da variância"},"comentario":{"resolucao":"ERRADO. Com médias iguais a 1, CV = DP. CV(V) = 2 CV(W) ⇒ DP(V) = 2 DP(W) ⇒ Var(V) = 4 Var(W), não o dobro.","fundamento":"CV e variância.","macete":"Variância escala com o quadrado.","erroComum":"Esquecer o quadrado.","comoBancaPensa":"Erro de escala."}},"ES-278":{"cognitivo":{"motivo":"Reconhecer o ponto: variância da diferença de independentes.","palavraCritica":"igual a 5"},"comentario":{"resolucao":"CERTO. Independentes: Var(V − W) = Var(V) + Var(W) = 9 + 16 = 25; DP = 5.","fundamento":"Variância de combinação linear.","macete":"Na diferença, as variâncias SOMAM.","erroComum":"Subtrair (DP = 1).","comoBancaPensa":"Clássico 3-4-5."}},"ES-279":{"cognitivo":{"motivo":"Reconhecer o ponto: amplitude.","palavraCritica":"igual a 20"},"comentario":{"resolucao":"ERRADO. Idades de 9 a 12: amplitude = 3. 20 é o número de estudantes.","fundamento":"Amplitude.","macete":"Máximo − mínimo.","erroComum":"Usar o n.","comoBancaPensa":"Confusão de dado."}},"ES-280":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão de dados binários.","palavraCritica":"igual ou superior a 1"},"comentario":{"resolucao":"ERRADO. Seis 1 e quatro 0: média 0,6; Σ(x − 0,6)² = 6 × 0,16 + 4 × 0,36 = 2,4. Variância amostral = 2,4/9 ≈ 0,27; DP ≈ 0,52, inferior a 1.","fundamento":"Desvio padrão.","macete":"Dados entre 0 e 1 têm DP < 1.","erroComum":"Achar que pode passar de 1.","comoBancaPensa":"Cota."}},"ES-281":{"cognitivo":{"motivo":"Reconhecer o ponto: variância amostral de tabela.","palavraCritica":"igual ou inferior a 18"},"comentario":{"resolucao":"ERRADO. Frequências 3, 6, 15, 6 (n = 30) para X = 0, 5, 10, 15; média 9. Σf(x − 9)² = 3×81 + 6×16 + 15×1 + 6×36 = 570. Variância amostral = 570/29 ≈ 19,7, superior a 18.","fundamento":"Variância.","macete":"Divida por n − 1.","erroComum":"Dividir por n (19).","comoBancaPensa":"Limite próximo."}},"ES-282":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão amostral.","palavraCritica":"igual ou inferior a 1,6"},"comentario":{"resolucao":"ERRADO. D = {0, 0, 1, 1, 2, 2, 2, 4, 6}: média 2; Σ(x − 2)² = 4 + 4 + 1 + 1 + 0 + 0 + 0 + 4 + 16 = 30. Variância amostral = 30/8 = 3,75; DP ≈ 1,94, superior a 1,6.","fundamento":"Desvio padrão.","macete":"Divida por n − 1.","erroComum":"Erro de soma.","comoBancaPensa":"Limite próximo."}},"ES-283":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão de três anos.","palavraCritica":"superior a 22"},"comentario":{"resolucao":"CERTO. Produção (milhões de t): 1995 — 310; 2000 — 327; 2005 — 410. Média ≈ 349; desvios ≈ −39, −22, 61. DP populacional ≈ 43,7; amostral ≈ 53,5. Superior a 22.","fundamento":"Desvio padrão.","macete":"Leia os valores do gráfico.","erroComum":"Usar anos errados.","comoBancaPensa":"Leitura de gráfico."}},"ES-284":{"cognitivo":{"motivo":"Reconhecer o ponto: coeficiente de variação.","palavraCritica":"maior que 1"},"comentario":{"resolucao":"ERRADO. Y é quantitativa (discreta), mas o CV não passa de 1: média 5; DP amostral ≈ 4,36 (populacional ≈ 4,04) ⇒ CV ≈ 0,87 (ou 0,81).","fundamento":"Coeficiente de variação.","macete":"CV = DP/média.","erroComum":"Aceitar a primeira parte e não checar a segunda.","comoBancaPensa":"Mistura verdade e erro."}},"ES-285":{"cognitivo":{"motivo":"Reconhecer o ponto: variância da diferença com covariância.","palavraCritica":"igual a 11"},"comentario":{"resolucao":"CERTO. Var(X − Y) = Var(X) + Var(Y) − 2Cov(X, Y) = 16 + 25 − 30 = 11.","fundamento":"Variância de combinação linear.","macete":"Na diferença, −2Cov.","erroComum":"Esquecer a covariância.","comoBancaPensa":"Fórmula."}},"ES-286":{"cognitivo":{"motivo":"Reconhecer o ponto: assimetria e posição de média e mediana.","palavraCritica":"sempre igual à média"},"comentario":{"resolucao":"ERRADO. Com assimetria (skewness ≠ 0), média e mediana tendem a se separar: a média é puxada para o lado da cauda. Não são 'sempre iguais'.","fundamento":"Assimetria.","macete":"Cauda puxa a média.","erroComum":"Achar que a mediana acompanha a média.","comoBancaPensa":"Termo absoluto."}},"ES-287":{"cognitivo":{"motivo":"Reconhecer o ponto: assimetria e valores extremos.","palavraCritica":"valores extremos"},"comentario":{"resolucao":"CERTO. Assimetria acentuada costuma vir de valores extremos numa das caudas, que alongam a distribuição desse lado.","fundamento":"Assimetria.","macete":"Cauda longa = valores extremos.","erroComum":"Confundir com curtose.","comoBancaPensa":"Conceito."}},"ES-288":{"cognitivo":{"motivo":"Reconhecer o ponto: coeficiente zero sem simetria plena.","palavraCritica":"não implica"},"comentario":{"resolucao":"CERTO. Um coeficiente de assimetria nulo indica equilíbrio das caudas por aquela medida, mas há distribuições não simétricas com coeficiente zero.","fundamento":"Assimetria.","macete":"Medida zero ≠ simetria garantida.","erroComum":"Tomar o número como prova.","comoBancaPensa":"Conceito."}},"ES-289":{"cognitivo":{"motivo":"Reconhecer o ponto: assimetria à esquerda.","palavraCritica":"média menor que a mediana"},"comentario":{"resolucao":"CERTO. Com cauda à esquerda (assimetria negativa), valores baixos puxam a média para baixo: em geral média < mediana < moda.","fundamento":"Assimetria negativa.","macete":"Média vai para o lado da cauda.","erroComum":"Inverter.","comoBancaPensa":"Conceito."}},"ES-290":{"cognitivo":{"motivo":"Reconhecer o ponto: assimetria negativa — direção da cauda.","palavraCritica":"cauda mais longa que se estende para a direita"},"comentario":{"resolucao":"ERRADO. Na assimetria negativa, a cauda longa fica à ESQUERDA e os valores se concentram à direita. O item descreve a assimetria positiva.","fundamento":"Assimetria.","macete":"O sinal acompanha o lado da cauda.","erroComum":"Associar 'negativa' a concentração à esquerda.","comoBancaPensa":"Inverte os lados."}},"ES-291":{"cognitivo":{"motivo":"Reconhecer o ponto: coeficiente quartílico.","palavraCritica":"igual a zero"},"comentario":{"resolucao":"CERTO. Bowley: (Q3 + Q1 − 2Q2)/(Q3 − Q1) = (24 + 12 − 36)/12 = 0 — os quartis são equidistantes da mediana.","fundamento":"Coeficiente de Bowley.","macete":"Q3 − Q2 = Q2 − Q1 ⇒ zero.","erroComum":"Usar os extremos.","comoBancaPensa":"Conta direta."}},"ES-292":{"cognitivo":{"motivo":"Reconhecer o ponto: concentração nas notas altas.","palavraCritica":"assimetria positiva"},"comentario":{"resolucao":"ERRADO. As notas se concentram nos valores altos (4 e 5 somam 100 das 200), com cauda para as notas baixas; a média (3,15) fica abaixo da mediana (3,5): assimetria negativa.","fundamento":"Assimetria.","macete":"Compare média e mediana.","erroComum":"Ver a cauda do lado errado.","comoBancaPensa":"Leitura de tabela."}},"ES-293":{"cognitivo":{"motivo":"Reconhecer o ponto: média < mediana < moda.","palavraCritica":"assimetria negativa"},"comentario":{"resolucao":"CERTO. Média 150 < mediana 152 < moda 154: padrão de assimetria negativa (cauda à esquerda).","fundamento":"Assimetria.","macete":"Média < mediana ⇒ negativa.","erroComum":"Inverter o sinal.","comoBancaPensa":"Leitura de tabela."}},"ES-294":{"cognitivo":{"motivo":"Reconhecer o ponto: cauda à direita.","palavraCritica":"cauda à direita"},"comentario":{"resolucao":"CERTO. Com cauda à direita (assimetria positiva), a massa dos dados fica à esquerda e poucos valores grandes se estendem à direita.","fundamento":"Assimetria positiva.","macete":"Cauda indica onde estão os raros.","erroComum":"Inverter.","comoBancaPensa":"Conceito."}},"ES-295":{"cognitivo":{"motivo":"Reconhecer o ponto: histograma com cauda à direita.","palavraCritica":"assimetria negativa"},"comentario":{"resolucao":"ERRADO. Metade das indenizações está na primeira classe e as frequências caem à direita: cauda longa à direita, assimetria POSITIVA. A média (3.300) supera a mediana (2.000).","fundamento":"Assimetria.","macete":"Concentração à esquerda + cauda à direita = positiva.","erroComum":"Associar concentração à esquerda a 'negativa'.","comoBancaPensa":"Inverte o sinal."}},"ES-296":{"cognitivo":{"motivo":"Reconhecer o ponto: média e DP não mostram assimetria.","palavraCritica":"suficientes"},"comentario":{"resolucao":"ERRADO. Média e desvio padrão descrevem centro e dispersão, mas não a forma. Distribuições com mesma média e DP podem ser simétricas ou assimétricas; é preciso, por exemplo, comparar com quantis ou calcular o 3.º momento.","fundamento":"Medidas de forma.","macete":"Forma exige outra medida.","erroComum":"Achar que DP revela forma.","comoBancaPensa":"Conceito."}},"ES-297":{"cognitivo":{"motivo":"Reconhecer o ponto: distribuição simétrica.","palavraCritica":"assimétrica"},"comentario":{"resolucao":"ERRADO. Frequências simples: 5, 10, 15, 15, 10, 5 para X = 0 a 5 — espelhadas em torno de 2,5, que é a média. A distribuição é simétrica.","fundamento":"Simetria.","macete":"Desacumule e compare as pontas.","erroComum":"Olhar as acumuladas.","comoBancaPensa":"Tabela acumulada."}},"ES-298":{"cognitivo":{"motivo":"Reconhecer o ponto: simetria em torno de 1.","palavraCritica":"simétrica em torno de 1"},"comentario":{"resolucao":"ERRADO. Os dados (seis 1 e quatro 0) têm média 0,6 e só tomam valores 0 e 1; não há simetria em torno de 1 (nenhum valor acima de 1 espelha os zeros).","fundamento":"Simetria.","macete":"Simetria exige espelhamento em torno do centro.","erroComum":"Usar a moda como centro.","comoBancaPensa":"Centro errado."}},"ES-299":{"cognitivo":{"motivo":"Reconhecer o ponto: média = mediana (gabarito do material).","palavraCritica":"pode ser considerada como simétrica"},"comentario":{"resolucao":"CERTO, segundo o gabarito. Média e mediana valem 1, e a banca aceitou tratar a distribuição como simétrica em torno da média. Observação: igualdade entre média e mediana não garante simetria; aqui os desvios (−1, −1, 0, 0, 0, 2) não são espelhados e o 3.º momento é positivo, como reconhece o item seguinte do mesmo caderno.","fundamento":"Simetria x medidas centrais.","macete":"Média = mediana é indício, não prova.","erroComum":"Tomar como prova.","comoBancaPensa":"Gabarito discutível."}},"ES-300":{"cognitivo":{"motivo":"Reconhecer o ponto: terceiro momento centrado.","palavraCritica":"μ3 > 0"},"comentario":{"resolucao":"CERTO. Desvios em relação à média 1: −1, −1, 0, 0, 0, 2. Cubos: −1, −1, 0, 0, 0, 8 ⇒ soma 6; μ3 = 1 > 0: assimetria à direita.","fundamento":"Momentos.","macete":"Sinal de μ3 = lado da cauda.","erroComum":"Esquecer o valor 3.","comoBancaPensa":"Conta direta."}},"ES-301":{"cognitivo":{"motivo":"Reconhecer o ponto: tabela assimétrica.","palavraCritica":"assimétrica"},"comentario":{"resolucao":"CERTO. Frequências 10, 15, 40, 35, 28, 10, 4 para 2 a 8 disciplinas: não há espelhamento (pico em 4, cauda mais longa à direita).","fundamento":"Simetria.","macete":"Compare as pontas.","erroComum":"Achar que pico central basta.","comoBancaPensa":"Leitura de tabela."}},"ES-302":{"cognitivo":{"motivo":"Reconhecer o ponto: coeficiente de Bowley.","palavraCritica":"igual a 0,5"},"comentario":{"resolucao":"CERTO. (Q3 + Q1 − 2Q2)/(Q3 − Q1) = (5 + 1 − 4)/(5 − 1) = 2/4 = 0,5.","fundamento":"Coeficiente de Bowley.","macete":"Use só os quartis.","erroComum":"Usar mínimo e máximo.","comoBancaPensa":"Fórmula."}},"ES-303":{"cognitivo":{"motivo":"Reconhecer o ponto: distribuição de dois valores.","palavraCritica":"simétrica"},"comentario":{"resolucao":"ERRADO. Com valores −1 e 4 e média 3: 4p − (1 − p) = 3 ⇒ p = 0,8. São 80% de valores 4 e 20% de −1: a massa fica à direita da média e a cauda à esquerda — assimétrica.","fundamento":"Simetria.","macete":"Ache as proporções pela média.","erroComum":"Achar que dois valores são simétricos.","comoBancaPensa":"Exige cálculo."}},"ES-304":{"cognitivo":{"motivo":"Reconhecer o ponto: assimetria pelos quartis.","palavraCritica":"assimetria positiva"},"comentario":{"resolucao":"CERTO. Q3 − Q2 = 4 > Q2 − Q1 = 2 e a média (6) supera a mediana (4): cauda à direita, assimetria positiva.","fundamento":"Assimetria.","macete":"Quartil superior mais afastado ⇒ positiva.","erroComum":"Inverter.","comoBancaPensa":"Leitura de tabela."}},"ES-305":{"cognitivo":{"motivo":"Reconhecer o ponto: simetria de frequências.","palavraCritica":"simétrica em torno da média"},"comentario":{"resolucao":"CERTO. Frequências 0,3; 0,1; 0,2; 0,1; 0,3 para X = 0 a 4: espelhadas em torno de 2, que é a média.","fundamento":"Simetria.","macete":"Compare as pontas.","erroComum":"Ver forma em U como assimétrica.","comoBancaPensa":"Distribuição em U."}},"ES-306":{"cognitivo":{"motivo":"Reconhecer o ponto: boxplot com cauda à direita.","palavraCritica":"assimetria positiva"},"comentario":{"resolucao":"CERTO. Média 0,80 > mediana 0,70; Q3 − Q2 = 0,50 > Q2 − Q1 = 0,45; máximo 3,10, muito acima do Q3. Cauda à direita: assimetria positiva.","fundamento":"Assimetria.","macete":"Compare distâncias aos quartis.","erroComum":"Olhar só a caixa.","comoBancaPensa":"Leitura de quadro."}},"ES-307":{"cognitivo":{"motivo":"Reconhecer o ponto: leptocúrtica.","palavraCritica":"leptocúrticas"},"comentario":{"resolucao":"CERTO. Na leptocúrtica, há mais massa no centro (pico mais agudo) e caudas mais pesadas que na normal; os valores se concentram próximos à média.","fundamento":"Curtose.","macete":"Lepto = pico alto.","erroComum":"Confundir com platicúrtica.","comoBancaPensa":"Conceito."}},"ES-308":{"cognitivo":{"motivo":"Reconhecer o ponto: curtose e caudas.","palavraCritica":"não estando relacionada às caudas"},"comentario":{"resolucao":"ERRADO. A curtose mede sobretudo o peso das caudas (valores extremos), e não apenas a altura do pico.","fundamento":"Curtose.","macete":"Curtose alta = caudas pesadas.","erroComum":"Ver só o pico.","comoBancaPensa":"Conceito."}},"ES-309":{"cognitivo":{"motivo":"Reconhecer o ponto: curtose e normalidade.","palavraCritica":"hipótese de normalidade"},"comentario":{"resolucao":"CERTO. Comparar a curtose (e a assimetria) com as da normal é um modo de avaliar o afastamento da normalidade.","fundamento":"Curtose.","macete":"Normal: curtose 3 (excesso 0).","erroComum":"Achar irrelevante.","comoBancaPensa":"Conceito."}},"ES-310":{"cognitivo":{"motivo":"Reconhecer o ponto: curtose negativa.","palavraCritica":"menos achatada"},"comentario":{"resolucao":"ERRADO. Curtose (excesso) negativa indica distribuição platicúrtica: MAIS achatada que a normal, com menos concentração no centro.","fundamento":"Curtose.","macete":"Negativa = platicúrtica.","erroComum":"Inverter.","comoBancaPensa":"Inverte o sentido."}},"ES-311":{"cognitivo":{"motivo":"Reconhecer o ponto: platicúrtica.","palavraCritica":"platicúrtica"},"comentario":{"resolucao":"ERRADO. Concentração maior junto à média e caudas mais pesadas descrevem a leptocúrtica. A platicúrtica é mais achatada, com caudas mais leves.","fundamento":"Curtose.","macete":"Plati = plana.","erroComum":"Trocar os nomes.","comoBancaPensa":"Troca de conceito."}},"ES-312":{"cognitivo":{"motivo":"Reconhecer o ponto: excesso de curtose zero.","palavraCritica":"platicúrtica"},"comentario":{"resolucao":"ERRADO. Média 1; m2 = (1 + 1 + 0 + 0 + 0 + 4)/6 = 1; m4 = (1 + 1 + 0 + 0 + 0 + 16)/6 = 3. K = 3/1² − 3 = 0: mesocúrtica, não platicúrtica.","fundamento":"Curtose por momentos.","macete":"K = m4/m2² − 3.","erroComum":"Errar m4.","comoBancaPensa":"Cálculo."}},"ES-313":{"cognitivo":{"motivo":"Reconhecer o ponto: classes de medidas descritivas.","palavraCritica":"medidas descritivas"},"comentario":{"resolucao":"CERTO. Medidas descritivas incluem posição (tendência central e separatrizes), dispersão, assimetria e curtose.","fundamento":"Estatística descritiva.","macete":"Posição, dispersão e forma.","erroComum":"Esquecer as de forma.","comoBancaPensa":"Conceito."}},"ES-314":{"cognitivo":{"motivo":"Reconhecer o ponto: coeficiente percentílico de curtose.","palavraCritica":"superior a 0,4"},"comentario":{"resolucao":"ERRADO. k = (Q3 − Q1)/[2(P90 − P10)] = (8 − 2)/[2(10 − 1)] = 6/18 ≈ 0,333, não superior a 0,4. Como 0,333 > 0,263 (referência da normal), a distribuição seria platicúrtica, não leptocúrtica.","fundamento":"Coeficiente percentílico de curtose.","macete":"Referência: 0,263.","erroComum":"Inverter a leitura da referência.","comoBancaPensa":"Dois erros."}},"ES-315":{"cognitivo":{"motivo":"Reconhecer o ponto: curtose não é semiamplitude.","palavraCritica":"semiamplitude"},"comentario":{"resolucao":"ERRADO. Curtose é medida de forma (achatamento e caudas), não de variação; não se confunde com semiamplitude, nem se expressa em anos.","fundamento":"Curtose.","macete":"Curtose é adimensional.","erroComum":"Confundir com dispersão.","comoBancaPensa":"Troca de conceito."}},"ES-316":{"cognitivo":{"motivo":"Reconhecer o ponto: comparação de coeficientes percentílicos.","palavraCritica":"inferior"},"comentario":{"resolucao":"ERRADO. Privadas: (2,9 − 2,3)/[2(3,1 − 2,2)] = 0,6/1,8 ≈ 0,333. Públicas: (3,1 − 2,5)/[2(3,4 − 2,3)] = 0,6/2,2 ≈ 0,273. O das privadas é maior, não inferior.","fundamento":"Coeficiente percentílico de curtose.","macete":"Calcule os dois.","erroComum":"Inverter decis.","comoBancaPensa":"Duas contas."}},"ES-317":{"cognitivo":{"motivo":"Reconhecer o ponto: frequências decrescentes não definem curtose.","palavraCritica":"curtose negativa"},"comentario":{"resolucao":"ERRADO. Percentuais decrescentes (50, 20, 15, 10, 5) indicam assimetria à direita; isso não determina o sinal da curtose, que depende do 4.º momento.","fundamento":"Curtose x assimetria.","macete":"Forma decrescente = assimetria.","erroComum":"Confundir as medidas.","comoBancaPensa":"Troca de conceito."}},"ES-318":{"cognitivo":{"motivo":"Reconhecer o ponto: quarto momento e referência 3.","palavraCritica":"todas as distribuições simétricas"},"comentario":{"resolucao":"ERRADO. O valor 3 é a curtose (m4/m2²) da distribuição NORMAL. Distribuições simétricas podem ter curtose diferente (a uniforme tem 1,8, por exemplo). Além disso, compara-se o momento padronizado, não o 4.º momento bruto.","fundamento":"Curtose.","macete":"3 = normal, não toda simétrica.","erroComum":"Generalizar.","comoBancaPensa":"Generalização."}},"ES-319":{"cognitivo":{"motivo":"Reconhecer o ponto: fórmula do excesso de curtose.","palavraCritica":"curtose é zero"},"comentario":{"resolucao":"CERTO. K = [(1/n)Σ(x − x̄)⁴] / [(1/n)Σ(x − x̄)²]² − 3 é o excesso de curtose; para a normal vale 0.","fundamento":"Curtose por momentos.","macete":"Menos 3: normal vira zero.","erroComum":"Esquecer o −3.","comoBancaPensa":"Fórmula."}},"ES-320":{"cognitivo":{"motivo":"Reconhecer o ponto: não normal não implica curtose negativa.","palavraCritica":"curtose é negativa"},"comentario":{"resolucao":"ERRADO. Ser diferente da normal não fixa o sinal da curtose: B pode ser lepto ou platicúrtica. O item tira uma conclusão sem base.","fundamento":"Curtose.","macete":"Não normal ≠ platicúrtica.","erroComum":"Generalizar.","comoBancaPensa":"Conclusão sem base."}},"ES-321":{"cognitivo":{"motivo":"Reconhecer o ponto: pico mais alto.","palavraCritica":"curtose da distribuição A"},"comentario":{"resolucao":"CERTO. Na figura, A tem o pico mais alto e estreito em torno do centro, em comparação com a normal e com B: maior curtose.","fundamento":"Curtose.","macete":"Pico alto e estreito = leptocúrtica.","erroComum":"Confundir com dispersão.","comoBancaPensa":"Leitura de figura."}},"ES-322":{"cognitivo":{"motivo":"Reconhecer o ponto: coeficiente angular x correlação.","palavraCritica":"igual a 1,1"},"comentario":{"resolucao":"ERRADO. 1,1 é a inclinação da reta de regressão. O coeficiente de Pearson está sempre entre −1 e 1; nunca vale 1,1.","fundamento":"Correlação e regressão.","macete":"|r| ≤ 1.","erroComum":"Confundir b com r.","comoBancaPensa":"Troca de conceito."}},"ES-323":{"cognitivo":{"motivo":"Reconhecer o ponto: cálculo de Pearson.","palavraCritica":"8/13"},"comentario":{"resolucao":"CERTO. Precipitação (média 54): desvios −4, 6, −14, 16, −4. Volume (média 154): −14, −4, −4, 16, 6. Σdxdy = 56 − 24 + 56 + 256 − 24 = 320; Σdx² = Σdy² = 520. r = 320/520 = 8/13.","fundamento":"Coeficiente de Pearson.","macete":"r = Σdxdy/√(Σdx²Σdy²).","erroComum":"Errar um produto.","comoBancaPensa":"Cálculo."}},"ES-324":{"cognitivo":{"motivo":"Reconhecer o ponto: correlação não é causalidade.","palavraCritica":"medida estatística de causalidade"},"comentario":{"resolucao":"ERRADO. Pearson mede associação LINEAR, não causalidade. Correlação não implica causa.","fundamento":"Correlação.","macete":"Correlação ≠ causalidade.","erroComum":"Inferir causa.","comoBancaPensa":"Conceito."}},"ES-325":{"cognitivo":{"motivo":"Reconhecer o ponto: pearson com quatro pares.","palavraCritica":"7/9"},"comentario":{"resolucao":"CERTO. X: 25, 20, 20, 20 (média 21,25); Y: 13, 10, 12, 10 (média 11,25). Σdxdy = 3,75×1,75 + (−1,25)(−1,25) + (−1,25)(0,75) + (−1,25)(−1,25) = 8,75. Σdx² = 18,75; Σdy² = 6,75. r = 8,75/√(126,56) ≈ 0,778 = 7/9.","fundamento":"Coeficiente de Pearson.","macete":"Use desvios em relação à média.","erroComum":"Errar os desvios.","comoBancaPensa":"Cálculo."}},"ES-326":{"cognitivo":{"motivo":"Reconhecer o ponto: pearson pela covariância.","palavraCritica":"superior a 0,6"},"comentario":{"resolucao":"CERTO. r = Cov/(sX·sY) = 15/(4 × 5) = 0,75, superior a 0,6.","fundamento":"Coeficiente de Pearson.","macete":"r = cov/(sx·sy).","erroComum":"Usar variâncias.","comoBancaPensa":"Fórmula."}},"ES-327":{"cognitivo":{"motivo":"Reconhecer o ponto: correlação forte pelas somas.","palavraCritica":"correlação forte"},"comentario":{"resolucao":"CERTO. Sxy = 181 − 24×49/8 = 34; Sxx = 100 − 24²/8 = 28; Syy = 343 − 49²/8 = 42,875. r = 34/√(28 × 42,875) ≈ 0,98: correlação forte.","fundamento":"Pearson por somatórios.","macete":"S = Σ − (soma)²/n.","erroComum":"Esquecer de centralizar.","comoBancaPensa":"Cálculo."}},"ES-328":{"cognitivo":{"motivo":"Reconhecer o ponto: sinal da correlação.","palavraCritica":"negativo"},"comentario":{"resolucao":"ERRADO. Sxy = 34 > 0: a correlação é positiva (≈ 0,98) e a reta de regressão é crescente.","fundamento":"Sinal da correlação.","macete":"Sinal de Sxy = sinal de r e de b.","erroComum":"Errar o sinal.","comoBancaPensa":"Inverte o sinal."}},"ES-329":{"cognitivo":{"motivo":"Reconhecer o ponto: adequação do Pearson.","palavraCritica":"adequada"},"comentario":{"resolucao":"CERTO. X (tempo de chuva) e Y (livros destruídos) são quantitativas; o coeficiente de Pearson é adequado para medir a associação linear entre elas.","fundamento":"Coeficiente de Pearson.","macete":"Duas quantitativas → Pearson.","erroComum":"Achar que precisa de normalidade.","comoBancaPensa":"Conceito."}},"ES-330":{"cognitivo":{"motivo":"Reconhecer o ponto: pearson com 5 pares.","palavraCritica":"inferior a 0,8"},"comentario":{"resolucao":"CERTO. X: 1 a 5 (média 3); Y: 2, 3, 2, 3, 4 (média 2,8). Σdxdy = 4; Σdx² = 10; Σdy² = 2,8. r = 4/√28 ≈ 0,756, inferior a 0,8.","fundamento":"Pearson.","macete":"Desvios e produtos.","erroComum":"Erro de conta.","comoBancaPensa":"Cálculo."}},"ES-331":{"cognitivo":{"motivo":"Reconhecer o ponto: correlação zero ≠ independência.","palavraCritica":"nenhuma relação"},"comentario":{"resolucao":"ERRADO. Correlação zero indica ausência de relação LINEAR; pode haver relação não linear forte (ex.: Y = X² com X simétrico).","fundamento":"Correlação.","macete":"r = 0 não descarta relação curva.","erroComum":"Achar que zero = nenhuma relação.","comoBancaPensa":"Termo absoluto."}},"ES-332":{"cognitivo":{"motivo":"Reconhecer o ponto: r a partir de R² com sinal.","palavraCritica":"superior a 0,5"},"comentario":{"resolucao":"ERRADO. Na regressão simples, R² = r² ⇒ |r| = 0,8. Como o coeficiente de x é negativo (−11), r = −0,8, que não é superior a 0,5.","fundamento":"R² e correlação.","macete":"O sinal de r segue o da inclinação.","erroComum":"Esquecer o sinal.","comoBancaPensa":"Sinal escondido."}},"ES-333":{"cognitivo":{"motivo":"Reconhecer o ponto: regressão linear.","palavraCritica":"relação linear"},"comentario":{"resolucao":"CERTO. A regressão linear modela a resposta como função linear (nos parâmetros) das preditoras, mais um erro.","fundamento":"Regressão.","macete":"Linear nos coeficientes.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-334":{"cognitivo":{"motivo":"Reconhecer o ponto: previsão não é exata.","palavraCritica":"necessariamente"},"comentario":{"resolucao":"ERRADO. A reta dá o valor ESPERADO (médio) do preço para aquela quilometragem; cada carro tem erro aleatório em torno dela.","fundamento":"Regressão.","macete":"Previsão = média condicional.","erroComum":"Achar que é exata.","comoBancaPensa":"Termo absoluto."}},"ES-335":{"cognitivo":{"motivo":"Reconhecer o ponto: estimativa dos coeficientes.","palavraCritica":"38,56x"},"comentario":{"resolucao":"ERRADO. b = (640.000 − 505 × 21.600/14)/(21.825 − 505²/14) ≈ −38,56 e a = ȳ − b·x̄ ≈ 1.542,9 + 38,56 × 36,07 ≈ 2.934. A reta é ŷ = 2.934 − 38,56x: o sinal da inclinação no item está trocado.","fundamento":"Mínimos quadrados.","macete":"Confira o sinal de Sxy.","erroComum":"Errar o sinal.","comoBancaPensa":"Sinal trocado."}},"ES-336":{"cognitivo":{"motivo":"Reconhecer o ponto: inclinação pela covariância.","palavraCritica":"igual a 2,4"},"comentario":{"resolucao":"CERTO. b = Cov(Y, W)/Var(W) = 60/25 = 2,4.","fundamento":"Mínimos quadrados.","macete":"b = cov/var do regressor.","erroComum":"Dividir pelo DP (12).","comoBancaPensa":"Fórmula."}},"ES-337":{"cognitivo":{"motivo":"Reconhecer o ponto: inclinação pela correlação.","palavraCritica":"igual ou superior a 0,6"},"comentario":{"resolucao":"CERTO. b = r·sy/sx = 0,5 × 5/4 = 0,625 ≥ 0,6.","fundamento":"Mínimos quadrados.","macete":"b = r·sy/sx.","erroComum":"Inverter sy/sx (0,4).","comoBancaPensa":"Fórmula."}},"ES-338":{"cognitivo":{"motivo":"Reconhecer o ponto: ajuste perfeito.","palavraCritica":"perfeitas"},"comentario":{"resolucao":"CERTO. Com todos os pontos sobre uma reta, |r| = 1 e a regressão tem resíduos nulos (R² = 1).","fundamento":"Correlação.","macete":"Pontos alinhados ⇒ |r| = 1.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-339":{"cognitivo":{"motivo":"Reconhecer o ponto: regressão de y sobre x não inverte.","palavraCritica":"estimar x"},"comentario":{"resolucao":"ERRADO. A reta de y sobre x minimiza erros em y; para estimar x a partir de y, ajusta-se a regressão de x sobre y, que é outra reta (salvo correlação perfeita).","fundamento":"Regressão.","macete":"Cada direção tem sua reta.","erroComum":"Inverter a equação.","comoBancaPensa":"Conceito."}},"ES-340":{"cognitivo":{"motivo":"Reconhecer o ponto: desvios padrão iguais.","palavraCritica":"mesmo desvio padrão"},"comentario":{"resolucao":"CERTO. R² = 0,81 ⇒ r = 0,9 (positivo, pois a = 0,9 > 0). Como a = r·sy/sx, 0,9 = 0,9·sy/sx ⇒ sy = sx.","fundamento":"Regressão e correlação.","macete":"a = r·sy/sx.","erroComum":"Esquecer o sinal de r.","comoBancaPensa":"Dedução."}},"ES-341":{"cognitivo":{"motivo":"Reconhecer o ponto: reta de X sobre Y.","palavraCritica":"2X − 10"},"comentario":{"resolucao":"ERRADO. A regressão de X sobre Y tem inclinação Cov/Var(Y) = 15/25 = 0,6 e passa pelas médias: X̂ = 3,2 + 0,6Y. O modelo Ŷ = 2X − 10 nem é a reta de X sobre Y, nem a de Y sobre X (inclinação 15/16).","fundamento":"Mínimos quadrados.","macete":"Inclinação = cov/var do regressor.","erroComum":"Usar razão de DPs.","comoBancaPensa":"Modelo inventado."}},"ES-342":{"cognitivo":{"motivo":"Reconhecer o ponto: duas placas, sem reposição.","palavraCritica":"superior a 0,3"},"comentario":{"resolucao":"CERTO. P = 2 × (200/1.000) × (800/999) ≈ 0,320: uma irregular e outra regular, em qualquer ordem.","fundamento":"Probabilidade sem reposição.","macete":"Multiplique por 2 pelas duas ordens.","erroComum":"Esquecer a ordem (0,16).","comoBancaPensa":"Ordem."}},"ES-343":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidades iguais.","palavraCritica":"inferior"},"comentario":{"resolucao":"ERRADO. O número dos que acham bom, bonito e barato é IGUAL ao dos que não acham nenhum dos três. As probabilidades são iguais.","fundamento":"Probabilidade.","macete":"Mesmo número, mesma probabilidade.","erroComum":"Inventar diferença.","comoBancaPensa":"Dado direto."}},"ES-344":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade a partir de igualdades.","palavraCritica":"50%"},"comentario":{"resolucao":"CERTO. Seja x os que estudam e trabalham (= os que não fazem nenhum) e E = T. Total: E + T − x + x = 2E = 300 ⇒ E = 150. P(estudar) = 50%.","fundamento":"Inclusão-exclusão.","macete":"Monte a equação do total.","erroComum":"Faltar um dado.","comoBancaPensa":"Exige álgebra."}},"ES-345":{"cognitivo":{"motivo":"Reconhecer o ponto: evento impossível.","palavraCritica":"igual a zero"},"comentario":{"resolucao":"CERTO. Se dois auditores não recebessem processos de tomada de contas especial, receberiam 40 de prestação de contas anuais — mas só existem 20. Evento impossível: probabilidade zero.","fundamento":"Probabilidade.","macete":"Teste se o evento é possível.","erroComum":"Calcular sem checar.","comoBancaPensa":"Raciocínio lógico."}},"ES-346":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade simples.","palavraCritica":"superior a 10%"},"comentario":{"resolucao":"CERTO. 20 dos 180 gostam das três áreas: 20/180 ≈ 11,1%.","fundamento":"Probabilidade clássica.","macete":"Favoráveis ÷ total.","erroComum":"Usar 165.","comoBancaPensa":"Conta direta."}},"ES-347":{"cognitivo":{"motivo":"Reconhecer o ponto: pelo menos um.","palavraCritica":"inferior a 0,50"},"comentario":{"resolucao":"ERRADO. P(nenhum de prestação de contas) = C(80, 20)/C(100, 20) ≈ 0,0066. Logo P(pelo menos um) ≈ 0,993, muito acima de 0,5.","fundamento":"Complementar.","macete":"Pelo menos um = 1 − nenhum.","erroComum":"Achar que é pequeno.","comoBancaPensa":"Intuição enganosa."}},"ES-348":{"cognitivo":{"motivo":"Reconhecer o ponto: complementar.","palavraCritica":"inferior a 70%"},"comentario":{"resolucao":"CERTO. Fora de Redenção: 320 − 110 = 210. 210/320 ≈ 65,6%, inferior a 70%.","fundamento":"Probabilidade.","macete":"Complementar.","erroComum":"Erro de conta.","comoBancaPensa":"Conta direta."}},"ES-349":{"cognitivo":{"motivo":"Reconhecer o ponto: razão entre probabilidades.","palavraCritica":"mais de 83%"},"comentario":{"resolucao":"CERTO. P(Parauapebas)/P(Belém) = 82/94 ≈ 87,2%, mais de 83%.","fundamento":"Probabilidade.","macete":"Razão dos casos favoráveis.","erroComum":"Dividir pelo total.","comoBancaPensa":"Razão."}},"ES-350":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade simples.","palavraCritica":"inferior a 0,09"},"comentario":{"resolucao":"ERRADO. 34/320 ≈ 0,106, não inferior a 0,09.","fundamento":"Probabilidade.","macete":"Favoráveis ÷ total.","erroComum":"Erro de divisão.","comoBancaPensa":"Limite próximo."}},"ES-351":{"cognitivo":{"motivo":"Reconhecer o ponto: pelo menos um antigo.","palavraCritica":"3/8"},"comentario":{"resolucao":"ERRADO. São 16 servidores (10 antigos, 6 novos). P(nenhum antigo) = C(6, 2)/C(16, 2) = 15/120 = 1/8. P(pelo menos um antigo) = 7/8, não 3/8.","fundamento":"Complementar.","macete":"1 − nenhum.","erroComum":"Calcular só um caso.","comoBancaPensa":"Valor errado."}},"ES-352":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade simples.","palavraCritica":"inferior a 50%"},"comentario":{"resolucao":"ERRADO. 480/900 ≈ 53,3%, não inferior a 50%.","fundamento":"Probabilidade.","macete":"Favoráveis ÷ total.","erroComum":"Erro de divisão.","comoBancaPensa":"Limite próximo."}},"ES-353":{"cognitivo":{"motivo":"Reconhecer o ponto: aluno sozinho.","palavraCritica":"1/7"},"comentario":{"resolucao":"CERTO. Só um dos 7 alunos fica sozinho, escolhido ao acaso: 1/7.","fundamento":"Probabilidade.","macete":"Um em sete.","erroComum":"Complicar.","comoBancaPensa":"Conta direta."}},"ES-354":{"cognitivo":{"motivo":"Reconhecer o ponto: mesmo grupo (leitura da banca).","palavraCritica":"superior a 29%"},"comentario":{"resolucao":"CERTO, segundo o gabarito. Considerando A já dentro de um dos grupos de três, restam 6 colegas para as 2 vagas do grupo dele: P(B junto) = 2/6 ≈ 33%, acima de 29%. Observação: sem condicionar (A pode ficar sozinho, com probabilidade 1/7), o valor seria 6/7 × 1/3 = 2/7 ≈ 28,6%, abaixo de 29%; o gabarito do material segue a primeira leitura.","fundamento":"Probabilidade condicional.","macete":"Fixe A e conte as vagas restantes.","erroComum":"Ignorar o caso de A sozinho.","comoBancaPensa":"Limite muito próximo."}},"ES-355":{"cognitivo":{"motivo":"Reconhecer o ponto: dados diferentes.","palavraCritica":"5/12"},"comentario":{"resolucao":"ERRADO. Um dado mostra número maior que o outro sempre que não há empate: 1 − 6/36 = 30/36 = 5/6. 5/12 seria a probabilidade de um dado ESPECÍFICO ser maior.","fundamento":"Probabilidade.","macete":"'Um maior que o outro' = não empatar.","erroComum":"Fixar qual dado.","comoBancaPensa":"Ambiguidade explorada."}},"ES-356":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade como proporção.","palavraCritica":"inferior a 3%"},"comentario":{"resolucao":"CERTO. 4.200/149.000 ≈ 2,8%, inferior a 3%.","fundamento":"Probabilidade.","macete":"Restantes ÷ total.","erroComum":"Erro de divisão.","comoBancaPensa":"Limite próximo."}},"ES-357":{"cognitivo":{"motivo":"Reconhecer o ponto: duas crianças de 8 anos.","palavraCritica":"igual a 1/2"},"comentario":{"resolucao":"ERRADO. C(10, 2)/C(40, 2) = 45/780 ≈ 0,058, muito longe de 1/2.","fundamento":"Probabilidade com combinações.","macete":"Favoráveis e possíveis.","erroComum":"Usar 10/40 + ...","comoBancaPensa":"Valor absurdo."}},"ES-358":{"cognitivo":{"motivo":"Reconhecer o ponto: pelo menos uma de 8 anos.","palavraCritica":"maior que 1/3"},"comentario":{"resolucao":"CERTO. P(nenhuma de 8) = C(30, 2)/C(40, 2) = 435/780 ≈ 0,558. P(pelo menos uma) ≈ 0,442 > 1/3.","fundamento":"Complementar.","macete":"1 − nenhum.","erroComum":"Somar probabilidades.","comoBancaPensa":"Complementar."}},"ES-359":{"cognitivo":{"motivo":"Reconhecer o ponto: duas turmas.","palavraCritica":"10%"},"comentario":{"resolucao":"ERRADO. Há duas turmas, e Luzia está em uma delas: P = 1/2 = 50%.","fundamento":"Probabilidade.","macete":"Uma em duas.","erroComum":"Usar 1/10 (membros).","comoBancaPensa":"Base errada."}},"ES-360":{"cognitivo":{"motivo":"Reconhecer o ponto: interseção de eventos.","palavraCritica":"superior a 10%"},"comentario":{"resolucao":"ERRADO. Supondo independência entre as escolhas: 0,2 × (49/50) × 0,4 ≈ 0,078, ou seja, cerca de 7,8%, não superior a 10%.","fundamento":"Probabilidade da interseção.","macete":"Multiplique os eventos independentes.","erroComum":"Somar.","comoBancaPensa":"Três fatores."}},"ES-361":{"cognitivo":{"motivo":"Reconhecer o ponto: dados insuficientes.","palavraCritica":"inferior a 20%"},"comentario":{"resolucao":"ERRADO. Sabe-se só que P(guaraná) = 60%. Os 40% restantes incluem não tomar refrigerante; não se infere quanto é 'outro sabor' — pode ir de 0 a 40%.","fundamento":"Probabilidade.","macete":"Complementar de guaraná não é 'outro sabor'.","erroComum":"Tomar 40% como outro sabor ou inventar limite.","comoBancaPensa":"Dado ausente."}},"ES-362":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade de conhecer.","palavraCritica":"80%"},"comentario":{"resolucao":"CERTO. Conhecem: 300 + 400 + 100 = 800 de 1.000 = 80%.","fundamento":"Probabilidade.","macete":"Some os grupos que conhecem.","erroComum":"Esquecer os indiferentes.","comoBancaPensa":"Conta direta."}},"ES-363":{"cognitivo":{"motivo":"Reconhecer o ponto: jogo não equilibrado.","palavraCritica":"mesma probabilidade"},"comentario":{"resolucao":"ERRADO. Com 0 a 10 dedos cada (11 × 11 = 121 pares), a soma é inferior a 10 em 1 + 2 + ... + 10 = 55 pares: A vence com 55/121 ≈ 45%, B com 66/121 ≈ 55%.","fundamento":"Probabilidade.","macete":"Conte os pares com soma < 10.","erroComum":"Supor simetria.","comoBancaPensa":"Exige contagem."}},"ES-364":{"cognitivo":{"motivo":"Reconhecer o ponto: espaço amostral.","palavraCritica":"20 elementos"},"comentario":{"resolucao":"ERRADO. Cada jogador tem 11 possibilidades (0 a 10): o espaço amostral tem 11 × 11 = 121 pares, não 20.","fundamento":"Espaço amostral.","macete":"Produto das possibilidades.","erroComum":"Somar 10 + 10.","comoBancaPensa":"Soma no lugar de produto."}},"ES-365":{"cognitivo":{"motivo":"Reconhecer o ponto: estratégia dominante.","palavraCritica":"100% de probabilidade"},"comentario":{"resolucao":"CERTO. Se B mostrar os 10 dedos, o total é sempre ≥ 10, qualquer que seja a jogada de A: B vence com certeza.","fundamento":"Probabilidade.","macete":"Procure jogada que garante o resultado.","erroComum":"Pensar só em aleatório.","comoBancaPensa":"Raciocínio."}},"ES-366":{"cognitivo":{"motivo":"Reconhecer o ponto: condicional invertida.","palavraCritica":"P(C|M) = 0,5"},"comentario":{"resolucao":"CERTO. P(M ∩ C) = P(M|C)·P(C) = 0,25 × 0,6 = 0,15. P(C|M) = 0,15/0,30 = 0,5.","fundamento":"Probabilidade condicional.","macete":"P(A|B) = P(A ∩ B)/P(B).","erroComum":"Inverter a condicional.","comoBancaPensa":"Bayes simples."}},"ES-367":{"cognitivo":{"motivo":"Reconhecer o ponto: excludentes não são independentes.","palavraCritica":"independentes"},"comentario":{"resolucao":"ERRADO. K e C são mutuamente exclusivos (P(K ∩ C) = 0) com probabilidades positivas; então P(K ∩ C) ≠ P(K)·P(C) = 0,24. Não são independentes.","fundamento":"Independência.","macete":"Excludentes com P > 0 nunca são independentes.","erroComum":"Confundir exclusão com independência.","comoBancaPensa":"Conceito."}},"ES-368":{"cognitivo":{"motivo":"Reconhecer o ponto: complementar.","palavraCritica":"igual a 0,7"},"comentario":{"resolucao":"CERTO. P(6 meses ou mais) = 1 − P(M) = 1 − 0,3 = 0,7.","fundamento":"Complementar.","macete":"1 − P(M).","erroComum":"Confundir.","comoBancaPensa":"Conta direta."}},"ES-369":{"cognitivo":{"motivo":"Reconhecer o ponto: interseção sem independência.","palavraCritica":"0,6 x 0,3"},"comentario":{"resolucao":"ERRADO. P(M ∩ C) = P(M|C)·P(C) = 0,25 × 0,6 = 0,15. O produto 0,6 × 0,3 = 0,18 só valeria se M e C fossem independentes, e não são (P(M|C) = 0,25 ≠ 0,3).","fundamento":"Interseção.","macete":"Só multiplique direto se forem independentes.","erroComum":"Supor independência.","comoBancaPensa":"Falsa independência."}},"ES-370":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade total.","palavraCritica":"15%"},"comentario":{"resolucao":"CERTO. P(D) = 0,2 × 0,3 + 0,1 × 0,2 + 0,7 × 0,1 = 0,06 + 0,02 + 0,07 = 0,15.","fundamento":"Teorema da probabilidade total.","macete":"Some P(D|cada)·P(cada).","erroComum":"Somar as condicionais.","comoBancaPensa":"Cálculo."}},"ES-371":{"cognitivo":{"motivo":"Reconhecer o ponto: interseção pela condicional.","palavraCritica":"0,2 x P(D)"},"comentario":{"resolucao":"ERRADO. P(A ∩ D) = P(A|D)·P(D) = 0,4·P(D). Usar 0,2 = P(A) suporia independência, contrariada por P(A|D) = 0,4.","fundamento":"Regra do produto.","macete":"Use a condicional dada.","erroComum":"Usar P(A).","comoBancaPensa":"Falsa independência."}},"ES-372":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade total.","palavraCritica":"P(A) = 0,23"},"comentario":{"resolucao":"CERTO. P(A) = 0,3 × 0,3 + 0,7 × 0,2 = 0,09 + 0,14 = 0,23.","fundamento":"Probabilidade total.","macete":"Pondere pelas proporções.","erroComum":"Média simples (0,25).","comoBancaPensa":"Cálculo."}},"ES-373":{"cognitivo":{"motivo":"Reconhecer o ponto: bayes.","palavraCritica":"P (B|A) = 0,3"},"comentario":{"resolucao":"ERRADO. P(B|A) = P(A|B)·P(B)/P(A) = 0,09/0,23 ≈ 0,39. 0,3 é P(A|B) ou P(B).","fundamento":"Teorema de Bayes.","macete":"Inverter exige dividir por P(A).","erroComum":"Confundir as condicionais.","comoBancaPensa":"Troca de condicional."}},"ES-374":{"cognitivo":{"motivo":"Reconhecer o ponto: condicional simples.","palavraCritica":"25%"},"comentario":{"resolucao":"CERTO. P(F|A) = P(A ∩ F)/P(A) = 0,05/0,2 = 0,25.","fundamento":"Probabilidade condicional.","macete":"Interseção ÷ condição.","erroComum":"Dividir por P(F).","comoBancaPensa":"Conta direta."}},"ES-375":{"cognitivo":{"motivo":"Reconhecer o ponto: união.","palavraCritica":"35%"},"comentario":{"resolucao":"ERRADO. P(A ∪ F) = 0,2 + 0,15 − 0,05 = 0,30, não 0,35.","fundamento":"Probabilidade da união.","macete":"Desconte a interseção.","erroComum":"Somar direto.","comoBancaPensa":"Erro clássico."}},"ES-376":{"cognitivo":{"motivo":"Reconhecer o ponto: independência ≠ exclusão.","palavraCritica":"igual a zero"},"comentario":{"resolucao":"ERRADO. Se A e F fossem independentes, P(A ∩ F) = 0,2 × 0,15 = 0,03. Zero seria o caso de eventos mutuamente exclusivos.","fundamento":"Independência.","macete":"Independentes: multiplica.","erroComum":"Confundir com exclusão.","comoBancaPensa":"Troca de conceito."}},"ES-377":{"cognitivo":{"motivo":"Reconhecer o ponto: condicional em tabela.","palavraCritica":"50%"},"comentario":{"resolucao":"CERTO. Entre as 10 mulheres, 5 têm filhos: P = 5/10 = 50%.","fundamento":"Probabilidade condicional.","macete":"Restrinja à linha da condição.","erroComum":"Dividir por 25.","comoBancaPensa":"Leitura de tabela."}},"ES-378":{"cognitivo":{"motivo":"Reconhecer o ponto: complementar em tabela.","palavraCritica":"36%"},"comentario":{"resolucao":"CERTO. Casados: 16 de 25. Não casados: 9/25 = 36%.","fundamento":"Complementar.","macete":"Total − casados.","erroComum":"Usar 16/25.","comoBancaPensa":"Conta direta."}},"ES-379":{"cognitivo":{"motivo":"Reconhecer o ponto: união de eventos disjuntos.","palavraCritica":"60%"},"comentario":{"resolucao":"ERRADO. Homens com ensino superior (12) e mulheres com filhos (5) são grupos disjuntos: (12 + 5)/25 = 68%, não 60%.","fundamento":"Probabilidade da união.","macete":"Disjuntos: some.","erroComum":"Errar a soma.","comoBancaPensa":"Valor próximo."}},"ES-380":{"cognitivo":{"motivo":"Reconhecer o ponto: conjunta x condicional.","palavraCritica":"53,33%"},"comentario":{"resolucao":"ERRADO. P(masculino e com filhos) = 8/25 = 32%. 53,33% = 8/15 é a condicional P(filhos | masculino).","fundamento":"Probabilidade conjunta.","macete":"Conjunta divide pelo total geral.","erroComum":"Dividir por 15.","comoBancaPensa":"Troca conjunta por condicional."}},"ES-381":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade conjunta.","palavraCritica":"48%"},"comentario":{"resolucao":"CERTO. Homens com ensino superior: 12 de 25 = 48%.","fundamento":"Probabilidade conjunta.","macete":"Célula ÷ total.","erroComum":"Dividir por 15.","comoBancaPensa":"Conta direta."}},"ES-382":{"cognitivo":{"motivo":"Reconhecer o ponto: bernoulli a partir de X².","palavraCritica":"probabilidade de sucesso é igual a 2a"},"comentario":{"resolucao":"ERRADO. 2a + a + 2a = 1 ⇒ a = 0,2. X² vale 1 quando X = ±1 (probabilidade 2a + 2a = 4a = 0,8) e 0 quando X = 0. X² é Bernoulli com p = 4a = 0,8, não 2a.","fundamento":"Distribuição de Bernoulli.","macete":"Some as probabilidades que levam X² a 1.","erroComum":"Contar só X = 1.","comoBancaPensa":"Esquece o −1."}},"ES-383":{"cognitivo":{"motivo":"Reconhecer o ponto: x² de Bernoulli.","palavraCritica":"média igual a 0,81"},"comentario":{"resolucao":"ERRADO. Se X só vale 0 ou 1, então X² = X: é Bernoulli com a mesma média 0,9, não 0,81.","fundamento":"Bernoulli.","macete":"0² = 0 e 1² = 1.","erroComum":"Elevar a média ao quadrado.","comoBancaPensa":"Erro clássico."}},"ES-384":{"cognitivo":{"motivo":"Reconhecer o ponto: variância simétrica em p.","palavraCritica":"variâncias de X e Y são iguais"},"comentario":{"resolucao":"CERTO. Var = p(1 − p). X: 0,9 × 0,1 = 0,09; Y (p = 0,1): 0,1 × 0,9 = 0,09. Iguais.","fundamento":"Bernoulli.","macete":"p(1 − p) é simétrico.","erroComum":"Achar que muda.","comoBancaPensa":"Propriedade."}},"ES-385":{"cognitivo":{"motivo":"Reconhecer o ponto: média de Bernoulli.","palavraCritica":"superior a 0,5"},"comentario":{"resolucao":"ERRADO. P(Y = 0) = 0,9 ⇒ P(Y = 1) = 0,1 = E[Y], inferior a 0,5.","fundamento":"Bernoulli.","macete":"Média = P(sucesso).","erroComum":"Usar P(Y = 0).","comoBancaPensa":"Troca o evento."}},"ES-386":{"cognitivo":{"motivo":"Reconhecer o ponto: média e variância.","palavraCritica":"0,7 e 0,21"},"comentario":{"resolucao":"CERTO. X é Bernoulli com p = 0,7: média 0,7 e variância 0,7 × 0,3 = 0,21.","fundamento":"Bernoulli.","macete":"E = p; Var = p(1 − p).","erroComum":"Usar p² na variância.","comoBancaPensa":"Fórmula."}},"ES-387":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão da geométrica.","palavraCritica":"superior a 50"},"comentario":{"resolucao":"ERRADO. DP = √(1 − p)/p = √0,98/0,02 ≈ 49,5, não superior a 50.","fundamento":"Distribuição geométrica.","macete":"Var = (1 − p)/p².","erroComum":"Usar 1/p.","comoBancaPensa":"Limite muito próximo."}},"ES-388":{"cognitivo":{"motivo":"Reconhecer o ponto: identificar a distribuição.","palavraCritica":"hipergeométrica"},"comentario":{"resolucao":"ERRADO. Ensaios independentes com mesma probabilidade até o primeiro sucesso: distribuição geométrica. A hipergeométrica é para amostragem sem reposição de população finita.","fundamento":"Modelos discretos.","macete":"Até o 1.º sucesso = geométrica.","erroComum":"Confundir modelos.","comoBancaPensa":"Troca de modelo."}},"ES-389":{"cognitivo":{"motivo":"Reconhecer o ponto: média da geométrica.","palavraCritica":"igual a 50"},"comentario":{"resolucao":"CERTO. E[X] = 1/p = 1/0,02 = 50.","fundamento":"Distribuição geométrica.","macete":"E = 1/p.","erroComum":"Usar (1 − p)/p.","comoBancaPensa":"Fórmula."}},"ES-390":{"cognitivo":{"motivo":"Reconhecer o ponto: p(X = 3).","palavraCritica":"inferior a 0,05"},"comentario":{"resolucao":"CERTO. P(X = 3) = 0,98² × 0,02 ≈ 0,0192, inferior a 0,05.","fundamento":"Distribuição geométrica.","macete":"(1 − p)^(k−1)·p.","erroComum":"Esquecer as falhas.","comoBancaPensa":"Conta direta."}},"ES-391":{"cognitivo":{"motivo":"Reconhecer o ponto: primeira cara no 15.º lançamento (gabarito do material).","palavraCritica":"(1 − p)14"},"comentario":{"resolucao":"CERTO, segundo o gabarito. Observação: pelo modelo geométrico, a probabilidade de a primeira cara ocorrer exatamente no 15.º lançamento é (1 − p)¹⁴·p (14 coroas e depois uma cara). A expressão (1 − p)¹⁴ corresponde a 14 coroas seguidas, sem o fator p; o gabarito do QAP foi mantido.","fundamento":"Distribuição geométrica.","macete":"Falhas antes × sucesso final.","erroComum":"Esquecer o fator p.","comoBancaPensa":"Fórmula incompleta."}},"ES-392":{"cognitivo":{"motivo":"Reconhecer o ponto: média.","palavraCritica":"E(X) = 1/p"},"comentario":{"resolucao":"CERTO. Contando o número de ensaios até o primeiro sucesso, E(X) = 1/p.","fundamento":"Geométrica.","macete":"E = 1/p.","erroComum":"Usar a versão das falhas.","comoBancaPensa":"Fórmula."}},"ES-393":{"cognitivo":{"motivo":"Reconhecer o ponto: variância.","palavraCritica":"Var(X) = 1/p2"},"comentario":{"resolucao":"ERRADO. Var(X) = (1 − p)/p², não 1/p².","fundamento":"Geométrica.","macete":"Var = q/p².","erroComum":"Esquecer q.","comoBancaPensa":"Fórmula incompleta."}},"ES-394":{"cognitivo":{"motivo":"Reconhecer o ponto: p(X = 3).","palavraCritica":"p . (1 − p)2"},"comentario":{"resolucao":"CERTO. Duas falhas e depois o sucesso: (1 − p)²·p.","fundamento":"Geométrica.","macete":"q^(k−1)·p.","erroComum":"Trocar expoentes.","comoBancaPensa":"Fórmula."}},"ES-395":{"cognitivo":{"motivo":"Reconhecer o ponto: p(X > 5).","palavraCritica":"p (1 − p)4"},"comentario":{"resolucao":"ERRADO. X > 5 significa 5 falhas seguidas: P(X > 5) = (1 − p)⁵. p(1 − p)⁴ é P(X = 5).","fundamento":"Geométrica.","macete":"P(X > k) = q^k.","erroComum":"Confundir com P(X = k).","comoBancaPensa":"Troca de evento."}},"ES-396":{"cognitivo":{"motivo":"Reconhecer o ponto: cauda da geométrica.","palavraCritica":"inferior a 50%"},"comentario":{"resolucao":"CERTO. 'Sucesso' aqui é a decisão desfavorável (p = 1/4). P(X > 3) = (3/4)³ ≈ 0,42, inferior a 50%.","fundamento":"Geométrica.","macete":"P(X > k) = q^k.","erroComum":"Trocar p e q.","comoBancaPensa":"Inversão do sucesso."}},"ES-397":{"cognitivo":{"motivo":"Reconhecer o ponto: média da geométrica.","palavraCritica":"pelo menos, quatro decisões favoráveis"},"comentario":{"resolucao":"ERRADO. E[X] = 1/(1/4) = 4: espera-se a primeira desfavorável na 4.ª decisão, isto é, depois de 3 favoráveis, e não de pelo menos quatro.","fundamento":"Geométrica.","macete":"E = 1/p conta o próprio sucesso.","erroComum":"Esquecer de descontar o ensaio final.","comoBancaPensa":"Erro de contagem."}},"ES-398":{"cognitivo":{"motivo":"Reconhecer o ponto: sem reposição não é geométrica.","palavraCritica":"geométrica com parâmetro p = 0,5"},"comentario":{"resolucao":"ERRADO. As pessoas são chamadas sem reposição; a probabilidade de a próxima testemunhar muda a cada chamada. Os ensaios não são independentes com p constante: X não é geométrica.","fundamento":"Modelos discretos.","macete":"Geométrica exige p constante e independência.","erroComum":"Ver só 2 de 4 = 0,5.","comoBancaPensa":"Sem reposição."}},"ES-399":{"cognitivo":{"motivo":"Reconhecer o ponto: variância binomial.","palavraCritica":"igual ou inferior a 10"},"comentario":{"resolucao":"CERTO. Var = np(1 − p) = 1.000 × 0,01 × 0,99 = 9,9.","fundamento":"Binomial.","macete":"npq.","erroComum":"Usar np.","comoBancaPensa":"Limite próximo."}},"ES-400":{"cognitivo":{"motivo":"Reconhecer o ponto: moda binomial.","palavraCritica":"moda de X é igual a zero"},"comentario":{"resolucao":"ERRADO. A moda da binomial fica perto de np = 10 (mais precisamente, ⌊(n + 1)p⌋ = 10). P baixo não leva a moda para zero quando n é grande.","fundamento":"Binomial.","macete":"Moda ≈ np.","erroComum":"Achar que p pequeno ⇒ zero.","comoBancaPensa":"Intuição falsa."}},"ES-401":{"cognitivo":{"motivo":"Reconhecer o ponto: independência dos ensaios.","palavraCritica":"independentes"},"comentario":{"resolucao":"CERTO. A binomial conta sucessos em n ensaios de Bernoulli independentes com mesma probabilidade.","fundamento":"Binomial.","macete":"Independência e p constante.","erroComum":"Confundir com hipergeométrica.","comoBancaPensa":"Conceito."}},"ES-402":{"cognitivo":{"motivo":"Reconhecer o ponto: sem reposição.","palavraCritica":"Binomial"},"comentario":{"resolucao":"ERRADO. Sem reposição, cada unidade aparece no máximo uma vez: fi vale 0 ou 1 (Bernoulli com p = n/N). Binomial(n, 1/N) descreve a amostragem COM reposição.","fundamento":"Amostragem.","macete":"Com reposição → binomial.","erroComum":"Trocar os esquemas.","comoBancaPensa":"Troca de esquema."}},"ES-403":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade binomial.","palavraCritica":"é 0,6"},"comentario":{"resolucao":"ERRADO. P = C(10, 6) × 0,6⁶ × 0,4⁴ ≈ 0,251, não 0,6.","fundamento":"Binomial.","macete":"C(n, k)p^k q^(n−k).","erroComum":"Usar a proporção como probabilidade.","comoBancaPensa":"Confunde p com probabilidade do evento."}},"ES-404":{"cognitivo":{"motivo":"Reconhecer o ponto: uma de aço comum em 3.","palavraCritica":"0,144"},"comentario":{"resolucao":"ERRADO. Com reposição, p = 0,4: P = C(3, 1) × 0,4 × 0,6² = 0,432. 0,144 é a probabilidade de uma ordem específica, sem o fator 3.","fundamento":"Binomial.","macete":"Não esqueça C(n, k).","erroComum":"Esquecer as ordens.","comoBancaPensa":"Erro clássico."}},"ES-405":{"cognitivo":{"motivo":"Reconhecer o ponto: suporte da binomial.","palavraCritica":"P(X ≥ 115) = 0"},"comentario":{"resolucao":"CERTO. np = 80 e np(1 − p) = 16 ⇒ 1 − p = 0,2, p = 0,8 e n = 100. X não passa de 100; P(X ≥ 115) = 0.","fundamento":"Binomial.","macete":"Ache n e p a partir da média e variância.","erroComum":"Usar normal.","comoBancaPensa":"Suporte."}},"ES-406":{"cognitivo":{"motivo":"Reconhecer o ponto: p(X = 0).","palavraCritica":"0,20"},"comentario":{"resolucao":"ERRADO. P(X = 0) = 0,2¹⁰⁰, praticamente zero. 0,2 é a probabilidade de fracasso em um ensaio.","fundamento":"Binomial.","macete":"q^n.","erroComum":"Usar q.","comoBancaPensa":"Confusão."}},"ES-407":{"cognitivo":{"motivo":"Reconhecer o ponto: cauda superior.","palavraCritica":"superior a 6%"},"comentario":{"resolucao":"ERRADO. Com p = 0,35 e n = 15: P(X ≥ 14) = 15 × 0,35¹⁴ × 0,65 + 0,35¹⁵ ≈ 0,000004, muito abaixo de 6%.","fundamento":"Binomial.","macete":"Some só os termos pedidos.","erroComum":"Achar que é grande.","comoBancaPensa":"Valor absurdo."}},"ES-408":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão.","palavraCritica":"igual ou superior a 0,9"},"comentario":{"resolucao":"CERTO. DP = √(10 × 0,1 × 0,9) = √0,9 ≈ 0,949 ≥ 0,9.","fundamento":"Binomial.","macete":"√npq.","erroComum":"Usar npq.","comoBancaPensa":"Limite próximo."}},"ES-409":{"cognitivo":{"motivo":"Reconhecer o ponto: p(X > 0).","palavraCritica":"P(X > 0) = 0,9"},"comentario":{"resolucao":"ERRADO. P(X > 0) = 1 − 0,9¹⁰ ≈ 0,651, não 0,9.","fundamento":"Binomial.","macete":"1 − P(X = 0).","erroComum":"Usar q.","comoBancaPensa":"Confusão."}},"ES-410":{"cognitivo":{"motivo":"Reconhecer o ponto: média.","palavraCritica":"igual a 1"},"comentario":{"resolucao":"CERTO. E[X] = np = 10 × 0,1 = 1.","fundamento":"Binomial.","macete":"np.","erroComum":"Erro de conta.","comoBancaPensa":"Conta direta."}},"ES-411":{"cognitivo":{"motivo":"Reconhecer o ponto: média da diferença.","palavraCritica":"é 3"},"comentario":{"resolucao":"ERRADO. E[Z] = E[Y] − E[X] = 10 × 0,2 − 10 × 0,5 = 2 − 5 = −3, não 3.","fundamento":"Esperança de combinação linear.","macete":"Atenção à ordem Y − X.","erroComum":"Inverter a ordem.","comoBancaPensa":"Sinal."}},"ES-412":{"cognitivo":{"motivo":"Reconhecer o ponto: variância.","palavraCritica":"0,24×n"},"comentario":{"resolucao":"CERTO. Var(Y) = n × 0,4 × 0,6 = 0,24n.","fundamento":"Binomial.","macete":"npq.","erroComum":"Usar p².","comoBancaPensa":"Fórmula."}},"ES-413":{"cognitivo":{"motivo":"Reconhecer o ponto: valor máximo.","palavraCritica":"impossível"},"comentario":{"resolucao":"CERTO. np = 4 e npq = 3 ⇒ q = 0,75, p = 0,25, n = 16. X ≤ 16: 18 erros são impossíveis.","fundamento":"Binomial.","macete":"Ache n.","erroComum":"Usar normal.","comoBancaPensa":"Suporte."}},"ES-414":{"cognitivo":{"motivo":"Reconhecer o ponto: p(X = 0).","palavraCritica":"3/4"},"comentario":{"resolucao":"ERRADO. P(X = 0) = 0,75¹⁶ ≈ 0,01. 3/4 é a probabilidade de fracasso em um ensaio.","fundamento":"Binomial.","macete":"q^n.","erroComum":"Usar q.","comoBancaPensa":"Confusão."}},"ES-415":{"cognitivo":{"motivo":"Reconhecer o ponto: exatamente um em quatro.","palavraCritica":"superior a 0,4"},"comentario":{"resolucao":"CERTO. P = 4 × 0,25 × 0,75³ ≈ 0,422, superior a 0,4.","fundamento":"Binomial.","macete":"C(4, 1)pq³.","erroComum":"Esquecer o 4.","comoBancaPensa":"Limite próximo."}},"ES-416":{"cognitivo":{"motivo":"Reconhecer o ponto: média estimada.","palavraCritica":"superior a 300"},"comentario":{"resolucao":"ERRADO. A estimativa de máxima verossimilhança da média é n·p̂ = 1.000 × 0,25 = 250, não superior a 300.","fundamento":"Binomial e MV.","macete":"Invariância: média = n·p̂.","erroComum":"Erro de conta.","comoBancaPensa":"Conta direta."}},"ES-417":{"cognitivo":{"motivo":"Reconhecer o ponto: soma de geométricas.","palavraCritica":"binomial negativa"},"comentario":{"resolucao":"CERTO. Y é geométrica (número de falhas antes do 1.º sucesso, p = 0,1). A soma de geométricas independentes de mesmo p é binomial negativa.","fundamento":"Binomial negativa.","macete":"Soma de geométricas = binomial negativa.","erroComum":"Achar que é binomial.","comoBancaPensa":"Propriedade."}},"ES-418":{"cognitivo":{"motivo":"Reconhecer o ponto: terceiro sucesso na décima retirada.","palavraCritica":"terceira peça defeituosa ocorrer na décima retirada"},"comentario":{"resolucao":"CERTO. Número de ensaios até o r-ésimo sucesso (r = 3) é o caso clássico da binomial negativa.","fundamento":"Binomial negativa.","macete":"Até o r-ésimo sucesso.","erroComum":"Usar binomial.","comoBancaPensa":"Conceito."}},"ES-419":{"cognitivo":{"motivo":"Reconhecer o ponto: número fixo de ensaios é binomial.","palavraCritica":"exatamente 3 peças defeituosas"},"comentario":{"resolucao":"ERRADO. Contar sucessos em um número fixo de ensaios (10) é binomial, não binomial negativa.","fundamento":"Binomial x binomial negativa.","macete":"n fixo → binomial; r fixo → negativa.","erroComum":"Trocar os modelos.","comoBancaPensa":"Troca de modelo."}},"ES-420":{"cognitivo":{"motivo":"Reconhecer o ponto: geométrica como caso particular.","palavraCritica":"primeira peça defeituosa"},"comentario":{"resolucao":"CERTO. A geométrica (primeiro sucesso) é a binomial negativa com r = 1.","fundamento":"Binomial negativa.","macete":"r = 1 → geométrica.","erroComum":"Achar que não serve.","comoBancaPensa":"Caso particular."}},"ES-421":{"cognitivo":{"motivo":"Reconhecer o ponto: contagem em folha fixa.","palavraCritica":"binomial negativa"},"comentario":{"resolucao":"ERRADO. Conta-se o número de reclamações numa folha de até 20 chamadas (número fixo de ensaios): modelo binomial (ou Poisson, como aproximação). Binomial negativa contaria ensaios até um número fixo de sucessos.","fundamento":"Escolha do modelo.","macete":"Número de sucessos em n fixo.","erroComum":"Confundir.","comoBancaPensa":"Troca de modelo."}},"ES-422":{"cognitivo":{"motivo":"Reconhecer o ponto: parâmetros da multinomial.","palavraCritica":"0,5, 0,1 e 0,4"},"comentario":{"resolucao":"CERTO. P(T1) = 0,5; P(T2.1) = 0,5 × 0,2 = 0,1; P(T2.2) = 0,5 × 0,8 = 0,4. As contagens das três classes seguem multinomial com esses parâmetros.","fundamento":"Multinomial.","macete":"Multiplique as proporções encadeadas.","erroComum":"Usar 0,2 e 0,8 diretamente.","comoBancaPensa":"Proporções condicionais."}},"ES-423":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade multinomial.","palavraCritica":"0,0003"},"comentario":{"resolucao":"CERTO. Cada elemento tem probabilidade 1/10 por sorteio. P = 5!/(1!2!2!) × 0,1⁵ = 30 × 0,00001 = 0,0003.","fundamento":"Multinomial.","macete":"n!/(n1!n2!…) × produtos.","erroComum":"Esquecer o coeficiente.","comoBancaPensa":"Fórmula."}},"ES-424":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade multinomial.","palavraCritica":"0,23%"},"comentario":{"resolucao":"CERTO. 5 em A, 3 em C e 2 em B: P = 10!/(5!3!2!) × 0,2⁵ × 0,2³ × 0,6² = 2.520 × 0,00032 × 0,008 × 0,36 ≈ 0,0023 = 0,23%.","fundamento":"Multinomial.","macete":"Coeficiente multinomial × potências.","erroComum":"Esquecer o coeficiente.","comoBancaPensa":"Cálculo."}},"ES-425":{"cognitivo":{"motivo":"Reconhecer o ponto: pelo menos duas zonas de risco.","palavraCritica":"menor que 75%"},"comentario":{"resolucao":"CERTO. P(X = 0) = C(6, 5)/C(10, 5) = 6/252; P(X = 1) = 4 × C(6, 4)/252 = 60/252. P(X ≥ 2) = 1 − 66/252 ≈ 0,738, menor que 75%.","fundamento":"Hipergeométrica.","macete":"Use o complementar.","erroComum":"Usar binomial.","comoBancaPensa":"Limite próximo."}},"ES-426":{"cognitivo":{"motivo":"Reconhecer o ponto: identificar a hipergeométrica.","palavraCritica":"hipergeométrica"},"comentario":{"resolucao":"CERTO. Sorteio sem reposição de população finita com duas categorias: hipergeométrica.","fundamento":"Modelos discretos.","macete":"Sem reposição → hipergeométrica.","erroComum":"Usar binomial.","comoBancaPensa":"Conceito."}},"ES-427":{"cognitivo":{"motivo":"Reconhecer o ponto: exatamente 2 defeituosos.","palavraCritica":"superior a 0,05"},"comentario":{"resolucao":"CERTO. C(5, 2) × C(25, 1)/C(30, 3) = 10 × 25/4.060 ≈ 0,062, superior a 0,05.","fundamento":"Hipergeométrica.","macete":"Favoráveis ÷ C(30, 3).","erroComum":"Usar binomial.","comoBancaPensa":"Conta."}},"ES-428":{"cognitivo":{"motivo":"Reconhecer o ponto: exatamente 2 bons.","palavraCritica":"inferior a 0,4"},"comentario":{"resolucao":"CERTO. Dois bons e um defeituoso: C(25, 2) × C(5, 1)/4.060 = 300 × 5/4.060 ≈ 0,369, inferior a 0,4.","fundamento":"Hipergeométrica.","macete":"Monte os dois grupos.","erroComum":"Errar o evento.","comoBancaPensa":"Inversão de evento."}},"ES-429":{"cognitivo":{"motivo":"Reconhecer o ponto: todos bons.","palavraCritica":"superior a 0,5"},"comentario":{"resolucao":"CERTO. C(25, 3)/C(30, 3) = 2.300/4.060 ≈ 0,567, superior a 0,5.","fundamento":"Hipergeométrica.","macete":"Todos do grupo bom.","erroComum":"Usar (5/6)³.","comoBancaPensa":"Conta."}},"ES-430":{"cognitivo":{"motivo":"Reconhecer o ponto: hipergeométrica com lotes grandes.","palavraCritica":"igual a 0,25"},"comentario":{"resolucao":"ERRADO. P = C(20, 5) × C(80, 15)/C(100, 20) ≈ 0,19, não 0,25. A média esperada (4) não se confunde com a probabilidade de um valor.","fundamento":"Hipergeométrica.","macete":"Favoráveis ÷ total.","erroComum":"Usar 5/20.","comoBancaPensa":"Valor intuitivo."}},"ES-431":{"cognitivo":{"motivo":"Reconhecer o ponto: loteria.","palavraCritica":"superior a 30%"},"comentario":{"resolucao":"CERTO. C(5, 1) × C(10, 4)/C(15, 5) = 5 × 210/3.003 ≈ 0,35, superior a 30%.","fundamento":"Hipergeométrica.","macete":"Acertos e erros como grupos.","erroComum":"Errar C(15, 5).","comoBancaPensa":"Conta."}},"ES-432":{"cognitivo":{"motivo":"Reconhecer o ponto: com x sem reposição.","palavraCritica":"r/4!"},"comentario":{"resolucao":"ERRADO. Sem reposição: r = C(6, 2) × C(9, 2)/C(15, 4) = 540/1.365 ≈ 0,396. Com reposição: C(4, 2) × 0,4² × 0,6² ≈ 0,346. Não há relação 'r/4!' (que daria ≈ 0,016).","fundamento":"Hipergeométrica x binomial.","macete":"Calcule os dois.","erroComum":"Inventar relação.","comoBancaPensa":"Fórmula inventada."}},"ES-433":{"cognitivo":{"motivo":"Reconhecer o ponto: média.","palavraCritica":"igual a 80"},"comentario":{"resolucao":"CERTO. A média é n·p = 100 × 0,8 = 80 (vale tanto para a binomial quanto para a hipergeométrica).","fundamento":"Esperança.","macete":"n·p.","erroComum":"Achar que a falta de reposição muda a média.","comoBancaPensa":"Conta direta."}},"ES-434":{"cognitivo":{"motivo":"Reconhecer o ponto: sem reposição não é multinomial.","palavraCritica":"multinomial"},"comentario":{"resolucao":"ERRADO. A seleção é sem reposição em população pequena: o vetor segue a hipergeométrica multivariada. A multinomial pressupõe ensaios independentes (com reposição).","fundamento":"Modelos discretos.","macete":"Sem reposição → hipergeométrica.","erroComum":"Usar multinomial.","comoBancaPensa":"Troca de modelo."}},"ES-435":{"cognitivo":{"motivo":"Reconhecer o ponto: hipergeométrica multivariada.","palavraCritica":"superior a 0,03"},"comentario":{"resolucao":"ERRADO. P = C(4, 3) × C(6, 2)/C(15, 5) = 4 × 15/3.003 ≈ 0,020, inferior a 0,03.","fundamento":"Hipergeométrica.","macete":"Produto das combinações ÷ total.","erroComum":"Erro de C(15, 5).","comoBancaPensa":"Conta."}},"ES-436":{"cognitivo":{"motivo":"Reconhecer o ponto: soma de Poisson independentes.","palavraCritica":"S - X"},"comentario":{"resolucao":"CERTO. S − X = Y + Z, soma de Poisson independentes, é Poisson com média 2 + 3 = 5.","fundamento":"Propriedade reprodutiva da Poisson.","macete":"Soma de Poisson independentes é Poisson.","erroComum":"Achar que a diferença complica.","comoBancaPensa":"Propriedade."}},"ES-437":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão da soma.","palavraCritica":"desvio padrão de S é igual a 6"},"comentario":{"resolucao":"ERRADO. S é Poisson com média 6, logo variância 6 e desvio padrão √6 ≈ 2,45, não 6.","fundamento":"Poisson.","macete":"Na Poisson, variância = média.","erroComum":"Confundir DP com variância.","comoBancaPensa":"Troca de medida."}},"ES-438":{"cognitivo":{"motivo":"Reconhecer o ponto: soma nula.","palavraCritica":"P(S = 0)"},"comentario":{"resolucao":"CERTO. Como os valores não são negativos, S = 0 só ocorre se X = Y = Z = 0; pela independência, P(S = 0) = P(X = 0)·P(Y = 0)·P(Z = 0) = e^(−6).","fundamento":"Independência.","macete":"Soma zero ⇒ todas zero.","erroComum":"Somar as probabilidades.","comoBancaPensa":"Propriedade."}},"ES-439":{"cognitivo":{"motivo":"Reconhecer o ponto: condicional com independência.","palavraCritica":"15 . e−8"},"comentario":{"resolucao":"CERTO. Pela independência, condicionar em Z não altera X e Y: P(X = 1)·P(Y = 1) = 5e^(−5) × 3e^(−3) = 15e^(−8).","fundamento":"Poisson e independência.","macete":"Condição em variável independente some.","erroComum":"Incluir P(Z = 1).","comoBancaPensa":"Condicional."}},"ES-440":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade da soma.","palavraCritica":"243 . e−9"},"comentario":{"resolucao":"ERRADO. T é Poisson(9): P(T = 3) = e^(−9)·9³/3! = 729e^(−9)/6 = 121,5e^(−9), não 243e^(−9).","fundamento":"Poisson.","macete":"λ^k/k!.","erroComum":"Esquecer o fatorial ou errar.","comoBancaPensa":"Valor dobrado."}},"ES-441":{"cognitivo":{"motivo":"Reconhecer o ponto: variância da soma.","palavraCritica":"variância de T é igual a 35"},"comentario":{"resolucao":"ERRADO. Var(T) = 5 + 3 + 1 = 9 (independentes, variância = média). 35 seria a soma dos quadrados das médias.","fundamento":"Poisson.","macete":"Some as variâncias.","erroComum":"Elevar as médias ao quadrado.","comoBancaPensa":"Erro de soma."}},"ES-442":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão da diferença.","palavraCritica":"igual a 2"},"comentario":{"resolucao":"CERTO. T − X = Y + Z ~ Poisson(4): desvio padrão √4 = 2.","fundamento":"Poisson.","macete":"Reescreva a diferença como soma.","erroComum":"Somar Var(T) + Var(X).","comoBancaPensa":"Diferença disfarçada."}},"ES-443":{"cognitivo":{"motivo":"Reconhecer o ponto: covariância com uma parcela.","palavraCritica":"covariância entre T e Z é igual a 1"},"comentario":{"resolucao":"CERTO. Cov(T, Z) = Cov(X + Y + Z, Z) = Var(Z) = 1 (as demais covariâncias são nulas pela independência).","fundamento":"Covariância.","macete":"Cov(soma, parcela) = Var(parcela).","erroComum":"Achar que é zero.","comoBancaPensa":"Propriedade."}},"ES-444":{"cognitivo":{"motivo":"Reconhecer o ponto: uso da Poisson.","palavraCritica":"distribuição de Poisson"},"comentario":{"resolucao":"CERTO. Número de ocorrências (ligações) em um intervalo de tempo é a aplicação típica da Poisson.","fundamento":"Poisson.","macete":"Contagens por intervalo.","erroComum":"Usar exponencial.","comoBancaPensa":"Conceito."}},"ES-445":{"cognitivo":{"motivo":"Reconhecer o ponto: total semanal.","palavraCritica":"igual a 5 transações por semana"},"comentario":{"resolucao":"CERTO. Y é Poisson com média 5 × 5 = 25; desvio padrão √25 = 5.","fundamento":"Poisson.","macete":"Some as médias.","erroComum":"Usar a média como DP.","comoBancaPensa":"Conta direta."}},"ES-446":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade de soma nula.","palavraCritica":"P(X1 = 0) + P(X2 = 0)"},"comentario":{"resolucao":"ERRADO. Y = 0 exige todos os Xi = 0: P(Y = 0) = Π P(Xi = 0) = (e^(−5))⁵ = e^(−25), produto e não soma.","fundamento":"Independência.","macete":"'E' entre eventos independentes multiplica.","erroComum":"Somar.","comoBancaPensa":"Soma no lugar de produto."}},"ES-447":{"cognitivo":{"motivo":"Reconhecer o ponto: p(X = 0) estimada.","palavraCritica":"nula"},"comentario":{"resolucao":"ERRADO. A média estimada é (10 + 4 + 2 + 4)/4 = 5; P̂(X = 0) = e^(−5) ≈ 0,0067, positiva. Não ter zeros na amostra não torna a probabilidade nula.","fundamento":"Poisson e estimação.","macete":"e^(−λ) > 0 sempre.","erroComum":"Usar a frequência amostral.","comoBancaPensa":"Confunde amostra com modelo."}},"ES-448":{"cognitivo":{"motivo":"Reconhecer o ponto: valor não observado.","palavraCritica":"P(X = 7) = 0"},"comentario":{"resolucao":"ERRADO. Na Poisson, todo inteiro não negativo tem probabilidade positiva: P(X = 7) = e^(−M)M⁷/7! > 0, mesmo sem aparecer na amostra.","fundamento":"Poisson.","macete":"Amostra não esgota o suporte.","erroComum":"Confundir frequência com probabilidade.","comoBancaPensa":"Conceito."}},"ES-449":{"cognitivo":{"motivo":"Reconhecer o ponto: estimativa do desvio padrão.","palavraCritica":"igual a 2 registros"},"comentario":{"resolucao":"CERTO. A MV de M é a média amostral (6 + 8 + 0 + 4 + 2)/5 = 4. Como Var = M, pela invariância o DP estimado é √4 = 2.","fundamento":"Máxima verossimilhança.","macete":"DP da Poisson = √M.","erroComum":"Calcular o DP amostral.","comoBancaPensa":"Invariância."}},"ES-450":{"cognitivo":{"motivo":"Reconhecer o ponto: mínimos quadrados para a média.","palavraCritica":"igual a 4"},"comentario":{"resolucao":"CERTO. Minimizar Σ(xi − M)² dá M̂ = média amostral = 4.","fundamento":"Mínimos quadrados.","macete":"MQ da média = média amostral.","erroComum":"Usar a mediana.","comoBancaPensa":"Conceito."}},"ES-451":{"cognitivo":{"motivo":"Reconhecer o ponto: soma de n Poisson(1).","palavraCritica":"média igual a n"},"comentario":{"resolucao":"CERTO. Soma de n Poisson(1) independentes é Poisson(n).","fundamento":"Poisson.","macete":"Some as médias.","erroComum":"Achar que vira normal.","comoBancaPensa":"Propriedade."}},"ES-452":{"cognitivo":{"motivo":"Reconhecer o ponto: p(X = 0) com λ = ln 15.","palavraCritica":"inferior a 0,08"},"comentario":{"resolucao":"CERTO. P(X = 0) = e^(−ln 15) = 1/15 ≈ 0,067, inferior a 0,08.","fundamento":"Poisson.","macete":"e^(−ln a) = 1/a.","erroComum":"Errar a propriedade do log.","comoBancaPensa":"Conta."}},"ES-453":{"cognitivo":{"motivo":"Reconhecer o ponto: variância = média.","palavraCritica":"ln(4)"},"comentario":{"resolucao":"CERTO. Na Poisson, a variância é igual à média: ln(4).","fundamento":"Poisson.","macete":"Var = λ.","erroComum":"Elevar ao quadrado.","comoBancaPensa":"Propriedade."}},"ES-454":{"cognitivo":{"motivo":"Reconhecer o ponto: p(S = 0).","palavraCritica":"P(S = 0) > 0,02"},"comentario":{"resolucao":"ERRADO. S é Poisson(ln 15 + ln 4) = Poisson(ln 60): P(S = 0) = 1/60 ≈ 0,0167, inferior a 0,02.","fundamento":"Poisson.","macete":"e^(−ln 60) = 1/60.","erroComum":"Somar as probabilidades.","comoBancaPensa":"Limite próximo."}},"ES-455":{"cognitivo":{"motivo":"Reconhecer o ponto: soma de Poisson.","palavraCritica":"segue uma distribuição de Poisson"},"comentario":{"resolucao":"CERTO. Soma de Poisson independentes é Poisson.","fundamento":"Poisson.","macete":"Propriedade reprodutiva.","erroComum":"Duvidar.","comoBancaPensa":"Propriedade."}},"ES-456":{"cognitivo":{"motivo":"Reconhecer o ponto: média da soma.","palavraCritica":"ln(60)"},"comentario":{"resolucao":"CERTO. E[S] = ln 15 + ln 4 = ln 60.","fundamento":"Poisson; logaritmos.","macete":"ln a + ln b = ln(ab).","erroComum":"Somar 15 + 4.","comoBancaPensa":"Log."}},"ES-457":{"cognitivo":{"motivo":"Reconhecer o ponto: menos de três chamadas.","palavraCritica":"85e–12"},"comentario":{"resolucao":"CERTO. P(X < 3) = e^(−12)(1 + 12 + 12²/2) = e^(−12)(1 + 12 + 72) = 85e^(−12).","fundamento":"Poisson.","macete":"Some k = 0, 1, 2.","erroComum":"Esquecer o termo k = 0.","comoBancaPensa":"Soma de termos."}},"ES-458":{"cognitivo":{"motivo":"Reconhecer o ponto: ajuste de taxa para 20 minutos.","palavraCritica":"duas chamadas em 20 minutos"},"comentario":{"resolucao":"ERRADO. Em 20 minutos, λ = 12/3 = 4: P(X = 2) = e^(−4)·4²/2! = 8e^(−4). A expressão do item não corresponde.","fundamento":"Poisson.","macete":"Ajuste λ ao intervalo.","erroComum":"Usar λ = 12.","comoBancaPensa":"Taxa não ajustada."}},"ES-459":{"cognitivo":{"motivo":"Reconhecer o ponto: normalização.","palavraCritica":"P(X = 1) = 0,2"},"comentario":{"resolucao":"CERTO. 5c + c + 2c + 3c + 4c = 15c = 1 ⇒ c = 1/15. P(X = 1) = 3/15 = 0,2.","fundamento":"Função de probabilidade.","macete":"Some e iguale a 1.","erroComum":"Errar a soma.","comoBancaPensa":"Conta."}},"ES-460":{"cognitivo":{"motivo":"Reconhecer o ponto: moda.","palavraCritica":"moda de X é igual a zero"},"comentario":{"resolucao":"ERRADO. A maior probabilidade é 5c, em X = −2: a moda é −2.","fundamento":"Moda.","macete":"Maior probabilidade.","erroComum":"Achar que o centro é a moda.","comoBancaPensa":"Confusão."}},"ES-461":{"cognitivo":{"motivo":"Reconhecer o ponto: média.","palavraCritica":"média de X é igual a zero"},"comentario":{"resolucao":"CERTO. E[X] = c(−10 − 1 + 0 + 3 + 8) = 0.","fundamento":"Esperança.","macete":"Σx·p(x).","erroComum":"Errar sinais.","comoBancaPensa":"Conta."}},"ES-462":{"cognitivo":{"motivo":"Reconhecer o ponto: discreta x contínua.","palavraCritica":"distribuição contínua"},"comentario":{"resolucao":"ERRADO. X assume um número finito de valores (suporte {−2, ..., 2}): é discreta. O fato de c ser real não muda isso.","fundamento":"Tipos de variáveis aleatórias.","macete":"Suporte enumerável → discreta.","erroComum":"Confundir parâmetro com suporte.","comoBancaPensa":"Troca de conceito."}},"ES-463":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana.","palavraCritica":"igual ou superior a 1"},"comentario":{"resolucao":"ERRADO. Acumuladas: −2 → 1/3; −1 → 6/15 = 0,4; 0 → 8/15 ≈ 0,53. A mediana é 0.","fundamento":"Mediana.","macete":"Primeiro valor com acumulada ≥ 0,5.","erroComum":"Errar a acumulação.","comoBancaPensa":"Conta."}},"ES-464":{"cognitivo":{"motivo":"Reconhecer o ponto: valores fora do suporte.","palavraCritica":"exatamente 31 meses"},"comentario":{"resolucao":"CERTO. Os tempos 13, 14, 16, 19, 21, 23, 27, 29 e 31 não estão na tabela: todos têm probabilidade zero. Soma zero = zero.","fundamento":"Função de probabilidade.","macete":"Fora do suporte: P = 0.","erroComum":"Interpolar.","comoBancaPensa":"Pegadinha de suporte."}},"ES-465":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana.","palavraCritica":"mediana igual a 24"},"comentario":{"resolucao":"CERTO. Acumuladas: 20 → 0,17; 22 → 0,39; 24 → 0,70. A mediana é 24 meses.","fundamento":"Mediana.","macete":"Acumulada cruza 0,5.","erroComum":"Erro de soma.","comoBancaPensa":"Conta."}},"ES-466":{"cognitivo":{"motivo":"Reconhecer o ponto: média.","palavraCritica":"mais de 24 meses"},"comentario":{"resolucao":"ERRADO. E[X] = 12×0,01 + 15×0,02 + 18×0,04 + 20×0,10 + 22×0,22 + 24×0,31 + 25×0,18 + 26×0,04 + 28×0,03 + 30×0,05 = 23,3 meses.","fundamento":"Esperança.","macete":"Σx·p.","erroComum":"Usar a mediana.","comoBancaPensa":"Cálculo."}},"ES-467":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão.","palavraCritica":"superior a 5"},"comentario":{"resolucao":"ERRADO. Var = E(X²) − [E(X)]² = 552 − 23,3² = 552 − 542,89 ≈ 9,11; DP ≈ 3,02, não superior a 5.","fundamento":"Variância.","macete":"Var = E(X²) − μ².","erroComum":"Errar μ.","comoBancaPensa":"Cálculo."}},"ES-468":{"cognitivo":{"motivo":"Reconhecer o ponto: comparação de probabilidades (leitura da banca).","palavraCritica":"até 2 meses antes"},"comentario":{"resolucao":"CERTO, segundo o gabarito. Defender 2 meses antes do prazo (22 meses) tem probabilidade 0,22; defender até 2 meses depois do prazo (25 ou 26 meses) tem 0,18 + 0,04 = 0,22. As duas são iguais. Observação: lidas como probabilidades acumuladas (X ≤ 22 e X ≤ 26), seriam 0,39 e 0,92; o gabarito segue a primeira leitura.","fundamento":"Função de probabilidade.","macete":"Some só as faixas pedidas.","erroComum":"Acumular desde o início.","comoBancaPensa":"Leitura ambígua."}},"ES-469":{"cognitivo":{"motivo":"Reconhecer o ponto: gráfico inadequado.","palavraCritica":"gráfico de setores"},"comentario":{"resolucao":"ERRADO. A variável é quantitativa (tempo em meses), com valores ordenados; o gráfico adequado é de barras/bastões. Setores servem a partes de um todo qualitativo.","fundamento":"Gráficos.","macete":"Quantitativa → barras.","erroComum":"Usar pizza.","comoBancaPensa":"Escolha de gráfico."}},"ES-470":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade acumulada.","palavraCritica":"superior a 70%"},"comentario":{"resolucao":"ERRADO. P(X ≤ 24) = 0,01 + 0,02 + 0,04 + 0,10 + 0,22 + 0,31 = 0,70, igual a 70%, não superior.","fundamento":"Acumulada.","macete":"Some até 24.","erroComum":"Erro de soma.","comoBancaPensa":"Limite exato."}},"ES-471":{"cognitivo":{"motivo":"Reconhecer o ponto: p(|X| > 0).","palavraCritica":"P(|X| > 0) < 0,6"},"comentario":{"resolucao":"ERRADO. 5a = 1 ⇒ a = 0,2. P(|X| > 0) = P(X = −1) + P(X = 1) = 4a = 0,8, não inferior a 0,6.","fundamento":"Função de probabilidade.","macete":"Normalize primeiro.","erroComum":"Usar só 2a.","comoBancaPensa":"Conta."}},"ES-472":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão.","palavraCritica":"2√a"},"comentario":{"resolucao":"CERTO. E[X] = −2a + 2a = 0; E[X²] = 2a + 2a = 4a. Var = 4a; DP = 2√a.","fundamento":"Variância.","macete":"Var = E(X²) − μ².","erroComum":"Esquecer a raiz.","comoBancaPensa":"Fórmula."}},"ES-473":{"cognitivo":{"motivo":"Reconhecer o ponto: média de distribuição simétrica.","palavraCritica":"igual a zero"},"comentario":{"resolucao":"CERTO. E[X] = (−1)(2a) + 0·a + (1)(2a) = 0.","fundamento":"Esperança.","macete":"Simétrica em torno de 0.","erroComum":"Erro de sinal.","comoBancaPensa":"Conta."}},"ES-474":{"cognitivo":{"motivo":"Reconhecer o ponto: média de dados agrupados.","palavraCritica":"9,75 sm"},"comentario":{"resolucao":"CERTO. Pontos médios: 7,5; 12,5; 17,5. Média = 7,5×0,65 + 12,5×0,25 + 17,5×0,10 = 4,875 + 3,125 + 1,75 = 9,75.","fundamento":"Média agrupada.","macete":"Ponto médio × frequência.","erroComum":"Usar limites.","comoBancaPensa":"Cálculo."}},"ES-475":{"cognitivo":{"motivo":"Reconhecer o ponto: renda é quantitativa.","palavraCritica":"qualitativa ordinal"},"comentario":{"resolucao":"ERRADO. Renda em salários mínimos é variável quantitativa (contínua), ainda que agrupada em classes. Agrupar não a torna qualitativa.","fundamento":"Tipos de variáveis.","macete":"Agrupar não muda a natureza.","erroComum":"Ver classes como categorias.","comoBancaPensa":"Troca de conceito."}},"ES-476":{"cognitivo":{"motivo":"Reconhecer o ponto: histograma de densidades.","palavraCritica":"densidades de frequência"},"comentario":{"resolucao":"CERTO, segundo a banca. No histograma, a altura de cada barra representa a densidade de frequência (frequência ÷ amplitude), e a área corresponde à frequência da classe.","fundamento":"Histograma.","macete":"Altura = densidade; área = frequência.","erroComum":"Achar que altura é sempre a frequência.","comoBancaPensa":"Conceito."}},"ES-477":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana agrupada.","palavraCritica":"superior a 8 sm e inferior a 9 sm"},"comentario":{"resolucao":"CERTO. A 1.ª classe tem 65%. Mediana = 5 + 5 × (0,50/0,65) ≈ 8,85 sm, entre 8 e 9.","fundamento":"Mediana agrupada.","macete":"Interpole na classe.","erroComum":"Usar o ponto médio.","comoBancaPensa":"Interpolação."}},"ES-478":{"cognitivo":{"motivo":"Reconhecer o ponto: variância da soma.","palavraCritica":"2n"},"comentario":{"resolucao":"ERRADO. Exponencial de média 2 tem variância 2² = 4. Var(Sn) = 4n, não 2n.","fundamento":"Exponencial.","macete":"Var = média².","erroComum":"Usar a média como variância.","comoBancaPensa":"Troca de fórmula."}},"ES-479":{"cognitivo":{"motivo":"Reconhecer o ponto: sobrevivência em dois anos.","palavraCritica":"84%"},"comentario":{"resolucao":"ERRADO. Sobreviver 1 ano: e^(−λ) = 0,6. Sobreviver 2 anos: 0,6² = 0,36; decaídos em 2 anos: 64%, não 84%.","fundamento":"Exponencial.","macete":"P(T > t) = e^(−λt).","erroComum":"Interpretar 60% como decaídos.","comoBancaPensa":"Leitura do dado."}},"ES-480":{"cognitivo":{"motivo":"Reconhecer o ponto: exponencial x Poisson.","palavraCritica":"distribuição de Poisson"},"comentario":{"resolucao":"ERRADO. O instante de decaimento é contínuo e segue a exponencial (dada pela densidade). A Poisson conta eventos num intervalo.","fundamento":"Exponencial x Poisson.","macete":"Tempo → exponencial; contagem → Poisson.","erroComum":"Confundir.","comoBancaPensa":"Troca de modelo."}},"ES-481":{"cognitivo":{"motivo":"Reconhecer o ponto: média a partir da densidade.","palavraCritica":"igual a 5"},"comentario":{"resolucao":"ERRADO. f(x) = 5e^(−5x) tem λ = 5; a média é 1/λ = 0,2, não 5.","fundamento":"Exponencial.","macete":"Média = 1/λ.","erroComum":"Confundir λ com a média.","comoBancaPensa":"Troca clássica."}},"ES-482":{"cognitivo":{"motivo":"Reconhecer o ponto: soma de exponenciais é gama.","palavraCritica":"exponencial"},"comentario":{"resolucao":"ERRADO. A soma de n exponenciais independentes de mesma taxa segue distribuição gama (Erlang), não exponencial (embora a média seja 2n).","fundamento":"Exponencial.","macete":"Soma → gama.","erroComum":"Generalizar a propriedade da Poisson.","comoBancaPensa":"Distribuição errada."}},"ES-483":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão da soma.","palavraCritica":"igual a 2n"},"comentario":{"resolucao":"ERRADO. Var(Sn) = 4n ⇒ DP = 2√n, não 2n.","fundamento":"Exponencial.","macete":"Variâncias somam; DPs não.","erroComum":"Somar desvios padrão.","comoBancaPensa":"Erro clássico."}},"ES-484":{"cognitivo":{"motivo":"Reconhecer o ponto: exponencial de taxa 1.","palavraCritica":"iguais a 1"},"comentario":{"resolucao":"CERTO. P(V > v) = e^(−v) é a exponencial com λ = 1: média 1 e variância 1.","fundamento":"Exponencial.","macete":"Média 1/λ; variância 1/λ².","erroComum":"Confundir.","comoBancaPensa":"Fórmula."}},"ES-485":{"cognitivo":{"motivo":"Reconhecer o ponto: tempo até a ligação.","palavraCritica":"distribuição exponencial"},"comentario":{"resolucao":"CERTO. Se as ligações chegam segundo um processo de Poisson, o tempo até a próxima ligação é exponencial.","fundamento":"Exponencial.","macete":"Tempo de espera → exponencial.","erroComum":"Usar Poisson.","comoBancaPensa":"Conceito."}},"ES-486":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão da soma.","palavraCritica":"igual a 7 dias"},"comentario":{"resolucao":"ERRADO. Var(T1 + T2) = 4² + 3² = 25 ⇒ DP = 5 dias. 7 é a soma das médias (ou dos DPs).","fundamento":"Exponencial.","macete":"Variâncias somam.","erroComum":"Somar DPs.","comoBancaPensa":"Erro clássico."}},"ES-487":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade conjunta.","palavraCritica":"e-3"},"comentario":{"resolucao":"CERTO. P(T1 > 4) = e^(−4/4) = e^(−1); P(T2 > 6) = e^(−6/3) = e^(−2). Independentes: e^(−3).","fundamento":"Exponencial.","macete":"P(T > t) = e^(−t/μ).","erroComum":"Errar a taxa.","comoBancaPensa":"Conta."}},"ES-488":{"cognitivo":{"motivo":"Reconhecer o ponto: falta de memória.","palavraCritica":"P(T1 > 7 | T1 > 3)"},"comentario":{"resolucao":"CERTO. Pela falta de memória, P(T1 > 7 | T1 > 3) = P(T1 > 4) = e^(−1) e P(T2 > 4 | T2 > 1) = P(T2 > 3) = e^(−1). Iguais.","fundamento":"Falta de memória.","macete":"Condicional = sobra do intervalo.","erroComum":"Calcular sem a propriedade.","comoBancaPensa":"Propriedade."}},"ES-489":{"cognitivo":{"motivo":"Reconhecer o ponto: soma de exponenciais.","palavraCritica":"segue distribuição exponencial"},"comentario":{"resolucao":"ERRADO. A soma de exponenciais independentes não é exponencial (com taxas diferentes, é hipoexponencial).","fundamento":"Exponencial.","macete":"Soma não preserva a exponencial.","erroComum":"Generalizar.","comoBancaPensa":"Distribuição errada."}},"ES-490":{"cognitivo":{"motivo":"Reconhecer o ponto: momentos da exponencial.","palavraCritica":"E[Xr] = (R$ 5.000)r"},"comentario":{"resolucao":"ERRADO. Na exponencial de média μ, E[X^r] = r!·μ^r. Para r = 2, por exemplo, E[X²] = 2μ², não μ².","fundamento":"Momentos.","macete":"E[X^r] = r!μ^r.","erroComum":"Esquecer o fatorial.","comoBancaPensa":"Fórmula incompleta."}},"ES-491":{"cognitivo":{"motivo":"Reconhecer o ponto: cV da exponencial.","palavraCritica":"igual a 1"},"comentario":{"resolucao":"CERTO. Na exponencial, DP = média; CV = 1.","fundamento":"Exponencial.","macete":"DP = média.","erroComum":"Confundir.","comoBancaPensa":"Propriedade."}},"ES-492":{"cognitivo":{"motivo":"Reconhecer o ponto: falta de memória.","palavraCritica":"P(X > 5.000 | X > 1.000) < P(X > 5.000)"},"comentario":{"resolucao":"ERRADO. P(X > 5.000 | X > 1.000) = P(X > 4.000) = e^(−0,8), maior que P(X > 5.000) = e^(−1).","fundamento":"Falta de memória.","macete":"Condicional = sobra.","erroComum":"Inverter a desigualdade.","comoBancaPensa":"Propriedade."}},"ES-493":{"cognitivo":{"motivo":"Reconhecer o ponto: dP da exponencial.","palavraCritica":"superior a 12 kg"},"comentario":{"resolucao":"ERRADO. Na exponencial, DP = média = 10 kg, não superior a 12.","fundamento":"Exponencial.","macete":"DP = média.","erroComum":"Confundir.","comoBancaPensa":"Conta direta."}},"ES-494":{"cognitivo":{"motivo":"Reconhecer o ponto: acima x abaixo da média.","palavraCritica":"P(Y ≥10 kg) > P(Y ≤10 kg)"},"comentario":{"resolucao":"ERRADO. P(Y ≥ 10) = e^(−1) ≈ 0,37 e P(Y ≤ 10) ≈ 0,63. A primeira é menor.","fundamento":"Exponencial.","macete":"Mais massa abaixo da média.","erroComum":"Achar simetria.","comoBancaPensa":"Assimetria."}},"ES-495":{"cognitivo":{"motivo":"Reconhecer o ponto: ponto em variável contínua.","palavraCritica":"P(Y=10kg)"},"comentario":{"resolucao":"ERRADO. Em variável contínua, P(Y = 10) = 0. E a moda da exponencial é 0, não a média.","fundamento":"Variáveis contínuas.","macete":"Ponto tem probabilidade zero.","erroComum":"Tratar como discreta.","comoBancaPensa":"Dois erros."}},"ES-496":{"cognitivo":{"motivo":"Reconhecer o ponto: dP = média.","palavraCritica":"igual a 30 minutos"},"comentario":{"resolucao":"CERTO. Na exponencial, DP = média = 30 minutos.","fundamento":"Exponencial.","macete":"DP = média.","erroComum":"Confundir.","comoBancaPensa":"Propriedade."}},"ES-497":{"cognitivo":{"motivo":"Reconhecer o ponto: ponto em contínua.","palavraCritica":"igual a zero"},"comentario":{"resolucao":"CERTO. T é contínua: P(T = 30) = 0.","fundamento":"Variáveis contínuas.","macete":"Ponto: probabilidade zero.","erroComum":"Tratar como discreta.","comoBancaPensa":"Conceito."}},"ES-498":{"cognitivo":{"motivo":"Reconhecer o ponto: moda da exponencial.","palavraCritica":"moda"},"comentario":{"resolucao":"ERRADO. A densidade da exponencial é máxima em t = 0: a moda é 0, não a média (30).","fundamento":"Exponencial.","macete":"Densidade decrescente: moda no início.","erroComum":"Igualar moda e média.","comoBancaPensa":"Troca de medida."}},"ES-499":{"cognitivo":{"motivo":"Reconhecer o ponto: falta de memória aplicada errado.","palavraCritica":"P(T > 35 | T > 30) = P(T > 35)"},"comentario":{"resolucao":"ERRADO. Pela falta de memória, P(T > 35 | T > 30) = P(T > 5), e não P(T > 35).","fundamento":"Falta de memória.","macete":"Condicional = tempo que sobra.","erroComum":"Esquecer de descontar.","comoBancaPensa":"Aplicação errada."}},"ES-500":{"cognitivo":{"motivo":"Reconhecer o ponto: simetria da normal.","palavraCritica":"0,8544"},"comentario":{"resolucao":"ERRADO. P(Z > −2) = 0,5 + P(−2 < Z < 0) = 0,5 + 0,4772 = 0,9772. 0,8544 seria 2 × 0,4272, sem relação com o dado.","fundamento":"Normal padrão.","macete":"Use a simetria em torno de 0.","erroComum":"Dobrar a área.","comoBancaPensa":"Valor errado."}},"ES-501":{"cognitivo":{"motivo":"Reconhecer o ponto: máximo da densidade.","palavraCritica":"x = m"},"comentario":{"resolucao":"CERTO. A densidade normal é máxima na média (que coincide com a moda e a mediana).","fundamento":"Normal.","macete":"Pico na média.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-502":{"cognitivo":{"motivo":"Reconhecer o ponto: padronização.","palavraCritica":"1,0"},"comentario":{"resolucao":"CERTO. z = (86 − 74)/12 = 1,0.","fundamento":"Normal padronizada.","macete":"z = (x − μ)/σ.","erroComum":"Dividir pela variância.","comoBancaPensa":"Conta direta."}},"ES-503":{"cognitivo":{"motivo":"Reconhecer o ponto: cauda superior (normal).","palavraCritica":"inferior a 15%"},"comentario":{"resolucao":"ERRADO. Com a tabela da normal: P(X > 800) = P(Z > 1) = 0,5 − 0,3413 = 0,1587, superior a 15%.","fundamento":"Normal.","macete":"z = (800 − 600)/200 = 1.","erroComum":"Errar a tabela.","comoBancaPensa":"Limite próximo."}},"ES-504":{"cognitivo":{"motivo":"Reconhecer o ponto: cauda inferior (normal).","palavraCritica":"superior a 10%"},"comentario":{"resolucao":"CERTO. P(X ≤ 400) = P(Z ≤ −1) = 0,1587, superior a 10%.","fundamento":"Normal.","macete":"Simetria.","erroComum":"Errar o sinal.","comoBancaPensa":"Conta."}},"ES-505":{"cognitivo":{"motivo":"Reconhecer o ponto: cauda extrema.","palavraCritica":"menor do que 1%"},"comentario":{"resolucao":"CERTO. P(X < 100) = P(Z < −2,5) = 0,5 − 0,4938 = 0,0062 < 1%.","fundamento":"Normal.","macete":"z = −2,5.","erroComum":"Errar a tabela.","comoBancaPensa":"Conta."}},"ES-506":{"cognitivo":{"motivo":"Reconhecer o ponto: intervalo assimétrico.","palavraCritica":"62,5%"},"comentario":{"resolucao":"CERTO. P(300 < X < 700) = P(−1,5 < Z < 0,5) = 0,4332 + 0,1915 = 0,6247 ≈ 62,5%.","fundamento":"Normal.","macete":"Some as áreas dos dois lados.","erroComum":"Subtrair.","comoBancaPensa":"Cálculo."}},"ES-507":{"cognitivo":{"motivo":"Reconhecer o ponto: intervalo (normal).","palavraCritica":"menor que 80%"},"comentario":{"resolucao":"ERRADO. Com a tabela da normal: P(30 < X < 60) = P(−2 < Z < 1) = 0,4772 + 0,3413 = 0,8185, não menor que 80%.","fundamento":"Normal.","macete":"Padronize os dois limites.","erroComum":"Usar a uniforme.","comoBancaPensa":"Limite próximo."}},"ES-508":{"cognitivo":{"motivo":"Reconhecer o ponto: cauda (normal).","palavraCritica":"maior que 1%"},"comentario":{"resolucao":"ERRADO. P(X > 80) = P(Z > 3) ≈ 0,0013, menor que 1%.","fundamento":"Normal.","macete":"z = 3.","erroComum":"Errar a tabela.","comoBancaPensa":"Conta."}},"ES-509":{"cognitivo":{"motivo":"Reconhecer o ponto: metade acima da média.","palavraCritica":"0,5"},"comentario":{"resolucao":"CERTO. A normal é simétrica em torno da média: P(W > 10) = 0,5.","fundamento":"Normal.","macete":"Simetria.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-510":{"cognitivo":{"motivo":"Reconhecer o ponto: padronização errada.","palavraCritica":"normal padrão"},"comentario":{"resolucao":"ERRADO. Padroniza-se com (W − 10)/4. (W − 20)/√4 = (W − 20)/2 tem média −5 e desvio padrão 2: não é normal padrão.","fundamento":"Padronização.","macete":"Subtraia a média e divida pelo DP.","erroComum":"Usar a variância.","comoBancaPensa":"Fórmula errada."}},"ES-511":{"cognitivo":{"motivo":"Reconhecer o ponto: cauda unilateral.","palavraCritica":"0,05"},"comentario":{"resolucao":"ERRADO. P(X > 70) = P(Z > 2) = 0,025, não 0,05 (0,05 seria a soma das duas caudas).","fundamento":"Normal.","macete":"Uma cauda só.","erroComum":"Somar as duas caudas.","comoBancaPensa":"Unilateral x bilateral."}},"ES-512":{"cognitivo":{"motivo":"Reconhecer o ponto: simetria.","palavraCritica":"P(X < 60 litros) = P(X ≥ 40 litros)"},"comentario":{"resolucao":"CERTO. P(X < 60) = P(Z < 1) e P(X ≥ 40) = P(Z ≥ −1) = P(Z ≤ 1). Iguais por simetria.","fundamento":"Normal.","macete":"Distâncias iguais à média.","erroComum":"Inverter.","comoBancaPensa":"Simetria."}},"ES-513":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade pontual.","palavraCritica":"P(X = 50 litros) > P(X = 30 litros)"},"comentario":{"resolucao":"ERRADO. Em variável contínua, P(X = 50) = P(X = 30) = 0. A densidade é maior em 50, mas probabilidade de ponto é sempre zero.","fundamento":"Variável contínua.","macete":"Densidade ≠ probabilidade.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-514":{"cognitivo":{"motivo":"Reconhecer o ponto: parâmetros pela figura.","palavraCritica":"7 ton e 4 ton"},"comentario":{"resolucao":"ERRADO. A curva é centrada em 7 (média). P(U > 9) = 0,16 = P(Z > 1) ⇒ 9 = 7 + σ ⇒ σ = 2 ton, não 4.","fundamento":"Normal.","macete":"Use o quantil dado.","erroComum":"Usar 9 − 7 como variância.","comoBancaPensa":"Erro de parâmetro."}},"ES-515":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade central.","palavraCritica":"inferior a 0,70"},"comentario":{"resolucao":"CERTO. P(5 < U < 9) = 1 − 2 × 0,16 = 0,68 < 0,70.","fundamento":"Normal.","macete":"1 − duas caudas.","erroComum":"Errar a simetria.","comoBancaPensa":"Conta."}},"ES-516":{"cognitivo":{"motivo":"Reconhecer o ponto: condicional na normal.","palavraCritica":"0,32"},"comentario":{"resolucao":"CERTO. P(U > 9 | U > 7) = 0,16/0,5 = 0,32.","fundamento":"Probabilidade condicional.","macete":"Divida pela metade superior.","erroComum":"Esquecer de dividir.","comoBancaPensa":"Conta."}},"ES-517":{"cognitivo":{"motivo":"Reconhecer o ponto: cauda mais distante.","palavraCritica":"inferior a 0,16"},"comentario":{"resolucao":"CERTO. 4 ton está a 1,5 DP abaixo da média: P(U < 4) = P(Z < −1,5) < P(Z < −1) = 0,16.","fundamento":"Normal.","macete":"Mais longe da média, menor a cauda.","erroComum":"Igualar.","comoBancaPensa":"Comparação."}},"ES-518":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidades pontuais.","palavraCritica":"P(X = 5) = P(X = 9) < P(X = 7)"},"comentario":{"resolucao":"ERRADO. Para variável contínua, todas as probabilidades pontuais são zero: P(X = 5) = P(X = 9) = P(X = 7) = 0. A desigualdade estrita é falsa.","fundamento":"Variável contínua.","macete":"Ponto: probabilidade zero.","erroComum":"Confundir com densidade.","comoBancaPensa":"Conceito."}},"ES-519":{"cognitivo":{"motivo":"Reconhecer o ponto: acima da média.","palavraCritica":"inferior a 0,49"},"comentario":{"resolucao":"ERRADO. Na normal, P(X > μ) = 0,5, qualquer que seja o desvio padrão.","fundamento":"Normal.","macete":"Metade acima da média.","erroComum":"Achar que depende do DP.","comoBancaPensa":"Conceito."}},"ES-520":{"cognitivo":{"motivo":"Reconhecer o ponto: quantil da normal.","palavraCritica":"P(X > 38,225) = 0,05"},"comentario":{"resolucao":"CERTO. σ = √25 = 5. 30 + 1,645 × 5 = 38,225: P(X > 38,225) = P(Z > 1,645) = 0,05.","fundamento":"Normal.","macete":"x = μ + zσ.","erroComum":"Usar a variância.","comoBancaPensa":"Conta."}},"ES-521":{"cognitivo":{"motivo":"Reconhecer o ponto: transformação linear.","palavraCritica":"variância 4"},"comentario":{"resolucao":"ERRADO. X = 4Z + 2 tem média 2 e variância 4² × 1 = 16.","fundamento":"Normal.","macete":"Var(aZ + b) = a²·Var(Z).","erroComum":"Esquecer o quadrado.","comoBancaPensa":"Erro clássico."}},"ES-522":{"cognitivo":{"motivo":"Reconhecer o ponto: gerar normal a partir da padrão.","palavraCritica":"x = 5 + 4z"},"comentario":{"resolucao":"ERRADO. Para variância 4, o desvio padrão é 2: x = 5 + 2z. Com 4z, a variância seria 16.","fundamento":"Normal.","macete":"Multiplique pelo DP, não pela variância.","erroComum":"Usar a variância.","comoBancaPensa":"Erro clássico."}},"ES-523":{"cognitivo":{"motivo":"Reconhecer o ponto: contínua: < e ≤.","palavraCritica":"P(X̄ <10) < P(X̄ ≤10)"},"comentario":{"resolucao":"ERRADO. X̄ é contínua (normal), logo P(X̄ = 10) = 0 e P(X̄ < 10) = P(X̄ ≤ 10) = 0,5.","fundamento":"Variável contínua.","macete":"Em contínuas, < e ≤ dão o mesmo.","erroComum":"Achar que o 'igual' acrescenta.","comoBancaPensa":"Conceito."}},"ES-524":{"cognitivo":{"motivo":"Reconhecer o ponto: uniforme discreta.","palavraCritica":"uniforme discreta"},"comentario":{"resolucao":"CERTO. Xk assume dois valores (−0,2k e 0,2k), cada um com probabilidade 0,5: distribuição uniforme discreta.","fundamento":"Distribuição uniforme discreta.","macete":"Valores equiprováveis.","erroComum":"Achar que precisa de muitos valores.","comoBancaPensa":"Conceito."}},"ES-525":{"cognitivo":{"motivo":"Reconhecer o ponto: esperança da soma.","palavraCritica":"igual a zero"},"comentario":{"resolucao":"CERTO. E[Xk] = 0,5(−0,2k) + 0,5(0,2k) = 0 para todo k; logo E[Sn] = 0.","fundamento":"Esperança.","macete":"Linearidade.","erroComum":"Errar sinais.","comoBancaPensa":"Conta."}},"ES-526":{"cognitivo":{"motivo":"Reconhecer o ponto: média pela acumulada.","palavraCritica":"inferior a 4"},"comentario":{"resolucao":"ERRADO. f(x) = F'(x) = x/32 em [0, 8]. E[X] = ∫₀⁸ x²/32 dx = 512/96 ≈ 5,33, não inferior a 4.","fundamento":"Variáveis contínuas.","macete":"Derive F e integre x·f.","erroComum":"Usar o ponto médio.","comoBancaPensa":"Cálculo."}},"ES-527":{"cognitivo":{"motivo":"Reconhecer o ponto: densidade fora do suporte.","palavraCritica":"igual a zero"},"comentario":{"resolucao":"CERTO. Para x > 8, F(x) = 1 é constante, logo f(x) = F'(x) = 0.","fundamento":"Variáveis contínuas.","macete":"F constante ⇒ densidade zero.","erroComum":"Confundir F com f.","comoBancaPensa":"Conceito."}},"ES-528":{"cognitivo":{"motivo":"Reconhecer o ponto: constante de normalização.","palavraCritica":"inferior a 0,01"},"comentario":{"resolucao":"CERTO. ∫₀²⁴ y(x − 12)² dx = y × 2 × 12³/3 = 1.152y = 1 ⇒ y = 1/1.152 ≈ 0,00087, inferior a 0,01.","fundamento":"Densidade.","macete":"A integral da densidade é 1.","erroComum":"Errar a integral.","comoBancaPensa":"Cálculo."}},"ES-529":{"cognitivo":{"motivo":"Reconhecer o ponto: densidade como mínimo.","palavraCritica":"mínimo"},"comentario":{"resolucao":"CERTO. Derivando: f(x) = (x − 2)/3 em [2, 4) e (10 − 2x)/3 em [4, 5]. Em [2, 4], (x − 2)/3 ≤ (10 − 2x)/3; em [4, 5], o contrário. Logo f(x) = mín{(x − 2)/3, (10 − 2x)/3}.","fundamento":"Densidade a partir da acumulada.","macete":"Derive cada trecho e compare.","erroComum":"Errar a derivada.","comoBancaPensa":"Cálculo."}},"ES-530":{"cognitivo":{"motivo":"Reconhecer o ponto: parâmetro fixado pela normalização.","palavraCritica":"estimado"},"comentario":{"resolucao":"ERRADO. A constante a não é livre: ∫₋₁¹ a·w² dw = 2a/3 = 1 ⇒ a = 3/2. Não há o que estimar com amostra.","fundamento":"Densidade.","macete":"Constante de normalização é determinada.","erroComum":"Tratar como parâmetro.","comoBancaPensa":"Conceito."}},"ES-531":{"cognitivo":{"motivo":"Reconhecer o ponto: média de densidade simétrica.","palavraCritica":"média de W é igual a a"},"comentario":{"resolucao":"ERRADO. A densidade é simétrica em torno de 0: E[W] = 0. Como a = 1,5, a média não é a.","fundamento":"Esperança.","macete":"Simetria ⇒ média no centro.","erroComum":"Confundir parâmetro com média.","comoBancaPensa":"Troca."}},"ES-532":{"cognitivo":{"motivo":"Reconhecer o ponto: moda nas extremidades.","palavraCritica":"moda de W é igual à média"},"comentario":{"resolucao":"ERRADO. f(w) = 1,5w² é mínima em 0 e máxima em w = ±1: as modas estão nas extremidades, e a média é 0.","fundamento":"Moda.","macete":"Moda = máximo da densidade.","erroComum":"Achar que coincide com a média.","comoBancaPensa":"Forma em U."}},"ES-533":{"cognitivo":{"motivo":"Reconhecer o ponto: mediana.","palavraCritica":"mediana de W é igual a 0"},"comentario":{"resolucao":"CERTO. Pela simetria em torno de 0, P(W < 0) = 0,5: mediana 0.","fundamento":"Mediana.","macete":"Simetria.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-534":{"cognitivo":{"motivo":"Reconhecer o ponto: variância.","palavraCritica":"3/5"},"comentario":{"resolucao":"CERTO. Var = E[W²] = ∫₋₁¹ 1,5w⁴ dw = 1,5 × 2/5 = 3/5.","fundamento":"Variância.","macete":"Média 0 ⇒ Var = E[W²].","erroComum":"Errar a integral.","comoBancaPensa":"Cálculo."}},"ES-535":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade central.","palavraCritica":"menor que 0,15"},"comentario":{"resolucao":"CERTO. P(−0,5 < W < 0,5) = 2 × 1,5 × (0,5)³/3 = 0,125 < 0,15.","fundamento":"Integral da densidade.","macete":"Integre a·w².","erroComum":"Errar o cubo.","comoBancaPensa":"Cálculo."}},"ES-536":{"cognitivo":{"motivo":"Reconhecer o ponto: densidades diferentes.","palavraCritica":"equivalente à distribuição de W"},"comentario":{"resolucao":"ERRADO. g(y) = a·y em [0, 1] exige a = 2 e tem outro suporte e outra forma (média 2/3). Não equivale à distribuição de W.","fundamento":"Densidades.","macete":"Compare suporte e forma.","erroComum":"Achar que basta a mesma letra.","comoBancaPensa":"Conceito."}},"ES-537":{"cognitivo":{"motivo":"Reconhecer o ponto: padronização incorreta.","palavraCritica":"média 0 e variância 1"},"comentario":{"resolucao":"ERRADO. Com a = 1,5, W·√2,5/a tem média 0, mas variância (2,5/2,25) × 3/5 ≈ 0,667, não 1. Para variância 1, seria preciso multiplicar por √(5/3).","fundamento":"Variância de transformação.","macete":"Var(cW) = c²·Var(W).","erroComum":"Errar o fator.","comoBancaPensa":"Cálculo."}},"ES-538":{"cognitivo":{"motivo":"Reconhecer o ponto: poder do teste.","palavraCritica":"1 −α"},"comentario":{"resolucao":"ERRADO. O poder é 1 − β (probabilidade de rejeitar H0 quando ela é falsa). 1 − α é o nível de confiança.","fundamento":"Erros e poder.","macete":"Poder = 1 − β.","erroComum":"Confundir com 1 − α.","comoBancaPensa":"Troca de conceito."}},"ES-539":{"cognitivo":{"motivo":"Reconhecer o ponto: significado de α.","palavraCritica":"5% de probabilidade de se aceitar"},"comentario":{"resolucao":"ERRADO. α = 5% é a probabilidade de REJEITAR H0 (concluir que as composições diferem) quando H0 é verdadeira. Aceitar composição igual quando são diferentes é o erro do tipo II (β).","fundamento":"Erros tipo I e II.","macete":"α: rejeitar H0 verdadeira.","erroComum":"Trocar os erros.","comoBancaPensa":"Troca de conceito."}},"ES-540":{"cognitivo":{"motivo":"Reconhecer o ponto: caudas do teste bilateral.","palavraCritica":"cada uma delas ao nível de significância α"},"comentario":{"resolucao":"ERRADO. No teste bilateral, cada cauda tem α/2; juntas somam α.","fundamento":"Região crítica.","macete":"Bilateral: α/2 de cada lado.","erroComum":"Pôr α em cada cauda.","comoBancaPensa":"Erro clássico."}},"ES-541":{"cognitivo":{"motivo":"Reconhecer o ponto: erro do tipo II.","palavraCritica":"rejeitar a hipótese alternativa quando esta for falsa"},"comentario":{"resolucao":"ERRADO. Erro do tipo II é NÃO rejeitar H0 quando ela é falsa. Rejeitar H1 quando H1 é falsa é uma decisão correta.","fundamento":"Erros tipo I e II.","macete":"Tipo II: manter H0 falsa.","erroComum":"Confundir.","comoBancaPensa":"Troca de conceito."}},"ES-542":{"cognitivo":{"motivo":"Reconhecer o ponto: erro do tipo I.","palavraCritica":"erro do tipo I"},"comentario":{"resolucao":"CERTO. Erro do tipo I: rejeitar H0 quando ela é verdadeira.","fundamento":"Erros tipo I e II.","macete":"Tipo I: rejeitar H0 verdadeira.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-543":{"cognitivo":{"motivo":"Reconhecer o ponto: foco na hipótese nula.","palavraCritica":"avaliar a hipótese nula"},"comentario":{"resolucao":"CERTO. O teste é construído sob H0: decide-se rejeitá-la ou não com base na evidência amostral.","fundamento":"Testes de hipóteses.","macete":"A decisão é sobre H0.","erroComum":"Achar que se testa H1.","comoBancaPensa":"Conceito."}},"ES-544":{"cognitivo":{"motivo":"Reconhecer o ponto: valores de α.","palavraCritica":"90%, 95% e 99%"},"comentario":{"resolucao":"ERRADO. Os níveis de significância usuais são pequenos (10%, 5%, 1%). 90%, 95% e 99% são níveis de confiança (1 − α).","fundamento":"Nível de significância.","macete":"α pequeno; confiança grande.","erroComum":"Trocar.","comoBancaPensa":"Troca de conceito."}},"ES-545":{"cognitivo":{"motivo":"Reconhecer o ponto: α e erro do tipo I.","palavraCritica":"erro do tipo II"},"comentario":{"resolucao":"ERRADO. O nível de significância é a probabilidade máxima do erro do tipo I, não do tipo II.","fundamento":"Nível de significância.","macete":"α ↔ tipo I; β ↔ tipo II.","erroComum":"Trocar.","comoBancaPensa":"Troca de conceito."}},"ES-546":{"cognitivo":{"motivo":"Reconhecer o ponto: α e poder.","palavraCritica":"potência"},"comentario":{"resolucao":"CERTO. Reduzir α (região crítica menor) aumenta β e reduz o poder; aumentar α aumenta o poder, mantido o resto.","fundamento":"Poder do teste.","macete":"α e β andam em sentidos opostos.","erroComum":"Achar que são independentes.","comoBancaPensa":"Conceito."}},"ES-547":{"cognitivo":{"motivo":"Reconhecer o ponto: decisão pelo p-valor.","palavraCritica":"não haveria evidências"},"comentario":{"resolucao":"ERRADO. p-valor = 0,0001 < 0,01: rejeita-se H0 a 1%. Há evidência contra o teor de 37%.","fundamento":"p-valor.","macete":"p < α ⇒ rejeita.","erroComum":"Inverter a regra.","comoBancaPensa":"Inverte a decisão."}},"ES-548":{"cognitivo":{"motivo":"Reconhecer o ponto: estatística t.","palavraCritica":"igual a 0,5"},"comentario":{"resolucao":"ERRADO. t = (38 − 37)/(2/√64) = 1/0,25 = 4, não 0,5.","fundamento":"Teste t.","macete":"t = (x̄ − μ0)/(s/√n).","erroComum":"Esquecer o √n.","comoBancaPensa":"Erro clássico."}},"ES-549":{"cognitivo":{"motivo":"Reconhecer o ponto: erro do tipo II.","palavraCritica":"erro do tipo II"},"comentario":{"resolucao":"ERRADO. Rejeitar H0 verdadeira é erro do tipo I. O tipo II é não rejeitar H0 falsa.","fundamento":"Erros.","macete":"Tipo I: rejeitar o verdadeiro.","erroComum":"Trocar.","comoBancaPensa":"Troca de conceito."}},"ES-550":{"cognitivo":{"motivo":"Reconhecer o ponto: teste z com σ conhecido.","palavraCritica":"deve ser aceita"},"comentario":{"resolucao":"CERTO. Média amostral = 57/4 = 14,25. σ = 3: z = (14,25 − 12)/(3/2) = 1,5 < 1,96. Não se rejeita H0 a 5%.","fundamento":"Teste z.","macete":"σ conhecido → z.","erroComum":"Usar a variância 9 como DP.","comoBancaPensa":"Cálculo."}},"ES-551":{"cognitivo":{"motivo":"Reconhecer o ponto: graus de liberdade.","palavraCritica":"20 graus de liberdade"},"comentario":{"resolucao":"ERRADO. Para o teste t da média com n = 20, os graus de liberdade são n − 1 = 19.","fundamento":"Teste t.","macete":"gl = n − 1.","erroComum":"Usar n.","comoBancaPensa":"Erro clássico."}},"ES-552":{"cognitivo":{"motivo":"Reconhecer o ponto: teste unilateral.","palavraCritica":"deve ser rejeitada"},"comentario":{"resolucao":"ERRADO. z = (5 − 4,5)/(4/10) = 1,25 < 1,96 (crítico a 2,5% unilateral). Não se rejeita H0.","fundamento":"Teste z unilateral.","macete":"Compare com o crítico da cauda.","erroComum":"Usar a variância.","comoBancaPensa":"Cálculo."}},"ES-553":{"cognitivo":{"motivo":"Reconhecer o ponto: rejeição bilateral.","palavraCritica":"deve ser rejeitada"},"comentario":{"resolucao":"CERTO. z = (20 − 19,5)/(2/√400) = 0,5/0,1 = 5 > 2: rejeita-se H0 a 5%.","fundamento":"Teste z.","macete":"DP da média = s/√n.","erroComum":"Esquecer o √n.","comoBancaPensa":"Cálculo."}},"ES-554":{"cognitivo":{"motivo":"Reconhecer o ponto: uso da t de Student.","palavraCritica":"inferiores a 30"},"comentario":{"resolucao":"CERTO, na visão da banca. A t de Student é usada quando a variância populacional é desconhecida e estimada pela amostra, situação típica de amostras pequenas (regra prática: n < 30), com população normal.","fundamento":"Distribuição t.","macete":"σ desconhecido e n pequeno → t.","erroComum":"Achar que vale para todo caso.","comoBancaPensa":"Regra prática."}},"ES-555":{"cognitivo":{"motivo":"Reconhecer o ponto: média acima de 37 sem significância.","palavraCritica":"não haverá evidências"},"comentario":{"resolucao":"CERTO. t = (38 − 37)/√(750/30) = 1/5 = 0,2 < 1,7. A diferença não é significativa a 5%, apesar de a média amostral superar 37.","fundamento":"Teste t.","macete":"Diferença amostral ≠ significância.","erroComum":"Ver só o valor 38.","comoBancaPensa":"Cálculo."}},"ES-556":{"cognitivo":{"motivo":"Reconhecer o ponto: regra de decisão.","palavraCritica":"se ҧ𝑥> 2"},"comentario":{"resolucao":"ERRADO. Com σ = 12 e n = 144, o erro padrão é 1. A 5% unilateral, rejeita-se H0 se x̄ > 2 + 1,645 × 1 ≈ 3,645, e não simplesmente se x̄ > 2.","fundamento":"Região crítica.","macete":"Crítico = μ0 + z·σ/√n.","erroComum":"Ignorar a variabilidade.","comoBancaPensa":"Regra ingênua."}},"ES-557":{"cognitivo":{"motivo":"Reconhecer o ponto: teste t unilateral.","palavraCritica":"evidências estatisticamente significativas"},"comentario":{"resolucao":"ERRADO. t = (58 − 60)/(4/√16) = −2. Com 15 graus de liberdade, P(T < −2) ≈ 0,03, acima de 2,3%: não se rejeita H0. (O valor 0,023 vale para a normal, não para a t.)","fundamento":"Teste t.","macete":"A t tem caudas mais pesadas que a normal.","erroComum":"Usar a tabela da normal.","comoBancaPensa":"Troca z por t."}},"ES-558":{"cognitivo":{"motivo":"Reconhecer o ponto: erro do tipo I.","palavraCritica":"erro do tipo II"},"comentario":{"resolucao":"ERRADO. Rejeitar H0 quando ela não deveria ser rejeitada é erro do tipo I.","fundamento":"Erros.","macete":"Rejeitar o verdadeiro = tipo I.","erroComum":"Trocar.","comoBancaPensa":"Troca de conceito."}},"ES-559":{"cognitivo":{"motivo":"Reconhecer o ponto: poder depende de μ.","palavraCritica":"para qualquer valor"},"comentario":{"resolucao":"ERRADO. O poder (1 − β) varia com o valor verdadeiro de μ; não é 1 − α nem constante.","fundamento":"Poder.","macete":"Poder é uma função de μ.","erroComum":"Confundir com 1 − α.","comoBancaPensa":"Termo absoluto."}},"ES-560":{"cognitivo":{"motivo":"Reconhecer o ponto: p-valor com a t.","palavraCritica":"superior a 2,3%"},"comentario":{"resolucao":"CERTO. Com t = −2 e 15 graus de liberdade, P(T < −2) ≈ 0,03, superior a 2,3%.","fundamento":"p-valor.","macete":"t tem caudas mais pesadas.","erroComum":"Usar a normal.","comoBancaPensa":"Comparação."}},"ES-561":{"cognitivo":{"motivo":"Reconhecer o ponto: graus de liberdade.","palavraCritica":"10 graus de liberdade"},"comentario":{"resolucao":"ERRADO. Com n = 10, o teste t para a média tem n − 1 = 9 graus de liberdade.","fundamento":"Teste t.","macete":"gl = n − 1.","erroComum":"Usar n.","comoBancaPensa":"Erro clássico."}},"ES-562":{"cognitivo":{"motivo":"Reconhecer o ponto: validade do t para amostra pequena.","palavraCritica":"inválido"},"comentario":{"resolucao":"ERRADO. Com população normal e variância desconhecida, o teste t é justamente o indicado para amostras pequenas; n = 10 não o invalida.","fundamento":"Teste t.","macete":"t foi feito para n pequeno.","erroComum":"Exigir n ≥ 30.","comoBancaPensa":"Confusão."}},"ES-563":{"cognitivo":{"motivo":"Reconhecer o ponto: média menor não basta.","palavraCritica":"deve ser rejeitada"},"comentario":{"resolucao":"ERRADO. Com σ = 2 conhecido, o teste adequado é o z (não o t), e z = (9,8 − 10)/(2/5) = −0,5. Como −0,5 > −2 (crítico a 2,3%), não se rejeita H0. Média amostral abaixo de 10 não basta.","fundamento":"Teste z.","macete":"Compare com o crítico.","erroComum":"Decidir só pelo sinal.","comoBancaPensa":"Dois erros."}},"ES-564":{"cognitivo":{"motivo":"Reconhecer o ponto: dois tipos de erro.","palavraCritica":"do tipo I"},"comentario":{"resolucao":"CERTO. Tipo I: rejeitar H0 verdadeira. Tipo II: não rejeitar H0 falsa.","fundamento":"Erros.","macete":"Duas decisões erradas possíveis.","erroComum":"Trocar.","comoBancaPensa":"Conceito."}},"ES-565":{"cognitivo":{"motivo":"Reconhecer o ponto: teste unilateral.","palavraCritica":"bilateral"},"comentario":{"resolucao":"ERRADO. Com HA: μ < 10, o teste é unilateral à esquerda (uma única região crítica). Não existe 'região de rejeição da hipótese alternativa'.","fundamento":"Tipos de teste.","macete":"Sinal de H1 define as caudas.","erroComum":"Ver duas hipóteses como duas caudas.","comoBancaPensa":"Conceito."}},"ES-566":{"cognitivo":{"motivo":"Reconhecer o ponto: poder variável.","palavraCritica":"95%"},"comentario":{"resolucao":"ERRADO. O poder varia com o μ verdadeiro (próximo de 10, é perto de α; longe, perto de 1). 95% é 1 − α.","fundamento":"Poder.","macete":"Poder ≠ 1 − α.","erroComum":"Confundir.","comoBancaPensa":"Termo absoluto."}},"ES-567":{"cognitivo":{"motivo":"Reconhecer o ponto: comparação com o crítico.","palavraCritica":"não haverá evidências"},"comentario":{"resolucao":"CERTO. 9,10 < 10,7 (crítico com 4 gl a 3%): não se rejeita a independência.","fundamento":"Teste qui-quadrado.","macete":"Estatística < crítico ⇒ não rejeita.","erroComum":"Inverter.","comoBancaPensa":"Comparação."}},"ES-568":{"cognitivo":{"motivo":"Reconhecer o ponto: qui-quadrado para categóricas.","palavraCritica":"variáveis numéricas"},"comentario":{"resolucao":"ERRADO. O teste qui-quadrado analisa associação entre variáveis categóricas (frequências). Para numéricas, usa-se correlação.","fundamento":"Qui-quadrado.","macete":"Categorias → qui-quadrado.","erroComum":"Confundir com correlação.","comoBancaPensa":"Troca de conceito."}},"ES-569":{"cognitivo":{"motivo":"Reconhecer o ponto: graus de liberdade.","palavraCritica":"igual a 2"},"comentario":{"resolucao":"CERTO. Tabela 3 × 2: gl = (3 − 1)(2 − 1) = 2.","fundamento":"Qui-quadrado.","macete":"(l − 1)(c − 1).","erroComum":"Contar células.","comoBancaPensa":"Fórmula."}},"ES-570":{"cognitivo":{"motivo":"Reconhecer o ponto: valor alto da estatística.","palavraCritica":"superior a 60"},"comentario":{"resolucao":"CERTO. Com 2 gl, o crítico a 5% é 5,99. Uma estatística acima de 60 rejeita a independência: há associação com 95% de confiança. (Os dados dão χ² ≈ 60,2.)","fundamento":"Qui-quadrado.","macete":"Compare com o crítico do gl certo.","erroComum":"Errar o gl.","comoBancaPensa":"Comparação."}},"ES-571":{"cognitivo":{"motivo":"Reconhecer o ponto: frequências esperadas pequenas.","palavraCritica":"será válido"},"comentario":{"resolucao":"ERRADO. Com Q1 = 20 sim/2 não e Q2 = 2 sim/7 não (31 alunos), algumas frequências esperadas ficam abaixo de 5 (por exemplo, 'não' em Q2 ≈ 2,6). A aproximação qui-quadrado não é válida.","fundamento":"Condições do teste.","macete":"Esperadas ≥ 5.","erroComum":"Olhar só as observadas.","comoBancaPensa":"Condição."}},"ES-572":{"cognitivo":{"motivo":"Reconhecer o ponto: cálculo do qui-quadrado 2×2.","palavraCritica":"6,4"},"comentario":{"resolucao":"CERTO. Esperadas: 10 em cada célula. χ² = 4 × (4²/10) = 6,4.","fundamento":"Qui-quadrado.","macete":"(O − E)²/E somado.","erroComum":"Errar as esperadas.","comoBancaPensa":"Cálculo."}},"ES-573":{"cognitivo":{"motivo":"Reconhecer o ponto: p-valor unilateral.","palavraCritica":"será rejeitada"},"comentario":{"resolucao":"CERTO. Com p bilateral 0,08, o unilateral (na direção observada) é 0,04 < 0,05: rejeita-se H0 contra H1: pQ1 > pQ2.","fundamento":"p-valor.","macete":"Unilateral = metade (na direção certa).","erroComum":"Usar 0,08.","comoBancaPensa":"Conceito."}},"ES-574":{"cognitivo":{"motivo":"Reconhecer o ponto: gl em tabela 3×3.","palavraCritica":"4 graus de liberdade"},"comentario":{"resolucao":"CERTO. (3 − 1)(3 − 1) = 4.","fundamento":"Qui-quadrado.","macete":"(l − 1)(c − 1).","erroComum":"Contar 9.","comoBancaPensa":"Fórmula."}},"ES-575":{"cognitivo":{"motivo":"Reconhecer o ponto: frequências esperadas.","palavraCritica":"7,6, 26 e 38,8"},"comentario":{"resolucao":"CERTO. Totais: linhas 38, 65, 97; colunas 40, 80, 80; N = 200. E11 = 38×40/200 = 7,6; E22 = 65×80/200 = 26; E33 = 97×80/200 = 38,8.","fundamento":"Qui-quadrado.","macete":"E = linha × coluna / N.","erroComum":"Erro de total.","comoBancaPensa":"Cálculo."}},"ES-576":{"cognitivo":{"motivo":"Reconhecer o ponto: homogeneidade também tem 4 gl.","palavraCritica":"apenas 2 graus de liberdade"},"comentario":{"resolucao":"ERRADO. No teste de homogeneidade da eficiência entre os 3 níveis de escolaridade, o gl continua (3 − 1)(3 − 1) = 4.","fundamento":"Qui-quadrado.","macete":"Homogeneidade e independência: mesmo gl.","erroComum":"Usar só uma dimensão.","comoBancaPensa":"Erro de gl."}},"ES-577":{"cognitivo":{"motivo":"Reconhecer o ponto: decisão com os dados.","palavraCritica":"não há evidências"},"comentario":{"resolucao":"ERRADO. Calculando Σ(O − E)²/E com as esperadas sob independência, obtém-se χ² ≈ 33,1, muito acima de 9,488 (crítico com 4 gl a 5%). Rejeita-se a independência.","fundamento":"Qui-quadrado.","macete":"Compare com o crítico.","erroComum":"Errar o gl.","comoBancaPensa":"Cálculo."}},"ES-578":{"cognitivo":{"motivo":"Reconhecer o ponto: p-valor depende do gl.","palavraCritica":"independentemente dos graus de liberdade"},"comentario":{"resolucao":"ERRADO. A distribuição qui-quadrado muda com os graus de liberdade; o p-valor deve ser lido na linha do gl correto.","fundamento":"Qui-quadrado.","macete":"Sempre use o gl.","erroComum":"Ignorar o gl.","comoBancaPensa":"Conceito."}},"ES-579":{"cognitivo":{"motivo":"Reconhecer o ponto: esperadas > 5 não é restrição.","palavraCritica":"restrições"},"comentario":{"resolucao":"ERRADO. A restrição do teste ocorre quando há frequências esperadas pequenas (menores que 5). Todas acima de 5 significa que o teste é aplicável.","fundamento":"Condições do teste.","macete":"Esperadas grandes = ok.","erroComum":"Inverter a regra.","comoBancaPensa":"Inverte."}},"ES-580":{"cognitivo":{"motivo":"Reconhecer o ponto: cálculo de Q.","palavraCritica":"superior a 7"},"comentario":{"resolucao":"CERTO. Esperadas: homens 15, 24, 21; mulheres 10, 16, 14. Q = 0 + 1,5 + 1,714 + 0 + 2,25 + 2,571 ≈ 8,04, superior a 7.","fundamento":"Qui-quadrado.","macete":"E = linha × coluna / N.","erroComum":"Erro de conta.","comoBancaPensa":"Cálculo."}},"ES-581":{"cognitivo":{"motivo":"Reconhecer o ponto: frequência esperada.","palavraCritica":"Oi"},"comentario":{"resolucao":"CERTO. Sob independência, eij = (total da linha i × total da coluna j)/N.","fundamento":"Qui-quadrado.","macete":"Linha × coluna / N.","erroComum":"Somar em vez de multiplicar.","comoBancaPensa":"Fórmula."}},"ES-582":{"cognitivo":{"motivo":"Reconhecer o ponto: fórmula errada.","palavraCritica":"estatística do teste"},"comentario":{"resolucao":"ERRADO. A expressão Eij = (xi· + x·j)/n soma os totais, quando o correto para a frequência esperada é (xi·)(x·j)/n; além disso, a estatística do teste é Σ(O − E)²/E, não a frequência esperada.","fundamento":"Qui-quadrado.","macete":"Esperada = produto dos totais / n.","erroComum":"Somar.","comoBancaPensa":"Dois erros."}},"ES-583":{"cognitivo":{"motivo":"Reconhecer o ponto: teste de aderência.","palavraCritica":"inferior a 10"},"comentario":{"resolucao":"CERTO. Esperadas: 30, 50, 20. χ² = 4/30 + 49/50 + 81/20 ≈ 0,13 + 0,98 + 4,05 = 5,16, inferior a 10.","fundamento":"Aderência.","macete":"E = n × proporção.","erroComum":"Errar as esperadas.","comoBancaPensa":"Cálculo."}},"ES-584":{"cognitivo":{"motivo":"Reconhecer o ponto: comparação de distribuições.","palavraCritica":"7÷9"},"comentario":{"resolucao":"CERTO. Tratando 2006 e 2007 como uma tabela 2 × 3 (100 mil em cada ano: 70, 16, 14 e 74, 16, 10), as esperadas são 72, 16 e 12 em cada ano. χ² = 2 × (2²/72 + 0 + 2²/12) = 1/9 + 2/3 = 7/9, com (2 − 1)(3 − 1) = 2 gl.","fundamento":"Qui-quadrado de homogeneidade.","macete":"Média dos dois anos como esperada.","erroComum":"Usar 2006 como esperado.","comoBancaPensa":"Cálculo."}},"ES-585":{"cognitivo":{"motivo":"Reconhecer o ponto: gl da independência.","palavraCritica":"(a – 1)*(b – 1)"},"comentario":{"resolucao":"CERTO. Para a × b categorias, gl = (a − 1)(b − 1).","fundamento":"Qui-quadrado.","macete":"(l − 1)(c − 1).","erroComum":"Usar a × b.","comoBancaPensa":"Fórmula."}},"ES-586":{"cognitivo":{"motivo":"Reconhecer o ponto: gl de tabela 2×3.","palavraCritica":"2 graus de liberdade"},"comentario":{"resolucao":"CERTO. 2 × 3: (2 − 1)(3 − 1) = 2.","fundamento":"Qui-quadrado.","macete":"(l − 1)(c − 1).","erroComum":"Contar 6.","comoBancaPensa":"Fórmula."}},"ES-587":{"cognitivo":{"motivo":"Reconhecer o ponto: hipótese nula = independência.","palavraCritica":"mutuamente dependentes"},"comentario":{"resolucao":"ERRADO. No teste de independência, H0 afirma que as variáveis são independentes; a dependência é a alternativa.","fundamento":"Hipóteses.","macete":"H0: independência.","erroComum":"Inverter.","comoBancaPensa":"Inverte."}},"ES-588":{"cognitivo":{"motivo":"Reconhecer o ponto: tabela de contingência.","palavraCritica":"tabela de contingência"},"comentario":{"resolucao":"CERTO. A tabela de contingência mostra a distribuição conjunta de variáveis categóricas e é a base do teste de independência.","fundamento":"Dados categorizados.","macete":"Cruzamento de categorias.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-589":{"cognitivo":{"motivo":"Reconhecer o ponto: qui-quadrado não mede associação linear.","palavraCritica":"associação linear"},"comentario":{"resolucao":"ERRADO. O qui-quadrado avalia associação entre variáveis categóricas, não associação linear entre quantitativas contínuas; e valores MAIORES indicam maior afastamento da independência.","fundamento":"Qui-quadrado.","macete":"Quanto maior, mais evidência de associação.","erroComum":"Confundir com correlação.","comoBancaPensa":"Dois erros."}},"ES-590":{"cognitivo":{"motivo":"Reconhecer o ponto: regra das esperadas.","palavraCritica":"valor observado"},"comentario":{"resolucao":"ERRADO. A restrição de validade refere-se às frequências ESPERADAS pequenas (menores que 5), não às observadas.","fundamento":"Condições do teste.","macete":"Olhe as esperadas.","erroComum":"Olhar as observadas.","comoBancaPensa":"Troca de conceito."}},"ES-591":{"cognitivo":{"motivo":"Reconhecer o ponto: hipótese alternativa.","palavraCritica":"independentes"},"comentario":{"resolucao":"ERRADO. A independência é a hipótese NULA; a alternativa seria a associação (dependência) entre sexo e escolaridade.","fundamento":"Hipóteses.","macete":"H1: dependência.","erroComum":"Inverter.","comoBancaPensa":"Inverte."}},"ES-592":{"cognitivo":{"motivo":"Reconhecer o ponto: valor da estatística.","palavraCritica":"maior que 1"},"comentario":{"resolucao":"ERRADO. Esperadas: masculino 9,17; 15,28; 30,56 e feminino 5,83; 9,72; 19,44. χ² ≈ 0,23, menor que 1 (os dados são quase proporcionais).","fundamento":"Qui-quadrado.","macete":"Calcule as esperadas.","erroComum":"Supor associação.","comoBancaPensa":"Cálculo."}},"ES-593":{"cognitivo":{"motivo":"Reconhecer o ponto: qui-quadrado 2×2.","palavraCritica":"igual ou superior a 7"},"comentario":{"resolucao":"ERRADO. Esperadas: 15, 15, 25, 25. χ² = 25/15 + 25/15 + 25/25 + 25/25 ≈ 5,33, inferior a 7.","fundamento":"Qui-quadrado.","macete":"E = linha × coluna / N.","erroComum":"Erro de conta.","comoBancaPensa":"Cálculo."}},"ES-594":{"cognitivo":{"motivo":"Reconhecer o ponto: esperadas erradas.","palavraCritica":"valores corretos esperados"},"comentario":{"resolucao":"ERRADO. Sob H0, as esperadas são 150 × 150/200 = 112,5 e 37,5 (público I) e 37,5 e 12,5 (público II), não 110, 40, 40 e 10.","fundamento":"Qui-quadrado.","macete":"E = linha × coluna / N.","erroComum":"Arredondar.","comoBancaPensa":"Valores próximos."}},"ES-595":{"cognitivo":{"motivo":"Reconhecer o ponto: gl de 2×2.","palavraCritica":"três graus de liberdade"},"comentario":{"resolucao":"ERRADO. Tabela 2 × 2: (2 − 1)(2 − 1) = 1 grau de liberdade.","fundamento":"Qui-quadrado.","macete":"(l − 1)(c − 1).","erroComum":"Usar n − 1 com 4 células.","comoBancaPensa":"Fórmula."}},"ES-596":{"cognitivo":{"motivo":"Reconhecer o ponto: medida de discrepância.","palavraCritica":"discrepância"},"comentario":{"resolucao":"CERTO. χ² = Σ(o − e)²/e mede a discrepância entre frequências observadas e esperadas.","fundamento":"Qui-quadrado.","macete":"Diferença O − E padronizada.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-597":{"cognitivo":{"motivo":"Reconhecer o ponto: moeda: 30 caras em 50.","palavraCritica":"inferior a 3,0"},"comentario":{"resolucao":"CERTO. Esperadas 25 e 25: χ² = 25/25 + 25/25 = 2, inferior a 3.","fundamento":"Aderência.","macete":"(O − E)²/E.","erroComum":"Esquecer uma parcela.","comoBancaPensa":"Cálculo."}},"ES-598":{"cognitivo":{"motivo":"Reconhecer o ponto: qui-quadrado 2×2.","palavraCritica":"igual ou inferior a 6"},"comentario":{"resolucao":"CERTO. Totais: linhas 30 e 20; colunas 30 e 20; N = 50. Esperadas: 18, 12, 12, 8. χ² = 16/18 + 16/12 + 16/12 + 16/8 ≈ 5,56 ≤ 6.","fundamento":"Qui-quadrado.","macete":"E = linha × coluna / N.","erroComum":"Erro de conta.","comoBancaPensa":"Cálculo."}},"ES-599":{"cognitivo":{"motivo":"Reconhecer o ponto: aderência a distribuição hipotética.","palavraCritica":"superior a 6"},"comentario":{"resolucao":"ERRADO. Observadas 5, 10, 20, 15; esperadas 10, 10, 20, 10. χ² = 25/10 + 0 + 0 + 25/10 = 5, não superior a 6.","fundamento":"Aderência.","macete":"(O − E)²/E.","erroComum":"Errar uma parcela.","comoBancaPensa":"Cálculo."}},"ES-600":{"cognitivo":{"motivo":"Reconhecer o ponto: moeda: 13 caras em 20.","palavraCritica":"1,4"},"comentario":{"resolucao":"ERRADO. Esperadas 10 e 10: χ² = 9/10 + 9/10 = 1,8, não 1,4.","fundamento":"Aderência.","macete":"Some as duas parcelas.","erroComum":"Somar só uma.","comoBancaPensa":"Cálculo."}},"ES-601":{"cognitivo":{"motivo":"Reconhecer o ponto: amplitude e tamanho da amostra.","palavraCritica":"aumentaria"},"comentario":{"resolucao":"ERRADO. A amplitude é 2·z·σ/√n: aumentando n de 25 para 28, ela DIMINUI.","fundamento":"Intervalo de confiança.","macete":"Mais dados, intervalo mais estreito.","erroComum":"Achar que mais dados aumentam a incerteza.","comoBancaPensa":"Inversão."}},"ES-602":{"cognitivo":{"motivo":"Reconhecer o ponto: iC com σ conhecido.","palavraCritica":"[33,38; 36,02]"},"comentario":{"resolucao":"CERTO. Margem = 1,88 × 3,5/√25 = 1,88 × 0,7 = 1,316. IC = 34,7 ± 1,316 = [33,38; 36,02].","fundamento":"IC para a média.","macete":"x̄ ± z·σ/√n.","erroComum":"Esquecer o √n.","comoBancaPensa":"Cálculo."}},"ES-603":{"cognitivo":{"motivo":"Reconhecer o ponto: viés de seleção x erro amostral.","palavraCritica":"erro amostral"},"comentario":{"resolucao":"ERRADO. A diferença de 10 anos (fora da margem de 2 anos) decorre da adesão voluntária (viés de seleção), um erro não amostral. Erro amostral é a variação aleatória de amostras probabilísticas.","fundamento":"Erros amostrais e não amostrais.","macete":"Amostra voluntária gera viés, não erro amostral.","erroComum":"Chamar tudo de erro amostral.","comoBancaPensa":"Conceito."}},"ES-604":{"cognitivo":{"motivo":"Reconhecer o ponto: erro padrão máximo de proporção.","palavraCritica":"sempre inferior a 2%"},"comentario":{"resolucao":"CERTO. O erro padrão de uma proporção é √[p(1 − p)/n], máximo em p = 0,5: √(0,25/900) = 0,5/30 ≈ 1,67%. Logo é sempre inferior a 2%.","fundamento":"Erro padrão de proporção.","macete":"Pior caso: p = 0,5.","erroComum":"Usar a margem de erro (×1,96).","comoBancaPensa":"Pior caso."}},"ES-605":{"cognitivo":{"motivo":"Reconhecer o ponto: erro padrão da média.","palavraCritica":"0,25%"},"comentario":{"resolucao":"CERTO. Erro padrão = s/√n = 2%/√64 = 0,25%.","fundamento":"Erro padrão.","macete":"s/√n.","erroComum":"Usar s.","comoBancaPensa":"Conta direta."}},"ES-606":{"cognitivo":{"motivo":"Reconhecer o ponto: margem proporcional ao desvio padrão.","palavraCritica":"4 ± 0,4375"},"comentario":{"resolucao":"CERTO. Em 2020: margem 0,5 = t × 1,6/√50 ⇒ t/√50 = 0,3125. Em 2024 (mesmo n e t): margem = 0,3125 × 1,4 = 0,4375. IC = 4 ± 0,4375.","fundamento":"IC para a média.","macete":"Margem ∝ desvio padrão.","erroComum":"Usar o mesmo 0,5.","comoBancaPensa":"Proporção."}},"ES-607":{"cognitivo":{"motivo":"Reconhecer o ponto: tamanho pelo coeficiente de variação.","palavraCritica":"menos de 500"},"comentario":{"resolucao":"ERRADO. Com erro relativo e = 5% e CV = 0,7: n = (z·CV/e)² = (1,96 × 0,7/0,05)² ≈ 753, mais de 500.","fundamento":"Tamanho de amostra.","macete":"n = (z·CV/e)².","erroComum":"Esquecer o quadrado.","comoBancaPensa":"Cálculo."}},"ES-608":{"cognitivo":{"motivo":"Reconhecer o ponto: intervalo para um indivíduo.","palavraCritica":"entre 15,8 e 35,4 horas"},"comentario":{"resolucao":"CERTO. Para o tempo de UM cliente (e não para a média), sob normalidade: 25,6 ± 1,96 × 5 = [15,8; 35,4] horas, com probabilidade 95%. Observação: a anotação do professor trata o item como intervalo para a média (25,6 ± 0,98) e marca ERRADO; mantido o gabarito impresso, coerente com a leitura do item (um cliente).","fundamento":"Intervalo de predição x de confiança.","macete":"Indivíduo: ± z·σ; média: ± z·σ/√n.","erroComum":"Usar σ/√n para um indivíduo.","comoBancaPensa":"Indivíduo x média."}},"ES-609":{"cognitivo":{"motivo":"Reconhecer o ponto: cauda do intervalo.","palavraCritica":"2,5%"},"comentario":{"resolucao":"CERTO. Num IC simétrico de 95% com variância conhecida, a probabilidade de o intervalo ficar inteiramente abaixo de μ (μ > x̄ + ε) é a cauda superior: 2,5%.","fundamento":"IC bilateral.","macete":"Cada lado: α/2.","erroComum":"Usar 5%.","comoBancaPensa":"Caudas."}},"ES-610":{"cognitivo":{"motivo":"Reconhecer o ponto: n menor, intervalo maior.","palavraCritica":"maior será a amplitude"},"comentario":{"resolucao":"CERTO. A semiamplitude é z·σ/√n: menos observações, maior a amplitude.","fundamento":"IC.","macete":"Amplitude ∝ 1/√n.","erroComum":"Inverter.","comoBancaPensa":"Conceito."}},"ES-611":{"cognitivo":{"motivo":"Reconhecer o ponto: amplitude do IC.","palavraCritica":"amplitude de 1,176"},"comentario":{"resolucao":"ERRADO. Semiamplitude = 1,96 × 75/√250 ≈ 9,3; amplitude ≈ 18,6 ciclos, não 1,176.","fundamento":"IC.","macete":"2·z·σ/√n.","erroComum":"Errar a raiz.","comoBancaPensa":"Cálculo."}},"ES-612":{"cognitivo":{"motivo":"Reconhecer o ponto: afirmação sem base.","palavraCritica":"Em 20 das 250 baterias"},"comentario":{"resolucao":"ERRADO. O intervalo de confiança refere-se à média populacional; não permite afirmar quantas baterias individuais terão mais de 653 ciclos.","fundamento":"Interpretação do IC.","macete":"IC é sobre a média, não sobre indivíduos.","erroComum":"Aplicar a indivíduos.","comoBancaPensa":"Interpretação."}},"ES-613":{"cognitivo":{"motivo":"Reconhecer o ponto: limite inferior.","palavraCritica":"548 ciclos"},"comentario":{"resolucao":"CERTO. Limite inferior ≈ 650 − 9,3 = 640,7, bem acima de 548.","fundamento":"IC.","macete":"x̄ − margem.","erroComum":"Errar a margem.","comoBancaPensa":"Conta."}},"ES-614":{"cognitivo":{"motivo":"Reconhecer o ponto: σ desconhecido com n grande.","palavraCritica":"desvio padrão"},"comentario":{"resolucao":"CERTO. Sem σ, usa-se o desvio padrão amostral das 250 baterias (com t, ou z pela amostra grande).","fundamento":"IC com σ desconhecido.","macete":"Substitua σ por s.","erroComum":"Achar que não dá.","comoBancaPensa":"Conceito."}},"ES-615":{"cognitivo":{"motivo":"Reconhecer o ponto: amostra voluntária.","palavraCritica":"existe um nível de confiança"},"comentario":{"resolucao":"ERRADO. Com resposta voluntária e cadastro falho, a amostra não é probabilística: não há base para associar nível de confiança e margem de erro ao resultado de 68%.","fundamento":"Inferência e amostragem.","macete":"Sem amostra probabilística, não há IC válido.","erroComum":"Calcular IC mesmo assim.","comoBancaPensa":"Conceito."}},"ES-616":{"cognitivo":{"motivo":"Reconhecer o ponto: margem de erro.","palavraCritica":"10 dias ± 6 dias"},"comentario":{"resolucao":"ERRADO. Margem = 2 × 3/√100 = 0,6 dia: IC = 10 ± 0,6, não ± 6.","fundamento":"IC.","macete":"Divida por √n.","erroComum":"Esquecer o √n.","comoBancaPensa":"Erro clássico."}},"ES-617":{"cognitivo":{"motivo":"Reconhecer o ponto: efeito de multiplicar n.","palavraCritica":"reduzida à metade"},"comentario":{"resolucao":"ERRADO. Largura ∝ 1/√n. Multiplicando n por 100, a largura cai para 1/10, não para a metade (para a metade, n teria de ser multiplicado por 4).","fundamento":"IC.","macete":"√100 = 10.","erroComum":"Achar linear.","comoBancaPensa":"Proporção."}},"ES-618":{"cognitivo":{"motivo":"Reconhecer o ponto: tamanho para proporção.","palavraCritica":"inferior a 160"},"comentario":{"resolucao":"ERRADO. n = z²p(1 − p)/e² = 0,615/0,0025 = 246 contratos (sem correção de população finita), não inferior a 160.","fundamento":"Tamanho de amostra.","macete":"n = z²pq/e².","erroComum":"Errar o e².","comoBancaPensa":"Cálculo."}},"ES-619":{"cognitivo":{"motivo":"Reconhecer o ponto: erro amostral de proporção.","palavraCritica":"superior a 10%"},"comentario":{"resolucao":"ERRADO. Com p̂ = 0,9 e n = 100, o erro padrão é √(0,09/100) = 3%; mesmo a 95% (1,96 × 3% ≈ 5,9%), o erro não supera 10%.","fundamento":"Erro de proporção.","macete":"√(pq/n).","erroComum":"Usar 1 − p como erro.","comoBancaPensa":"Conta."}},"ES-620":{"cognitivo":{"motivo":"Reconhecer o ponto: quantil errado.","palavraCritica":"Φ−1(0,95)"},"comentario":{"resolucao":"ERRADO. Para 95% de confiança bilateral, usa-se Φ⁻¹(0,975) = 1,96. Com Φ⁻¹(0,95) = 1,645, o intervalo seria de 90%.","fundamento":"IC para proporção.","macete":"95% bilateral → 0,975.","erroComum":"Usar 0,95.","comoBancaPensa":"Quantil."}},"ES-621":{"cognitivo":{"motivo":"Reconhecer o ponto: margem de erro.","palavraCritica":"inferior a 0,07"},"comentario":{"resolucao":"CERTO. ε = 1,96 × √(0,21/200) ≈ 1,96 × 0,0324 ≈ 0,0635, inferior a 0,07.","fundamento":"IC para proporção.","macete":"z·√(pq/n).","erroComum":"Errar a raiz.","comoBancaPensa":"Limite próximo."}},"ES-622":{"cognitivo":{"motivo":"Reconhecer o ponto: média e desvio a partir do IC.","palavraCritica":"11 e 2"},"comentario":{"resolucao":"CERTO. Centro do IC = 11 (média). Semiamplitude 0,5 = 2 × s/√64 ⇒ s = 2.","fundamento":"IC com t.","macete":"Centro = média; margem = t·s/√n.","erroComum":"Errar o √n.","comoBancaPensa":"Engenharia reversa."}},"ES-623":{"cognitivo":{"motivo":"Reconhecer o ponto: erro padrão a partir do IC.","palavraCritica":"igual a 0,5"},"comentario":{"resolucao":"ERRADO. 0,5 é a semiamplitude (margem). O erro padrão é 0,5/2 = 0,25.","fundamento":"Erro padrão.","macete":"Margem = t × EP.","erroComum":"Confundir margem com EP.","comoBancaPensa":"Troca de conceito."}},"ES-624":{"cognitivo":{"motivo":"Reconhecer o ponto: iC de diferenças pareadas.","palavraCritica":"R$ 0,5 mil"},"comentario":{"resolucao":"ERRADO. Erro padrão = 3/√36 = 0,5 mil; com t ≈ 2,03 (35 gl), a margem é ≈ 1,0 mil. O IC seria R$ 5 mil ± R$ 1 mil, não ± 0,5 mil (que é só o erro padrão).","fundamento":"IC.","macete":"Margem = t × EP.","erroComum":"Usar o EP como margem.","comoBancaPensa":"Troca de conceito."}},"ES-625":{"cognitivo":{"motivo":"Reconhecer o ponto: confiança maior, intervalo maior.","palavraCritica":"inferior a 3"},"comentario":{"resolucao":"ERRADO. Aumentar a confiança de 95% para 99,9% exige z maior (≈ 3,29 em vez de 1,96): ε fica maior que 3.","fundamento":"IC.","macete":"Mais confiança, mais largura.","erroComum":"Inverter.","comoBancaPensa":"Inversão."}},"ES-626":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão a partir da margem.","palavraCritica":"desvio padrão igual a 3"},"comentario":{"resolucao":"ERRADO. 3 = 1,96 × σ/√400 = 1,96 × σ/20 ⇒ σ ≈ 30,6. 3 é a margem, não o desvio padrão.","fundamento":"IC.","macete":"Margem = z·σ/√n.","erroComum":"Igualar margem e σ.","comoBancaPensa":"Troca de conceito."}},"ES-627":{"cognitivo":{"motivo":"Reconhecer o ponto: intervalo em torno de zero.","palavraCritica":"amplitude"},"comentario":{"resolucao":"CERTO. Se as médias forem iguais, o IC da diferença fica centrado perto de zero (ex.: [−2; 3]); a amplitude (5) supera o limite superior (3).","fundamento":"IC para diferença.","macete":"Intervalo com extremos de sinais opostos.","erroComum":"Achar impossível.","comoBancaPensa":"Conceito."}},"ES-628":{"cognitivo":{"motivo":"Reconhecer o ponto: interpretação frequentista.","palavraCritica":"cerca de 95%"},"comentario":{"resolucao":"CERTO. A confiança de 95% significa que, repetindo o procedimento muitas vezes, cerca de 95% dos intervalos conterão o parâmetro.","fundamento":"Interpretação do IC.","macete":"Confiança é do método.","erroComum":"Falar em probabilidade do parâmetro.","comoBancaPensa":"Conceito."}},"ES-629":{"cognitivo":{"motivo":"Reconhecer o ponto: tamanho mínimo.","palavraCritica":"inferior a 50"},"comentario":{"resolucao":"ERRADO. n = (1,96 × 8/2)² = 7,84² ≈ 61,5 ⇒ 62. Não é inferior a 50.","fundamento":"Tamanho de amostra.","macete":"n = (zσ/e)².","erroComum":"Esquecer o quadrado.","comoBancaPensa":"Cálculo."}},"ES-630":{"cognitivo":{"motivo":"Reconhecer o ponto: menor confiança, menor amostra.","palavraCritica":"diminuiria"},"comentario":{"resolucao":"CERTO. Reduzir a confiança reduz z e, portanto, o tamanho mínimo de amostra (aqui, o número mínimo de meses observados).","fundamento":"Tamanho de amostra.","macete":"n ∝ z².","erroComum":"Inverter.","comoBancaPensa":"Conceito."}},"ES-631":{"cognitivo":{"motivo":"Reconhecer o ponto: erro pela metade.","palavraCritica":"duplicaria"},"comentario":{"resolucao":"ERRADO. n ∝ 1/e²: com o erro pela metade, n quadruplica, não duplica.","fundamento":"Tamanho de amostra.","macete":"Metade do erro = 4 vezes n.","erroComum":"Achar linear.","comoBancaPensa":"Proporção."}},"ES-632":{"cognitivo":{"motivo":"Reconhecer o ponto: iC com variância conhecida.","palavraCritica":"[52,525; 57,475]"},"comentario":{"resolucao":"ERRADO. Erro padrão = √18/√144 ≈ 0,354; margem = 1,96 × 0,354 ≈ 0,69. IC ≈ [54,31; 55,69], não [52,525; 57,475].","fundamento":"IC.","macete":"√(Var/n).","erroComum":"Esquecer o √n.","comoBancaPensa":"Cálculo."}},"ES-633":{"cognitivo":{"motivo":"Reconhecer o ponto: iC com σ conhecido.","palavraCritica":"[1.902, 2.098]"},"comentario":{"resolucao":"CERTO. 2.000 ± 1,96 × 500/√100 = 2.000 ± 98 ⇒ [1.902; 2.098].","fundamento":"IC.","macete":"x̄ ± z·σ/√n.","erroComum":"Errar a conta.","comoBancaPensa":"Conta direta."}},"ES-634":{"cognitivo":{"motivo":"Reconhecer o ponto: iC com t a partir de somas.","palavraCritica":"menor que 4"},"comentario":{"resolucao":"CERTO. Média = 90/20 = 4,5. s² = (460 − 20 × 4,5²)/19 = 55/19 ≈ 2,89; s ≈ 1,70. Margem = 2,093 × 1,70/√20 ≈ 0,80. IC ≈ [3,70; 5,30]: limite inferior < 4 e superior > 5.","fundamento":"IC com t.","macete":"Use n − 1 = 19 gl.","erroComum":"Usar z.","comoBancaPensa":"Cálculo."}},"ES-635":{"cognitivo":{"motivo":"Reconhecer o ponto: estimativa pontual.","palavraCritica":"igual a 25"},"comentario":{"resolucao":"CERTO. Num IC simétrico, a estimativa pontual é o centro: (22,5 + 27,5)/2 = 25.","fundamento":"Estimação pontual.","macete":"Centro do intervalo.","erroComum":"Confundir.","comoBancaPensa":"Conta direta."}},"ES-636":{"cognitivo":{"motivo":"Reconhecer o ponto: fórmula do IC.","palavraCritica":"Var"},"comentario":{"resolucao":"ERRADO. O IC com t usa o erro padrão, isto é, a RAIZ da variância estimada da média: x̄ ± t·√Var(x̄) = x̄ ± t·s/√n. A fórmula com Var(x̄) não está correta.","fundamento":"IC com t.","macete":"Use o desvio, não a variância.","erroComum":"Esquecer a raiz.","comoBancaPensa":"Fórmula."}},"ES-637":{"cognitivo":{"motivo":"Reconhecer o ponto: iC com σ conhecido.","palavraCritica":"5 ± 0,784"},"comentario":{"resolucao":"CERTO. 1,96 × 4/√100 = 0,784: IC = 5 ± 0,784.","fundamento":"IC.","macete":"x̄ ± z·σ/√n.","erroComum":"Usar a variância 16.","comoBancaPensa":"Conta."}},"ES-638":{"cognitivo":{"motivo":"Reconhecer o ponto: esquecer o erro padrão.","palavraCritica":"38 ± 1,7"},"comentario":{"resolucao":"ERRADO. EP = √(750/30) = 5; margem = 1,7 × 5 = 8,5. O IC de 90% é 38 ± 8,5, não 38 ± 1,7.","fundamento":"IC com t.","macete":"Margem = t × EP.","erroComum":"Usar só o t.","comoBancaPensa":"Esquece o EP."}},"ES-639":{"cognitivo":{"motivo":"Reconhecer o ponto: confundir nível com margem.","palavraCritica":"± 0,95"},"comentario":{"resolucao":"ERRADO. EP = 12/√144 = 1; o IC de 95% é x̄ ± 1,96, não ± 0,95.","fundamento":"IC.","macete":"Margem = z × EP.","erroComum":"Usar 0,95 como margem.","comoBancaPensa":"Confusão."}},"ES-640":{"cognitivo":{"motivo":"Reconhecer o ponto: nível de confiança errado.","palavraCritica":"97,7%"},"comentario":{"resolucao":"ERRADO. EP = 1/√100 = 0,1. 10 ± 2 corresponde a ± 20 erros padrão (confiança praticamente 100%). E mesmo 10 ± 0,2 (z = 2) teria confiança 2 × 0,977 − 1 = 95,4%, não 97,7%.","fundamento":"IC.","macete":"Confiança bilateral = 2Φ(z) − 1.","erroComum":"Usar Φ(z) direto.","comoBancaPensa":"Dois erros."}},"ES-641":{"cognitivo":{"motivo":"Reconhecer o ponto: valor fora do intervalo.","palavraCritica":"igual a 49"},"comentario":{"resolucao":"ERRADO. IC de 95% = 60 ± 1,96 × 25/6 ≈ 60 ± 8,2 ⇒ [51,8; 68,2]. 49 está fora: não é plausível com 95% de confiança.","fundamento":"IC.","macete":"Monte o intervalo e verifique.","erroComum":"Errar o EP.","comoBancaPensa":"Cálculo."}},"ES-642":{"cognitivo":{"motivo":"Reconhecer o ponto: nível a partir do intervalo.","palavraCritica":"95%"},"comentario":{"resolucao":"CERTO. Semiamplitude = 82,84 − 75 = 7,84 = z × 4 ⇒ z = 1,96: confiança de 95%.","fundamento":"IC.","macete":"z = margem/EP.","erroComum":"Errar a conta.","comoBancaPensa":"Engenharia reversa."}},"ES-643":{"cognitivo":{"motivo":"Reconhecer o ponto: margem com n grande.","palavraCritica":"[20 −2; 20 + 2]"},"comentario":{"resolucao":"ERRADO. EP = 2/√400 = 0,1; margem = 2 × 0,1 = 0,2. IC = [19,8; 20,2], não [18; 22].","fundamento":"IC.","macete":"Divida por √n.","erroComum":"Usar o desvio padrão.","comoBancaPensa":"Erro clássico."}},"ES-644":{"cognitivo":{"motivo":"Reconhecer o ponto: n ∝ 1/e².","palavraCritica":"inversamente proporcional"},"comentario":{"resolucao":"ERRADO. O tamanho de amostra para proporções é n = z²p(1 − p)/e²: inversamente proporcional ao QUADRADO do erro, não ao erro.","fundamento":"Tamanho de amostra.","macete":"Metade do erro = 4 vezes a amostra.","erroComum":"Achar linear.","comoBancaPensa":"Proporção errada."}},"ES-645":{"cognitivo":{"motivo":"Reconhecer o ponto: tamanho do IC de proporção.","palavraCritica":"inferior a 0,12"},"comentario":{"resolucao":"CERTO. Notas ≥ 6: 26 + 38 = 64 de 256 ⇒ p̂ = 0,25. EP = √(0,25 × 0,75/256) ≈ 0,0271. Tamanho do IC de 90% = 2 × 1,65 × 0,0271 ≈ 0,089, inferior a 0,12.","fundamento":"IC para proporção.","macete":"Some as classes pedidas.","erroComum":"Errar p̂.","comoBancaPensa":"Cálculo."}},"ES-646":{"cognitivo":{"motivo":"Reconhecer o ponto: erro amostral.","palavraCritica":"5%"},"comentario":{"resolucao":"CERTO. Semiamplitude de [0,25; 0,35] = 0,05 = 5%.","fundamento":"IC.","macete":"Margem = metade da largura.","erroComum":"Usar a largura toda.","comoBancaPensa":"Conta direta."}},"ES-647":{"cognitivo":{"motivo":"Reconhecer o ponto: tamanho conservador.","palavraCritica":"superior a 400"},"comentario":{"resolucao":"ERRADO. Sem informação, usa-se p = 0,5: n = 1,96² × 0,25/0,05² ≈ 384,2 ⇒ 385 pessoas, não mais de 400.","fundamento":"Tamanho de amostra.","macete":"Pior caso p = 0,5.","erroComum":"Arredondar z para 2 (dá 400).","comoBancaPensa":"Limite próximo."}},"ES-648":{"cognitivo":{"motivo":"Reconhecer o ponto: iC para proporção.","palavraCritica":"0,25 ± 0,05"},"comentario":{"resolucao":"ERRADO. EP = √(0,25 × 0,75/1.875) = 0,01; margem = 2 × 0,01 = 0,02. IC = 0,25 ± 0,02, não ± 0,05.","fundamento":"IC para proporção.","macete":"z·√(pq/n).","erroComum":"Errar o EP.","comoBancaPensa":"Cálculo."}},"ES-649":{"cognitivo":{"motivo":"Reconhecer o ponto: moldura incompleta.","palavraCritica":"igual probabilidade"},"comentario":{"resolucao":"ERRADO. Os números sorteados vão de 1 a 10.000, mas o total de motoristas do dia é desconhecido (cerca de dez mil) e os números posteriores às 22 h são descartados: quem chegar além do 10.000.º ou depois das 22 h não tem chance. A igualdade de probabilidades não está garantida.","fundamento":"Amostragem aleatória simples.","macete":"Moldura (lista) precisa cobrir toda a população.","erroComum":"Ignorar a moldura.","comoBancaPensa":"Termo absoluto."}},"ES-650":{"cognitivo":{"motivo":"Reconhecer o ponto: plano II não é AAS pura.","palavraCritica":"não pode ser classificada"},"comentario":{"resolucao":"CERTO. Como a lista de 1 a 10.000 não coincide com a população do dia (pode sobrar ou faltar motorista, e números excedentes são descartados), nem todas as amostras de 460 motoristas têm a mesma probabilidade: não é amostra aleatória simples.","fundamento":"AAS.","macete":"AAS: todas as amostras equiprováveis.","erroComum":"Ver sorteio e concluir AAS.","comoBancaPensa":"Detalhe da moldura."}},"ES-651":{"cognitivo":{"motivo":"Reconhecer o ponto: classes prévias = estratos.","palavraCritica":"estratificada"},"comentario":{"resolucao":"CERTO. O plano III divide os veículos em classes (premium, grandes e pequenos) e sorteia dentro de cada uma, com alocação proporcional: características de amostragem estratificada.","fundamento":"Amostragem estratificada.","macete":"Classes + sorteio em cada classe = estratos.","erroComum":"Confundir com cotas.","comoBancaPensa":"Conceito."}},"ES-652":{"cognitivo":{"motivo":"Reconhecer o ponto: um a cada dez = sistemática.","palavraCritica":"sistemática"},"comentario":{"resolucao":"CERTO. Entrevistar o primeiro e depois sempre o décimo seguinte é seleção a intervalo fixo: amostragem sistemática.","fundamento":"Amostragem sistemática.","macete":"Intervalo fixo = sistemática.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-653":{"cognitivo":{"motivo":"Reconhecer o ponto: setores com sorteio interno.","palavraCritica":"conglomerados"},"comentario":{"resolucao":"ERRADO. No plano IV, o estacionamento é dividido em setores e há sorteio de automóveis DENTRO de cada setor: isso é estratificação. Em conglomerados, sorteiam-se grupos inteiros.","fundamento":"Estratificada x conglomerados.","macete":"Sorteio em todos os grupos = estratos.","erroComum":"Confundir.","comoBancaPensa":"Troca de conceito."}},"ES-654":{"cognitivo":{"motivo":"Reconhecer o ponto: unidade amostral.","palavraCritica":"unidade amostral"},"comentario":{"resolucao":"ERRADO. A unidade amostral é o contrato (o que é sorteado e examinado). A abrangência define os estratos.","fundamento":"Unidade amostral.","macete":"Unidade = o que se sorteia.","erroComum":"Confundir estrato com unidade.","comoBancaPensa":"Conceito."}},"ES-655":{"cognitivo":{"motivo":"Reconhecer o ponto: fração amostral.","palavraCritica":"igual a 0,1"},"comentario":{"resolucao":"CERTO. 200/2.000 = 0,1.","fundamento":"Fração amostral.","macete":"n/N.","erroComum":"Inverter.","comoBancaPensa":"Conta direta."}},"ES-656":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidades iguais por estrato.","palavraCritica":"superior"},"comentario":{"resolucao":"ERRADO. Local: 80/800 = 0,1; nacional: 50/500 = 0,1. As probabilidades de seleção são iguais.","fundamento":"Alocação proporcional.","macete":"Compare n_h/N_h.","erroComum":"Comparar só n_h.","comoBancaPensa":"Conta."}},"ES-657":{"cognitivo":{"motivo":"Reconhecer o ponto: alocação proporcional.","palavraCritica":"proporcional"},"comentario":{"resolucao":"CERTO. Cada estrato recebe 10% de seus contratos (80, 70 e 50): alocação proporcional ao tamanho.","fundamento":"Alocação proporcional.","macete":"Mesma fração em todos os estratos.","erroComum":"Confundir com uniforme.","comoBancaPensa":"Conceito."}},"ES-658":{"cognitivo":{"motivo":"Reconhecer o ponto: estratos x conglomerados.","palavraCritica":"conglomerados"},"comentario":{"resolucao":"ERRADO. Os três grupos de abrangência são estratos (sorteia-se dentro de todos eles), e não conglomerados.","fundamento":"Estratificada.","macete":"Sorteio dentro de cada grupo = estrato.","erroComum":"Confundir.","comoBancaPensa":"Troca de conceito."}},"ES-659":{"cognitivo":{"motivo":"Reconhecer o ponto: eficiência amostral.","palavraCritica":"eficiência amostral"},"comentario":{"resolucao":"ERRADO, segundo a banca. A eficiência amostral (relação entre custo e precisão) é um conceito associado aos planos probabilísticos, nos quais a precisão pode ser medida; em amostras não probabilísticas não há como avaliar a precisão.","fundamento":"Amostragem não probabilística.","macete":"Sem probabilidade, sem medida de precisão.","erroComum":"Aplicar conceito de eficiência.","comoBancaPensa":"Conceito."}},"ES-660":{"cognitivo":{"motivo":"Reconhecer o ponto: alocação proporcional (visão da banca).","palavraCritica":"deve ser proporcional"},"comentario":{"resolucao":"CERTO, segundo o gabarito. A banca tomou como referência a alocação proporcional, a mais usual. Observação: existem outras alocações legítimas (uniforme, ótima de Neyman), de modo que a proporcionalidade não é obrigatória em toda amostra estratificada.","fundamento":"Alocação na estratificação.","macete":"Proporcional é a alocação padrão.","erroComum":"Esquecer as outras alocações.","comoBancaPensa":"Afirmação forte."}},"ES-661":{"cognitivo":{"motivo":"Reconhecer o ponto: sistemática exige lista.","palavraCritica":"listagem"},"comentario":{"resolucao":"CERTO. A amostragem sistemática percorre uma listagem ordenada das unidades, selecionando a intervalos fixos.","fundamento":"Sistemática.","macete":"Precisa de lista ordenada.","erroComum":"Achar dispensável.","comoBancaPensa":"Conceito."}},"ES-662":{"cognitivo":{"motivo":"Reconhecer o ponto: conglomerados em um ou dois estágios.","palavraCritica":"conglomerados"},"comentario":{"resolucao":"CERTO. Sorteiam-se grupos naturais (conglomerados) e, dentro dos sorteados, faz-se censo (um estágio) ou nova amostragem (dois estágios).","fundamento":"Conglomerados.","macete":"Sorteia grupos inteiros.","erroComum":"Confundir com estratos.","comoBancaPensa":"Conceito."}},"ES-663":{"cognitivo":{"motivo":"Reconhecer o ponto: homogeneidade interna prejudica.","palavraCritica":"sempre produz estimativas mais precisas"},"comentario":{"resolucao":"ERRADO. Conglomerados internamente homogêneos e diferentes entre si tornam a amostragem por conglomerados MENOS precisa: cada grupo traz pouca informação nova. O ideal é o contrário.","fundamento":"Conglomerados.","macete":"Conglomerado bom = mini-população heterogênea.","erroComum":"Inverter com estratos.","comoBancaPensa":"Inverte."}},"ES-664":{"cognitivo":{"motivo":"Reconhecer o ponto: conglomerados heterogêneos.","palavraCritica":"heterogeneidade"},"comentario":{"resolucao":"CERTO. Em conglomerados, deseja-se que cada grupo seja uma miniatura da população, isto é, heterogêneo internamente.","fundamento":"Conglomerados.","macete":"Interno heterogêneo; entre grupos parecidos.","erroComum":"Confundir com estratos.","comoBancaPensa":"Conceito."}},"ES-665":{"cognitivo":{"motivo":"Reconhecer o ponto: dois estágios.","palavraCritica":"dois estágios"},"comentario":{"resolucao":"CERTO. Sorteiam-se departamentos (1.º estágio) e, em cada um, uma amostra de pessoas (2.º estágio).","fundamento":"Conglomerados em dois estágios.","macete":"Grupo + subamostra = dois estágios.","erroComum":"Chamar de estratificada.","comoBancaPensa":"Conceito."}},"ES-666":{"cognitivo":{"motivo":"Reconhecer o ponto: definição de AAS.","palavraCritica":"mesma probabilidade"},"comentario":{"resolucao":"CERTO. Na AAS, toda amostra de tamanho n tem a mesma probabilidade de ser escolhida.","fundamento":"AAS.","macete":"Todas as amostras equiprováveis.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-667":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade de inclusão.","palavraCritica":"1/1.000"},"comentario":{"resolucao":"ERRADO. Na AAS de n = 100 em N = 1.000, a probabilidade de inclusão de cada servidor é n/N = 0,1, não 1/1.000.","fundamento":"AAS.","macete":"Inclusão = n/N.","erroComum":"Usar 1/N.","comoBancaPensa":"Erro clássico."}},"ES-668":{"cognitivo":{"motivo":"Reconhecer o ponto: elementos do mesmo conglomerado.","palavraCritica":"independentes"},"comentario":{"resolucao":"ERRADO. Os elementos 6 e 7 estão no mesmo conglomerado (II): ou entram juntos ou ficam juntos de fora. Os eventos são totalmente dependentes.","fundamento":"Conglomerados.","macete":"Mesmo grupo, mesmo destino.","erroComum":"Supor independência.","comoBancaPensa":"Conceito."}},"ES-669":{"cognitivo":{"motivo":"Reconhecer o ponto: inclusão do conglomerado inteiro.","palavraCritica":"igual a 1"},"comentario":{"resolucao":"CERTO. Se o 12 está na amostra, o conglomerado III foi sorteado e todos os seus elementos entram, inclusive o 9: probabilidade 1.","fundamento":"Conglomerados.","macete":"Sorteou o grupo, entram todos.","erroComum":"Calcular sem condicionar.","comoBancaPensa":"Condicional."}},"ES-670":{"cognitivo":{"motivo":"Reconhecer o ponto: amostra de conglomerados.","palavraCritica":"exatamente por dois elementos"},"comentario":{"resolucao":"ERRADO. n = 2 refere-se a dois CONGLOMERADOS, com todos os seus elementos. {13, 17} mistura elementos de grupos diferentes e não é uma amostra possível.","fundamento":"Conglomerados.","macete":"Tamanho conta grupos.","erroComum":"Contar elementos.","comoBancaPensa":"Conceito."}},"ES-671":{"cognitivo":{"motivo":"Reconhecer o ponto: domicílio como conglomerado.","palavraCritica":"conglomerado de pessoas"},"comentario":{"resolucao":"CERTO. Seleciona-se o domicílio, mas as características investigadas são das pessoas: cada domicílio é um conglomerado de pessoas.","fundamento":"Conglomerados.","macete":"Seleciona grupo, mede indivíduos.","erroComum":"Confundir com AAS de pessoas.","comoBancaPensa":"Conceito."}},"ES-672":{"cognitivo":{"motivo":"Reconhecer o ponto: um ou dois estágios.","palavraCritica":"em 1 estágio"},"comentario":{"resolucao":"ERRADO. Entrevistar todos os moradores é conglomerado em um estágio; entrevistar só uma amostra deles é conglomerado em dois estágios. As duas situações não são equivalentes.","fundamento":"Conglomerados.","macete":"Subamostra dentro do grupo = 2.º estágio.","erroComum":"Igualar.","comoBancaPensa":"Mistura."}},"ES-673":{"cognitivo":{"motivo":"Reconhecer o ponto: ordem do cálculo em dois estágios.","palavraCritica":"não existe diferença"},"comentario":{"resolucao":"ERRADO. Em dois estágios, o tamanho é planejado primeiro para as unidades primárias (conglomerados) e depois para as secundárias; a ordem e os componentes de variância de cada estágio importam.","fundamento":"Conglomerados em dois estágios.","macete":"Primeiro as unidades primárias.","erroComum":"Achar indiferente.","comoBancaPensa":"Conceito."}},"ES-674":{"cognitivo":{"motivo":"Reconhecer o ponto: tamanho x variabilidade.","palavraCritica":"maiores variabilidades"},"comentario":{"resolucao":"ERRADO. Pela tabela, o maior estrato (B, 10 elementos) tem o menor desvio padrão (3) e o menor (C, 4 elementos) o maior (10). Não há tal tendência.","fundamento":"Estratificação.","macete":"Confira os dados.","erroComum":"Generalizar.","comoBancaPensa":"Contradição com os dados."}},"ES-675":{"cognitivo":{"motivo":"Reconhecer o ponto: alocação de Neyman.","palavraCritica":"três elementos do estrato A"},"comentario":{"resolucao":"CERTO. Neyman: n_h ∝ N_h·σ_h. A: 6 × 5 = 30; B: 10 × 3 = 30; C: 4 × 10 = 40 (total 100). Com n = 10: 3, 3 e 4.","fundamento":"Alocação ótima de Neyman.","macete":"n_h ∝ N_h·σ_h.","erroComum":"Usar só N_h.","comoBancaPensa":"Cálculo."}},"ES-676":{"cognitivo":{"motivo":"Reconhecer o ponto: probabilidade numa alocação uniforme.","palavraCritica":"igual a 0,25"},"comentario":{"resolucao":"ERRADO. Uniforme com n = 6: 2 elementos por estrato. No estrato C (4 elementos), há C(4, 2) = 6 pares possíveis: P({17, 18}) = 1/6 ≈ 0,167, não 0,25.","fundamento":"Estratificada.","macete":"Pares possíveis no estrato.","erroComum":"Usar 2/4 × ...","comoBancaPensa":"Cálculo."}},"ES-677":{"cognitivo":{"motivo":"Reconhecer o ponto: evento impossível.","palavraCritica":"igual a zero"},"comentario":{"resolucao":"CERTO. Com n = 5 proporcional (6/20, 10/20, 4/20), o estrato A recebe 1,5 → 1 ou 2 elementos. Os elementos 1, 5 e 6 são todos de A; três deles nunca entram juntos: probabilidade zero.","fundamento":"Alocação proporcional.","macete":"Veja quantos cabem no estrato.","erroComum":"Calcular sem checar.","comoBancaPensa":"Raciocínio."}},"ES-678":{"cognitivo":{"motivo":"Reconhecer o ponto: fração amostral.","palavraCritica":"inferior a 0,01"},"comentario":{"resolucao":"ERRADO. 100/1.000 = 0,1, não inferior a 0,01.","fundamento":"Fração amostral.","macete":"n/N.","erroComum":"Erro de casa decimal.","comoBancaPensa":"Conta direta."}},"ES-679":{"cognitivo":{"motivo":"Reconhecer o ponto: neyman com tamanhos diferentes.","palavraCritica":"n1 = 200"},"comentario":{"resolucao":"CERTO. N_h·σ_h: I = 250.000; II = 250.000; III = 750.000 (total 1.250.000). n_h = 1.000 × N_hσ_h/1.250.000: 200, 200 e 600.","fundamento":"Alocação de Neyman.","macete":"n_h ∝ N_h·σ_h.","erroComum":"Usar só σ.","comoBancaPensa":"Cálculo."}},"ES-680":{"cognitivo":{"motivo":"Reconhecer o ponto: proporcional.","palavraCritica":"n1 < n2 < n3"},"comentario":{"resolucao":"ERRADO. Proporcional: n1 = 500, n2 = 250, n3 = 250. Logo n1 > n2 = n3.","fundamento":"Alocação proporcional.","macete":"n_h = n·N_h/N.","erroComum":"Confundir com Neyman.","comoBancaPensa":"Troca de alocação."}},"ES-681":{"cognitivo":{"motivo":"Reconhecer o ponto: cotas não são probabilísticas.","palavraCritica":"amostragem probabilística"},"comentario":{"resolucao":"ERRADO. A sistemática é probabilística (com início aleatório), mas a amostragem por cotas é não probabilística.","fundamento":"Tipos de amostragem.","macete":"Cotas = escolha do entrevistador.","erroComum":"Confundir cotas com estratos.","comoBancaPensa":"Mistura."}},"ES-682":{"cognitivo":{"motivo":"Reconhecer o ponto: unidade amostral.","palavraCritica":"cada estudante"},"comentario":{"resolucao":"CERTO. Os estudantes são sorteados e entrevistados em cada curso: cada estudante é uma unidade amostral.","fundamento":"Unidade amostral.","macete":"Unidade = quem é sorteado.","erroComum":"Achar que é o curso.","comoBancaPensa":"Conceito."}},"ES-683":{"cognitivo":{"motivo":"Reconhecer o ponto: estratificada, não AAS.","palavraCritica":"aleatória simples"},"comentario":{"resolucao":"ERRADO. A amostra foi tomada separadamente em cada curso (estratos), com tamanhos fixados: amostragem estratificada.","fundamento":"Estratificada.","macete":"Amostra por grupo = estratos.","erroComum":"Chamar de AAS.","comoBancaPensa":"Troca."}},"ES-684":{"cognitivo":{"motivo":"Reconhecer o ponto: sem reposição: dependência.","palavraCritica":"mutuamente independentes"},"comentario":{"resolucao":"ERRADO. Sem reposição, cada retirada altera as possibilidades das seguintes: as variáveis não são independentes (com reposição, seriam).","fundamento":"AAS sem reposição.","macete":"Sem reposição ⇒ dependência.","erroComum":"Supor independência.","comoBancaPensa":"Conceito."}},"ES-685":{"cognitivo":{"motivo":"Reconhecer o ponto: equipes sorteadas = conglomerados.","palavraCritica":"aleatória simples"},"comentario":{"resolucao":"ERRADO. Sortearam-se equipes e entrevistaram-se todos os seus membros: amostragem por conglomerados, não AAS de funcionários.","fundamento":"Conglomerados.","macete":"Grupo inteiro = conglomerado.","erroComum":"Chamar de AAS.","comoBancaPensa":"Troca."}},"ES-686":{"cognitivo":{"motivo":"Reconhecer o ponto: unidade = equipe.","palavraCritica":"260 funcionários"},"comentario":{"resolucao":"ERRADO. A unidade amostral é a equipe (conglomerado sorteado); o tamanho da amostra é 50 equipes. Os 260 funcionários são as unidades de observação.","fundamento":"Unidade amostral.","macete":"Unidade = o sorteado.","erroComum":"Contar pessoas.","comoBancaPensa":"Confusão."}},"ES-687":{"cognitivo":{"motivo":"Reconhecer o ponto: alocação proporcional.","palavraCritica":"n1 = n2 = 25"},"comentario":{"resolucao":"CERTO. N = 200: n1 = 100 × 50/200 = 25; n2 = 25; n3 = 100 × 100/200 = 50.","fundamento":"Alocação proporcional.","macete":"n·N_h/N.","erroComum":"Usar N_h·s_h (Neyman).","comoBancaPensa":"Conta."}},"ES-688":{"cognitivo":{"motivo":"Reconhecer o ponto: múltiplos de 10.","palavraCritica":"sistemática"},"comentario":{"resolucao":"CERTO. Selecionar as senhas múltiplas de 10 (intervalo fixo) é amostragem sistemática.","fundamento":"Sistemática.","macete":"Intervalo fixo.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-689":{"cognitivo":{"motivo":"Reconhecer o ponto: domicílios com todos os moradores.","palavraCritica":"conglomerados"},"comentario":{"resolucao":"CERTO. Sortearam-se domicílios e entrevistaram-se todos os adultos: amostragem por conglomerados, com o domicílio como unidade amostral.","fundamento":"Conglomerados.","macete":"Grupo inteiro = conglomerado.","erroComum":"Chamar de AAS.","comoBancaPensa":"Conceito."}},"ES-690":{"cognitivo":{"motivo":"Reconhecer o ponto: tamanho e precisão.","palavraCritica":"mais precisas"},"comentario":{"resolucao":"CERTO. Com amostras maiores, o erro padrão diminui e as estimativas ficam mais precisas.","fundamento":"Tamanho da amostra.","macete":"EP ∝ 1/√n.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-691":{"cognitivo":{"motivo":"Reconhecer o ponto: erro amostral.","palavraCritica":"Erro puro"},"comentario":{"resolucao":"ERRADO. O erro decorrente de usar parte da população para inferir o parâmetro é o erro AMOSTRAL. 'Erro puro' é outro conceito (variação experimental em réplicas).","fundamento":"Erros.","macete":"Amostra x população = erro amostral.","erroComum":"Trocar o nome.","comoBancaPensa":"Nome trocado."}},"ES-692":{"cognitivo":{"motivo":"Reconhecer o ponto: voluntários não garantem representatividade.","palavraCritica":"voluntariamente"},"comentario":{"resolucao":"ERRADO. Amostras de voluntários são não probabilísticas e sujeitas a viés de autosseleção; não são, por isso, representativas.","fundamento":"Amostragem.","macete":"Voluntário = viés.","erroComum":"Achar que espontâneo é aleatório.","comoBancaPensa":"Conceito."}},"ES-693":{"cognitivo":{"motivo":"Reconhecer o ponto: não probabilística.","palavraCritica":"arbitrária ou conscientemente"},"comentario":{"resolucao":"CERTO. Na amostragem não probabilística, a seleção depende do julgamento ou da conveniência do pesquisador.","fundamento":"Não probabilística.","macete":"Escolha do pesquisador.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-694":{"cognitivo":{"motivo":"Reconhecer o ponto: alocação uniforme.","palavraCritica":"alocação uniforme"},"comentario":{"resolucao":"CERTO. Os boletins foram divididos por tipo (estratos) e sorteadas quantidades iguais em cada: estratificada com alocação uniforme.","fundamento":"Alocação.","macete":"Iguais em cada estrato = uniforme.","erroComum":"Chamar de proporcional.","comoBancaPensa":"Conceito."}},"ES-695":{"cognitivo":{"motivo":"Reconhecer o ponto: objetivo da estratificação.","palavraCritica":"homogeneização"},"comentario":{"resolucao":"CERTO. Estratificar busca grupos internamente homogêneos quanto à variável de interesse, o que reduz a variância das estimativas.","fundamento":"Estratificação.","macete":"Estrato homogêneo por dentro.","erroComum":"Confundir com conglomerado.","comoBancaPensa":"Conceito."}},"ES-696":{"cognitivo":{"motivo":"Reconhecer o ponto: estratificada proporcional.","palavraCritica":"3 homens e 5 mulheres"},"comentario":{"resolucao":"CERTO. 8 × 15/40 = 3 homens; 8 × 25/40 = 5 mulheres.","fundamento":"Alocação proporcional.","macete":"n·N_h/N.","erroComum":"Erro de conta.","comoBancaPensa":"Conta."}},"ES-697":{"cognitivo":{"motivo":"Reconhecer o ponto: sistemática com início aleatório.","palavraCritica":"sistemática"},"comentario":{"resolucao":"CERTO. Um registro a cada 10, com início aleatório entre os 10 primeiros: amostragem sistemática.","fundamento":"Sistemática.","macete":"Início aleatório + intervalo fixo.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-698":{"cognitivo":{"motivo":"Reconhecer o ponto: veículos = conglomerados.","palavraCritica":"aleatória simples"},"comentario":{"resolucao":"ERRADO. Sortearam-se veículos e entrevistaram-se todos os ocupantes: amostragem por conglomerados (80 veículos), não AAS de 120 pessoas.","fundamento":"Conglomerados.","macete":"Grupo inteiro = conglomerado.","erroComum":"Contar pessoas.","comoBancaPensa":"Troca."}},"ES-699":{"cognitivo":{"motivo":"Reconhecer o ponto: conglomerado não pede amostra acidental.","palavraCritica":"acidental"},"comentario":{"resolucao":"ERRADO. Num plano por conglomerados, o sorteio é probabilístico e, dentro dos conglomerados, faz-se censo ou nova amostragem aleatória — não uma amostra acidental (não probabilística).","fundamento":"Conglomerados.","macete":"Plano probabilístico em todos os estágios.","erroComum":"Misturar com acidental.","comoBancaPensa":"Mistura."}},"ES-700":{"cognitivo":{"motivo":"Reconhecer o ponto: sistemática x estratificada.","palavraCritica":"internamente homogêneos"},"comentario":{"resolucao":"ERRADO. Partição em grupos internamente homogêneos descreve a estratificação. A sistemática seleciona a intervalos fixos numa lista.","fundamento":"Tipos de amostragem.","macete":"Sistemática = intervalo fixo.","erroComum":"Confundir.","comoBancaPensa":"Troca de conceito."}},"ES-701":{"cognitivo":{"motivo":"Reconhecer o ponto: estrato não é unidade.","palavraCritica":"unidade amostral"},"comentario":{"resolucao":"ERRADO. Na estratificada, as unidades amostrais são os elementos sorteados dentro de cada estrato; os estratos são partições da população.","fundamento":"Estratificada.","macete":"Unidade = elemento.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-702":{"cognitivo":{"motivo":"Reconhecer o ponto: alocação uniforme.","palavraCritica":"dividir o tamanho populacional por 10"},"comentario":{"resolucao":"ERRADO. Alocação uniforme divide o tamanho da AMOSTRA igualmente entre os estratos: 170/5 = 34 por estrato. 'Dividir o tamanho populacional por 10' não define alocação.","fundamento":"Alocação.","macete":"Uniforme = n/H por estrato.","erroComum":"Usar o N.","comoBancaPensa":"Regra inventada."}},"ES-703":{"cognitivo":{"motivo":"Reconhecer o ponto: aAS dentro dos estratos.","palavraCritica":"aleatória simples em cada estrato"},"comentario":{"resolucao":"CERTO. Na amostragem aleatória estratificada, faz-se uma AAS independente dentro de cada estrato.","fundamento":"Estratificada.","macete":"AAS em cada estrato.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-704":{"cognitivo":{"motivo":"Reconhecer o ponto: email a todos não é sistemática.","palavraCritica":"sistemática"},"comentario":{"resolucao":"ERRADO. Enviar o formulário a todos e receber respostas voluntárias gera amostra não probabilística (autosseleção), não sistemática.","fundamento":"Tipos de amostragem.","macete":"Resposta voluntária = não probabilística.","erroComum":"Confundir.","comoBancaPensa":"Troca."}},"ES-705":{"cognitivo":{"motivo":"Reconhecer o ponto: alcance de amostra voluntária.","palavraCritica":"limita-se"},"comentario":{"resolucao":"CERTO. Com respostas voluntárias, os resultados valem para quem respondeu; não se generalizam com segurança para toda a população.","fundamento":"Amostragem não probabilística.","macete":"Sem aleatoriedade, sem generalização.","erroComum":"Generalizar.","comoBancaPensa":"Conceito."}},"ES-706":{"cognitivo":{"motivo":"Reconhecer o ponto: oportunidades desiguais.","palavraCritica":"mesma oportunidade"},"comentario":{"resolucao":"ERRADO. Só os advogados cadastrados receberam email; outros usuários dependiam de achar o formulário no site. As chances não foram iguais.","fundamento":"Amostragem.","macete":"Canais diferentes, chances diferentes.","erroComum":"Supor igualdade.","comoBancaPensa":"Termo absoluto."}},"ES-707":{"cognitivo":{"motivo":"Reconhecer o ponto: tamanho não corrige viés.","palavraCritica":"suficiente"},"comentario":{"resolucao":"ERRADO. 1.127 respostas voluntárias não representam todos os usuários: o problema é o viés de seleção, que não se resolve aumentando a amostra.","fundamento":"Amostragem.","macete":"Viés não some com n grande.","erroComum":"Confiar no tamanho.","comoBancaPensa":"Conceito."}},"ES-708":{"cognitivo":{"motivo":"Reconhecer o ponto: fábricas = conglomerados.","palavraCritica":"aleatória simples"},"comentario":{"resolucao":"ERRADO. Sortear fábricas e medir seus trabalhadores é amostragem por conglomerados, não AAS de trabalhadores.","fundamento":"Conglomerados.","macete":"Grupo sorteado = conglomerado.","erroComum":"Chamar de AAS.","comoBancaPensa":"Troca."}},"ES-709":{"cognitivo":{"motivo":"Reconhecer o ponto: alocação de Neyman — vantagens e limites.","palavraCritica":"alocação ótima de Neyman"},"comentario":{"resolucao":"CERTO. Neyman considera tamanho e variabilidade dos estratos; como desvantagens, a amostra não é autoponderada (exige pesos) e as variâncias dos estratos costumam ser desconhecidas.","fundamento":"Alocação de Neyman.","macete":"N_h·σ_h; precisa conhecer σ_h.","erroComum":"Ignorar as limitações.","comoBancaPensa":"Conceito."}},"ES-710":{"cognitivo":{"motivo":"Reconhecer o ponto: áreas sorteadas com censo.","palavraCritica":"conglomerados"},"comentario":{"resolucao":"CERTO. Sortear 10 áreas e entrevistar todos os seus moradores é amostragem por conglomerados.","fundamento":"Conglomerados.","macete":"Grupo inteiro = conglomerado.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-711":{"cognitivo":{"motivo":"Reconhecer o ponto: sistemática e periodicidade.","palavraCritica":"padrão sistemático"},"comentario":{"resolucao":"ERRADO. Se a ordem dos documentos segue um padrão periódico, a sistemática pode coincidir com o ciclo e gerar viés. Ela é adequada justamente quando a ordenação não tem esse padrão.","fundamento":"Sistemática.","macete":"Periodicidade é o risco da sistemática.","erroComum":"Inverter.","comoBancaPensa":"Inverte a condição."}},"ES-712":{"cognitivo":{"motivo":"Reconhecer o ponto: tamanho em conglomerados.","palavraCritica":"3 mil pessoas"},"comentario":{"resolucao":"ERRADO. A unidade amostral é o domicílio: o tamanho da amostra é 1.000 domicílios; as 3.000 pessoas são unidades de observação.","fundamento":"Conglomerados.","macete":"Conte as unidades sorteadas.","erroComum":"Contar pessoas.","comoBancaPensa":"Confusão."}},"ES-713":{"cognitivo":{"motivo":"Reconhecer o ponto: fração amostral.","palavraCritica":"superior a 0,5"},"comentario":{"resolucao":"ERRADO. 1.000 domicílios em 10.000: fração de 0,1.","fundamento":"Fração amostral.","macete":"n/N com a mesma unidade.","erroComum":"Usar pessoas.","comoBancaPensa":"Conta."}},"ES-714":{"cognitivo":{"motivo":"Reconhecer o ponto: subgrupos com AAS = estratificada.","palavraCritica":"estratificada"},"comentario":{"resolucao":"CERTO. Partição em subgrupos semelhantes e AAS em cada um: amostragem estratificada.","fundamento":"Estratificada.","macete":"Partição + AAS em cada parte.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-715":{"cognitivo":{"motivo":"Reconhecer o ponto: definição de AAS.","palavraCritica":"mesma probabilidade"},"comentario":{"resolucao":"CERTO. Na AAS de tamanho n, todas as amostras possíveis são equiprováveis.","fundamento":"AAS.","macete":"Todas iguais.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-716":{"cognitivo":{"motivo":"Reconhecer o ponto: neyman é para estratificada.","palavraCritica":"conglomerados"},"comentario":{"resolucao":"ERRADO. A alocação ótima de Neyman distribui a amostra entre ESTRATOS; não se aplica à amostragem por conglomerados.","fundamento":"Alocação.","macete":"Neyman ↔ estratos.","erroComum":"Confundir.","comoBancaPensa":"Troca."}},"ES-717":{"cognitivo":{"motivo":"Reconhecer o ponto: conveniência.","palavraCritica":"conveniência"},"comentario":{"resolucao":"CERTO. A amostra por conveniência é não probabilística e pode não representar a população.","fundamento":"Não probabilística.","macete":"Conveniência = acessível, não aleatória.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-718":{"cognitivo":{"motivo":"Reconhecer o ponto: unidade = passageiro.","palavraCritica":"unidade amostral"},"comentario":{"resolucao":"ERRADO. O grupo de origem é um estrato; as unidades amostrais são os passageiros sorteados em cada grupo.","fundamento":"Estratificada.","macete":"Estrato ≠ unidade.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-719":{"cognitivo":{"motivo":"Reconhecer o ponto: estratos, não conglomerados.","palavraCritica":"conglomerados"},"comentario":{"resolucao":"ERRADO. Sorteou-se dentro de TODOS os grupos de origem: amostragem estratificada, não por conglomerados.","fundamento":"Estratificada x conglomerados.","macete":"Todos os grupos amostrados = estratos.","erroComum":"Confundir.","comoBancaPensa":"Troca."}},"ES-720":{"cognitivo":{"motivo":"Reconhecer o ponto: turmas = conglomerados.","palavraCritica":"estratificada"},"comentario":{"resolucao":"ERRADO. Sortear 50 turmas e entrevistar todos os alunos delas é amostragem por conglomerados; turma não é estrato.","fundamento":"Conglomerados.","macete":"Grupo inteiro sorteado = conglomerado.","erroComum":"Chamar de estrato.","comoBancaPensa":"Troca."}},"ES-721":{"cognitivo":{"motivo":"Reconhecer o ponto: unidade = turma.","palavraCritica":"escola"},"comentario":{"resolucao":"ERRADO. A unidade amostral (sorteada) é a turma, não a escola.","fundamento":"Unidade amostral.","macete":"O que se sorteia.","erroComum":"Subir de nível.","comoBancaPensa":"Confusão."}},"ES-722":{"cognitivo":{"motivo":"Reconhecer o ponto: alocação proporcional.","palavraCritica":"igual a 25"},"comentario":{"resolucao":"CERTO. Total 8.000; estrato III: 100 × 2.000/8.000 = 25.","fundamento":"Alocação proporcional.","macete":"n·N_h/N.","erroComum":"Erro de soma.","comoBancaPensa":"Conta."}},"ES-723":{"cognitivo":{"motivo":"Reconhecer o ponto: alocação uniforme.","palavraCritica":"3 elementos"},"comentario":{"resolucao":"ERRADO. Uniforme com n = 6 e 3 estratos: 2 elementos por estrato.","fundamento":"Alocação uniforme.","macete":"n/H.","erroComum":"Usar proporção.","comoBancaPensa":"Conta."}},"ES-724":{"cognitivo":{"motivo":"Reconhecer o ponto: estrato não é unidade.","palavraCritica":"unidade amostral"},"comentario":{"resolucao":"ERRADO. Na estratificada, as unidades amostrais são os elementos; cada estrato é um subconjunto da população.","fundamento":"Estratificada.","macete":"Unidade = elemento.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-725":{"cognitivo":{"motivo":"Reconhecer o ponto: alocação proporcional.","palavraCritica":"três elementos do estrato A"},"comentario":{"resolucao":"CERTO. n = 10: A = 10 × 6/20 = 3; B = 10 × 10/20 = 5; C = 10 × 4/20 = 2.","fundamento":"Alocação proporcional.","macete":"n·N_h/N.","erroComum":"Usar Neyman.","comoBancaPensa":"Conta."}},"ES-726":{"cognitivo":{"motivo":"Reconhecer o ponto: erro padrão e tamanho.","palavraCritica":"reduzido a um terço"},"comentario":{"resolucao":"CERTO. EP = σ/√n. Com n 9 vezes maior, √9 = 3: o erro padrão cai a um terço.","fundamento":"Erro padrão.","macete":"EP ∝ 1/√n.","erroComum":"Achar que cai a 1/9.","comoBancaPensa":"Proporção."}},"ES-727":{"cognitivo":{"motivo":"Reconhecer o ponto: σ desconhecido: t, não z.","palavraCritica":"normal padrão"},"comentario":{"resolucao":"ERRADO. Com o desvio padrão AMOSTRAL (s = 30) no denominador, a estatística ȳ/(s/√40) segue t de Student com 39 gl, não a normal padrão (embora se aproxime dela).","fundamento":"Distribuição t.","macete":"s no lugar de σ ⇒ t.","erroComum":"Usar z.","comoBancaPensa":"Troca de distribuição."}},"ES-728":{"cognitivo":{"motivo":"Reconhecer o ponto: erro padrão estimado.","palavraCritica":"inferior a 6"},"comentario":{"resolucao":"CERTO. s² = 44,5 ⇒ s ≈ 6,67; EP = 6,67/√5 ≈ 2,98, inferior a 6.","fundamento":"Erro padrão.","macete":"s/√n.","erroComum":"Usar s.","comoBancaPensa":"Conta."}},"ES-729":{"cognitivo":{"motivo":"Reconhecer o ponto: estimador e tamanho da amostra.","palavraCritica":"independe do tamanho da amostra"},"comentario":{"resolucao":"ERRADO, segundo a banca. O estimador da média é x̄ = ΣXi/n: depende de n em sua definição e, sobretudo, em sua precisão (variância σ²/n).","fundamento":"Estimadores.","macete":"Precisão depende de n.","erroComum":"Ver só a fórmula.","comoBancaPensa":"Conceito."}},"ES-730":{"cognitivo":{"motivo":"Reconhecer o ponto: estimador da média.","palavraCritica":"média aritmética"},"comentario":{"resolucao":"CERTO. O estimador pontual usual da média populacional é a média aritmética amostral.","fundamento":"Estimadores.","macete":"x̄ estima μ.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-731":{"cognitivo":{"motivo":"Reconhecer o ponto: desvio padrão de x̄.","palavraCritica":"σ/n"},"comentario":{"resolucao":"ERRADO. E(μ̂n) = μ está correto, mas √Var(μ̂n) = σ/√n, e não σ/n.","fundamento":"Distribuição da média amostral.","macete":"DP de x̄ = σ/√n.","erroComum":"Esquecer a raiz.","comoBancaPensa":"Erro de fórmula."}},"ES-732":{"cognitivo":{"motivo":"Reconhecer o ponto: dP da média amostral.","palavraCritica":"igual a 32"},"comentario":{"resolucao":"ERRADO. DP(ȳ) = 32/√16 = 8, não 32.","fundamento":"Erro padrão.","macete":"σ/√n.","erroComum":"Usar σ.","comoBancaPensa":"Erro clássico."}},"ES-733":{"cognitivo":{"motivo":"Reconhecer o ponto: média amostral e mediana.","palavraCritica":"mediana populacional"},"comentario":{"resolucao":"CERTO. E(ȳ) = μ = 10, e na normal a mediana coincide com a média.","fundamento":"Esperança da média.","macete":"Normal: média = mediana.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-734":{"cognitivo":{"motivo":"Reconhecer o ponto: padronização com EP = 1.","palavraCritica":"normal padrão"},"comentario":{"resolucao":"CERTO. EP = 12/√144 = 1. Assim, x̄ − μ tem média 0 e desvio padrão 1: normal padrão.","fundamento":"Distribuição da média.","macete":"Divida por EP; aqui EP = 1.","erroComum":"Achar que falta dividir.","comoBancaPensa":"Caso especial."}},"ES-735":{"cognitivo":{"motivo":"Reconhecer o ponto: correção para população finita.","palavraCritica":"inferior a 0,04"},"comentario":{"resolucao":"CERTO. Sem reposição: Var(X̄) = (σ²/n)·(N − n)/(N − 1) = (4/100) × 900/999 ≈ 0,036, inferior a 0,04.","fundamento":"Amostragem sem reposição.","macete":"Fator (N − n)/(N − 1).","erroComum":"Esquecer a correção (0,04).","comoBancaPensa":"Limite exato."}},"ES-736":{"cognitivo":{"motivo":"Reconhecer o ponto: média das médias amostrais.","palavraCritica":"4,75"},"comentario":{"resolucao":"CERTO. A média da distribuição das médias amostrais é a média da população: (2 + 4 + 5 + 8)/4 = 4,75.","fundamento":"Distribuição amostral.","macete":"E(x̄) = μ.","erroComum":"Calcular amostra por amostra.","comoBancaPensa":"Atalho."}},"ES-737":{"cognitivo":{"motivo":"Reconhecer o ponto: variância das médias.","palavraCritica":"1,173"},"comentario":{"resolucao":"ERRADO. Com reposição e n = 2, Var(x̄) = σ²/2. Se Var(x̄) ≈ 2,345, então σ² ≈ 4,69 (o dobro), não a metade (1,173).","fundamento":"Distribuição amostral.","macete":"Var(x̄) = σ²/n.","erroComum":"Inverter a relação.","comoBancaPensa":"Inversão."}},"ES-738":{"cognitivo":{"motivo":"Reconhecer o ponto: erro padrão.","palavraCritica":"igual a σ"},"comentario":{"resolucao":"ERRADO. O erro padrão da média amostral é σ/√n.","fundamento":"Erro padrão.","macete":"σ/√n.","erroComum":"Usar σ.","comoBancaPensa":"Erro clássico."}},"ES-739":{"cognitivo":{"motivo":"Reconhecer o ponto: variância estimada da média (Poisson).","palavraCritica":"1,25"},"comentario":{"resolucao":"CERTO. Média amostral = 5; na Poisson, Var(X) = λ, estimada por 5. Var(x̄) = 5/4 = 1,25.","fundamento":"Distribuição amostral.","macete":"Var(x̄) = λ/n.","erroComum":"Usar a variância amostral.","comoBancaPensa":"Propriedade."}},"ES-740":{"cognitivo":{"motivo":"Reconhecer o ponto: padronização incompleta.","palavraCritica":"normal padrão"},"comentario":{"resolucao":"ERRADO. μ̂ − μ tem desvio padrão σ/√10; dividir só por σ não padroniza (o DP resultante é 1/√10).","fundamento":"Distribuição da média.","macete":"Divida por σ/√n.","erroComum":"Esquecer o √n.","comoBancaPensa":"Fórmula incompleta."}},"ES-741":{"cognitivo":{"motivo":"Reconhecer o ponto: erro padrão.","palavraCritica":"inferior a 0,5"},"comentario":{"resolucao":"CERTO. EP = 3/√100 = 0,3 dia, inferior a 0,5.","fundamento":"Erro padrão.","macete":"σ/√n.","erroComum":"Usar σ.","comoBancaPensa":"Conta."}},"ES-742":{"cognitivo":{"motivo":"Reconhecer o ponto: variância da média.","palavraCritica":"igual a 100"},"comentario":{"resolucao":"ERRADO. Var(x̄) = σ²/n = 100/n, não 100 (salvo n = 1).","fundamento":"Distribuição da média.","macete":"σ²/n.","erroComum":"Esquecer n.","comoBancaPensa":"Erro clássico."}},"ES-743":{"cognitivo":{"motivo":"Reconhecer o ponto: média amostral é normal.","palavraCritica":"t de Student"},"comentario":{"resolucao":"ERRADO. De população normal, x̄ é normal (média 10, variância 100/n). A t aparece na estatística padronizada com s no lugar de σ.","fundamento":"Distribuição da média.","macete":"x̄ normal; (x̄ − μ)/(s/√n) ~ t.","erroComum":"Confundir.","comoBancaPensa":"Troca de distribuição."}},"ES-744":{"cognitivo":{"motivo":"Reconhecer o ponto: simetria da média.","palavraCritica":"≤0,5"},"comentario":{"resolucao":"CERTO. x̄ é normal com média 10: P(x̄ − 10 > 0) = 0,5, que satisfaz ≤ 0,5.","fundamento":"Distribuição da média.","macete":"Simetria.","erroComum":"Achar que precisa ser < 0,5.","comoBancaPensa":"Limite."}},"ES-745":{"cognitivo":{"motivo":"Reconhecer o ponto: padronização correta.","palavraCritica":"normal padrão"},"comentario":{"resolucao":"CERTO. 0,1(X̄ − 10)√n = (X̄ − 10)/(10/√n): média subtraída e divisão pelo erro padrão. Segue N(0, 1).","fundamento":"Padronização.","macete":"(x̄ − μ)/(σ/√n).","erroComum":"Não reconhecer a forma.","comoBancaPensa":"Forma disfarçada."}},"ES-746":{"cognitivo":{"motivo":"Reconhecer o ponto: esperança da média.","palavraCritica":"igual a 10"},"comentario":{"resolucao":"CERTO. E(x̄) = μ = 10.","fundamento":"Distribuição da média.","macete":"Não viesada.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-747":{"cognitivo":{"motivo":"Reconhecer o ponto: não viés da média.","palavraCritica":"igual à média populacional"},"comentario":{"resolucao":"CERTO. A média amostral é estimador não viesado: E(x̄) = μ.","fundamento":"Estimadores.","macete":"E(x̄) = μ.","erroComum":"Confundir.","comoBancaPensa":"Conceito."}},"ES-748":{"cognitivo":{"motivo":"Reconhecer o ponto: estatística t.","palavraCritica":"15 graus de liberdade"},"comentario":{"resolucao":"CERTO. (m − 1,8)/(s/√16) = (m − 1,8)/(s/4) segue t de Student com n − 1 = 15 gl (população normal, σ desconhecido).","fundamento":"Distribuição t.","macete":"s no lugar de σ ⇒ t com n − 1.","erroComum":"Usar 16 gl.","comoBancaPensa":"Conceito."}},"ES-749":{"cognitivo":{"motivo":"Reconhecer o ponto: erro padrão.","palavraCritica":"igual a 0,5"},"comentario":{"resolucao":"CERTO. s = √4 = 2; EP = 2/√16 = 0,5.","fundamento":"Erro padrão.","macete":"s/√n.","erroComum":"Usar a variância.","comoBancaPensa":"Conta."}}});
